pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, but with non-linear saturation
    let mut score = (norm_pr.powf(1.4)) * cap;

    // Smooth coupling: as stream progresses, penalize residual more strongly
    let progress_weight = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_weight;

    // Non-linear interaction of post_residual with mean residual deviation
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * cap - 6.0 * dev * cap;

    // Reward tight fits (small post residual relative to item)
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin bonus (avoid opening new bins needlessly)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
    }

    // New-bin candidate: penalize opening bins early, allow late in stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 - progress);
        // discourage new bin if any open bin fits well
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 25.0;
        }
    }

    // Small bonus for perfectly filling a bin
    if post_residual == 0 {
        score -= 10.0;
    }

    // Mild penalty scaling with open bins count to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: eliminate score entirely for exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size (chained perfect fill), penalize near-misses that
    // leave dead space unusable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0; // chain: this bin becomes perfect for next item
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to slack
            score -= 0.5 * (post - nxt);
        } else {
            // next item cannot use this bin's leftover: penalize dead space,
            // worse when the leftover is small (unusable fragment)
            let frag = post / 100.0;
            score += 40.0 * (1.0 - frag);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or open bins are crowded; otherwise penalize
    // opening new bins to keep existing residual capacity utilized.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_fit = mean_residual / bin_capacity as f64;
        score = 50.0
            - 60.0 * fill_frac      // large items deserve fresh bins
            - 30.0 * pressure       // many open bins -> consolidate less
            + 40.0 * mean_fit;      // high mean residual -> reuse open bins
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can also host the next item
        }
    }

    // Mild global pressure: tighten scoring late in the stream to avoid
    // fragmenting residual capacity when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / 100.0) * 10.0;

    // Prefer bins tighter than the mean residual (compact packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // plausible future item (<= 10) are nearly worthless -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < item_size.min(20) {
        // Gaps smaller than the current item's class are likely dead space too.
        score += 25.0;
    }

    // Reward tight fits: post_residual close to zero is good (subtract).
    let tightness = 1.0 - (post / cap);
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0; // chain fit leaves no dead space
        } else {
            score -= 10.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement creates a gap the next item cannot use.
        score += 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight fit exists elsewhere.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual < 10 {
            score += 60.0; // but dead space still dominates
        }
    }

    // New-bin candidate: make it attractive only when all open fits are poor.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // baseline = residual left in fresh bin
        if fitting_bins_count > 0 {
            // Only prefer a new bin if every existing fit would leave dead space.
            score += 5.0; // slight handicap so decent fits win
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host current + next item
        }
    }

    // Mild stream-phase modulation: early on, keep options open.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - phase) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are penalized heavily.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 * (min_useful as f64 - post_residual as f64);
    }

    // Dead space relative to the next item's needs (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Reward tight fits: post_residual near zero (but usable) is great.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect fit into a fresh bin is ideal.
    if bin_residual == bin_capacity && post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the next item when it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: penalize spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin before opening a new one: strong bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight nudge toward bins with below-average residual (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Early in the stream, allow opening bins more freely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are nearly unusable
    // since items are >= 1 but practical waste concentrates in tiny gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual was large relative to mean (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using a bin when it's the only fitting option (last chance).
    score += open_bins_count as f64 * 0.5;
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // Base new-bin cost; offset if lookahead item would fit the leftover
        // of a placement here poorly anyway.
        score = 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Opening a bin lets next item also land here: strong bonus.
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Placement leaves a gap the next item cannot use: penalize.
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover is reusable by the lookahead item: reward.
        score -= 10.0;
    }

    // Late-stream tightening: as the stream progresses, avoid creating
    // fragmented residuals, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap too small for the minimum item -> dead space, big penalty
        score += (10.0 - pr) * 8.0;
    } else if pr == 0.0 {
        // perfect fit: strong reward
        score -= 25.0;
    } else if pr < 20.0 {
        // awkward small gap that only fits a few item sizes
        score += (20.0 - pr) * 2.5;
    }

    // Reward tight fits relative to bin residual (waste ratio)
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 12.0;
    }

    // If next item can use the post_residual, reward leaving exactly that gap
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0; // leaves room perfectly for lookahead item
        } else if post_residual >= next_item_size {
            score -= 4.0; // next item still fits here
        } else {
            score += 3.0; // next item won't fit in the leftover
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if this bin is much emptier than average, prefer filling it
    score -= (mean_residual - pr).max(-50.0).min(50.0) * 0.3;

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad gap
    if bin_residual == bin_capacity {
        // baseline competitiveness of a fresh bin
        score = (bin_capacity - item_size) as f64 + 10.0;
        if post_residual < 10.0 {
            score -= 20.0; // item nearly fills a fresh bin -> great to open new bin
        }
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    }
    // Residuals that can only fit a narrow band of items are semi-dead space.
    if post_residual >= 10 && post_residual < 25 {
        score += 30.0 + (25 - post_residual) as f64 * 2.0;
    }

    // Perfect or near-perfect fits are highly rewarded.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 - (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; if this bin becomes near-dead, penalize.
            if post_residual < 20 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new ones; with few open bins, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins; penalize proportionally, but relax when the
    // current fit would create dead space anyway.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.8;
        if post_residual < 25 && post_residual > 0 {
            score -= 10.0; // still better than fragmenting an open bin badly
        }
    }

    // Slight preference for tighter bins overall (small residual before placement).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powf(6.0);

    // Penalize dead space: post_residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64).powf(3.0);
        } else {
            // Next item can't follow here; mild penalty scaled by gap.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin is attractive only when fits are bad.
    if bin_residual == bin_capacity {
        // Neutral-ish base; penalize slightly when good fits exist elsewhere.
        score += 10.0;
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Few open bins -> new bin less costly.
        score -= 2.0 * open_bins_count as f64;
    } else {
        // Reward using already-open bins, more so when many are open.
        score -= 0.2 * open_bins_count as f64;
        // Prefer bins below mean residual (consolidating emptier bins).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: as stream progresses, tighten everything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Any post_residual below the minimum item size (1) is impossible here,
    // but tiny residuals (< ~20) are hard to fill later -> quadratic penalty.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * (20.0 - pr) * 1.5;
        } else if pr < 35.0 {
            score += (35.0 - pr) * 0.8;
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via its large residual, but
    // add explicit pressure scaled by open_bins_count).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mild reward proportional to how well residual is used.
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a residual that wastes space.
        score += (post_residual as f64) * 0.5;
    }

    // Mean residual coupling: if this bin is much emptier than average,
    // prefer packing here to consolidate open space.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: residuals in [1, 9] are nearly unusable
    // (min item size is 1, but statistically small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Residuals in [10, 25] are partially usable: mild penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current item + next item can
    // combine nicely, or open bins are crowded / fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // If the next item fits together with the current one in a fresh
        // bin, opening is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 55.0;
        }
        // Many open bins with low mean residual -> prefer packing into them.
        if open_bins_count > 0 && mean_residual < item_size as f64 * 1.3 {
            score += 30.0;
        }
    } else {
        // Favor bins whose residual can still host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Prefer tighter bins (less waste of large residual).
        score += (bin_residual as f64 - item_size as f64) * 0.05;
        // Open-bin pressure: with many open bins, discourage spreading.
        score += open_bins_count as f64 * 0.8;
    }

    // Early stream: be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
