    }

    // Tightness reward scaled by fraction of bin consumed.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Pressure to close bins: more open bins -> prefer filling existing ones.
    score += 4.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item almost fits, slight penalty for leaving an awkward gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins with residuals close to the item (minimize waste relative to mean).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    // Mild preference to use existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
