}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with polynomial sharpening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr) + 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (nxt - pr).abs() / cap) * (1.0 - progress);
        }
    }

