    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Reward tight fits non-linearly
    score -= 15.0 * fit * (1.0 - norm_pr) * (1.0 - norm_pr);

    // New-bin candidate: neutral-ish baseline, penalized early, relaxed late
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * (1.0 - progress) * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

