    if fitting_bins_count == 1 {
        score -= 20.0;
        // Extra urgency when the bin would be nearly emptied.
        if post_residual <= sixth {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so new bins are used sparingly; relax late in the stream or with many open bins.
        score += 40.0 - 0.3 * open_bins_count as f64 - 20.0 * progress;
        // If the item is huge, a fresh bin is more attractive (avoids awkward splits).
        if item_size >= 2 * third {
            score -= 15.0;
        }
        // If mean residual across open bins is small (fragmented), opening new bin is less bad.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Mild preference for tighter fits among comparable residuals.
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for any item, min size 1..100 range)
    // treat gaps below 10 as fully dead (worst), gaps 10..=30 as risky.
    if post_residual < 10 {
        score += 200.0; // totally wasted space
    } else if post_residual <= 30 {
        score += 60.0 + 2.0 * (30 - post_residual) as f64;
    } else {
        // reward leaving gaps that can still host typical items
        score -= 0.5 * post_residual as f64;
    }

    // Dead space is only acceptable if it exactly matches the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0; // perfect next-fit slot
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0; // next item still fits
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (new empty bin candidate gets penalized proportionally to open count)
    if bin_residual == bin_capacity {
        score += 80.0 + 15.0 * open_bins_count as f64;
    } else {
        score -= 5.0; // mild preference for filling existing bins
    }

    // Prefer bins with residual below mean (tighter bins get filled first)
    if bin_residual < bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits into the leftover with small waste.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 1.5;
    }
    // Next item cannot use the leftover: penalize proportionally to wasted capacity.
    else if next_item_size > post_residual {
        let waste = post_residual as f64;
        score += waste * 0.8;
    }

    // Reward tight fits relative to the mean residual of open bins.
    let tightness = (post_residual as f64 - mean_residual).abs();
    score -= tightness * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable dead space (unless it matches next item).
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 15.0;
    }

    // Late in the stream, prefer closing bins out (lower residual wins more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize leaving dead space that few future items could use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - t); // small gaps are worse early (long horizon to regret)
    }

    // Lookahead: if next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // next item can't use the leftover: penalize proportionally to waste
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin where the item fits most snugly
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of opening a new bin, discounted late in the stream.
        score += 40.0 - 15.0 * t;
        // Open a new bin when no open bin fits, or when existing fits are loose.
        if pressure > 0.0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host a sequence of large items
        }
    } else {
        // Slightly favor bins with lower residual (tighter bins) for tight packing.
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Global state: many open bins -> prefer filling existing ones.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;
    }

    // Mild preference for using larger items to fill larger residual bins.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize residual, weighted non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling: residual^2 interaction with progress
    score += 2.0 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.3 + progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            // reward leaving space exactly usable by next item
            score -= 10.0 * (1.0 - ((pr - nx) / cap).abs().min(1.0)) * (0.2 + progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight preference to fill bins below mean residual (balance consolidation)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Deter new-bin opening unless residual is truly large relative to item
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress) - 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small dead space"
    // classes (very low remainders) are strongly preferred — waste is minimized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let post_frac = post / cap;

    // Class A: post_residual <= 10 -> near-perfect fill, big reward.
    if post_residual <= 10 {
        score -= 40.0;
    }
    // Class B: post_residual in 11..=20 -> good fill.
    else if post_residual <= 20 {
        score -= 18.0;
    }
    // Class C: post_residual in 21..=35 -> acceptable.
    else if post_residual <= 35 {
        score -= 6.0;
    }
    // Class D: post_residual > 60 -> large dead space unless it can host the next item.
    else if post_residual > 60 {
        score += 10.0;
    }

    // Modulo coupling: post_residual divisible by common item-size granularities
    // (5, 10) tends to be reusable by future items; reward such "harmonic" remainders.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover will shrink further; penalize less.
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
            // Harmonic bonus: next item leaves a round remainder.
            if next_post % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's leftover: dead-space risk scales with size.
            score += (next_item_size as f64).min(80.0) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream when
    // open bins are still relatively empty; allow it later or when mean residual
    // across open bins is small (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = 1.0 - (mean_residual / cap);
        let open_penalty = (open_bins_count as f64) * 1.5;
        score = cap * 0.35 + open_penalty + (1.0 - progress) * 15.0 - fragmentation * 10.0;
        // Never open a new bin when a near-perfect fit exists elsewhere:
        if fitting_bins_count >= 1 && (item_size as f64) / cap > 0.85 {
            score += 25.0;
        }
    }

    // Mild tie-break: prefer bins with residual closest to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 5.0;

    // Slight preference toward fewer open bins (consolidation).
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no future item (min size 1..)
    // can practically fill are heavily penalized, especially tiny unusable slivers.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Dead space zone: gaps below the smallest plausible item size.
        let dead_threshold = 10.0_f64.min(pr);
        if pr < 10.0 {
            // Unusable sliver: punish far beyond its nominal size.
            score += (10.0 - pr) * 6.0;
        }
        // Smooth dead-space penalty proportional to how "wasted" the gap is
        // relative to the bin capacity (fragmentation pressure).
        score += (pr / bin_capacity as f64).powf(2.0) * 30.0;
        let _ = dead_threshold;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 20.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few are open,
    // but encourage using existing bins when many are open (avoid new-bin churn).
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when the
    // item fits poorly everywhere else. A fresh bin has perfect residual, but
    // opening it while good fits exist is wasteful.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and
        // current mean residual (high mean residual = existing space is usable).
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3 - progress * 10.0;
        // If lookahead item is large, a fresh bin paired with it may be fine;
        // slight discount when next item is big.
        if next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward this placement strongly (creates a perfect follow-up slot).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits in the gap: mild bonus scaled by fill ratio.
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base pressure: prefer tight fits (small post_residual).
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let match_quality = 1.0 - (pr - nxt) / bin_capacity as f64;
            score -= 30.0 * match_quality * match_quality;
        } else {
            // Next item cannot use this leftover: dead-space penalty.
            score += 0.5 * pr;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce space;
    // using them for a tight fit is valuable.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 10.0 * rel * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better
    // than all existing placements (e.g. early stream or huge leftover would form).
    if bin_residual == bin_capacity {
        score += 45.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the item leaves a large hole and no open bin fits well, opening is fine.
        if post_residual as f64 > 0.5 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference to fill older/more-open-bin situations to cap bin count.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize creating small unusable dead space (< smallest item ~10).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count >= 2 {
        // many alternatives: prefer the best fit, add mild noise-free spread
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin only when existing bins are poor fits or few remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64 / bin_residual.max(1) as f64) < 0.5;
        let few_options = fitting_bins_count <= 1;
        if poor_fit || few_options {
            score -= 20.0 + 10.0 * progress;
        } else {
            // discourage opening new bins when decent fits exist
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Global state: if mean residual is high, prefer filling bins with large
    // residuals less aggressively (spread load) — mild coupling.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Late-stream consolidation: as stream progresses, favor existing bins
    // to avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth polynomial coupling to progress.
    // Late in the stream, residual waste matters more (no future to amortize it).
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear quadratic coupling: penalize mid-range residuals that are hard to fill,
    // scaled by remaining stream length (early stream => more future => less penalty).
    let quad = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 30.0 * quad * (1.0 - progress);

    // Lookahead: reward bins whose post_residual can host the next item (smooth soft-match).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n) / cap;
        let soft = (-diff * diff * 40.0).exp();
        score -= 12.0 * soft * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when this bin's residual deviates far from the mean residual
    // (prefer keeping residuals homogeneous for future pairing).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Slight bias toward filling already-open bins vs. opening new ones early.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify by capacity fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 10.0).floor(); // 0..10 harmonic class

    // Reward residuals that belong to "useful" classes (small residual = tight fit).
    // Classes 0 (<=10% left) and 1 are excellent; mid classes (4..7) are dead space.
    match class as u32 {
        0 => score -= 18.0,
        1 => score -= 12.0,
        2 => score -= 6.0,
        3 => score -= 1.0,
        4 | 5 => score += 6.0,
        6 | 7 => score += 10.0,
        _ => score -= 2.0, // near-empty bin: fine, still flexible
    }

    // Integer-division threshold: post_residual divisible structure.
    // Residuals that are multiples of small sizes (e.g. %10, %20) are reusable.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible, reward proportionally to tightness.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 10.0 + 12.0 * chain_tightness;
        } else {
            // Next item won't fit here: penalize more if we waste a big residual.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Harmonic class of next item vs residual class (modulo-style matching).
        let next_class = (next_item_size as f64 / cap * 10.0).floor() as u32;
        if (next_class + class as u32) % 3 == 0 {
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (bin consolidation pressure).
    score -= (bin_residual as f64 / cap) * open_bins_count as f64 * 0.4;

    // Late in stream: tighten packing, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.05 * progress;

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 20.0 + mean_residual * 0.1; // discourage opening when fits exist
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a good sink.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (< 10) are the worst outcome: heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that are small relative to typical items (1..20) are risky dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward tight fits relative to the bin: smaller post_residual as fraction
    // of capacity gets a bonus (non-linear, quadratic emphasis).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // --- Last-chance pressure ---
    // If this is the only bin that fits, strongly prefer using it over
    // opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // --- Open-bin pressure ---
    // With many open bins, discourage spreading; with few open bins,
    // allow opening a new one for large items.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * open_pressure;

    // New-bin candidate: only attractive when item is large or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins when existing bins could handle it well.
        let mut nb = 30.0 + 40.0 * (1.0 - item_frac) + 20.0 * progress;
        // But if the fit elsewhere is dead-space prone (post_residual small but
        // nonzero), a new bin becomes competitive.
        if post_residual > 0 && post_residual < 15 && bin_residual < bin_capacity {
            nb -= 45.0;
        }
        score += nb;
    }

    // --- Lookahead: penalize placements that strand the next item ---
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            // Gap too small for next item: dead space for the future.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Gap accommodates next item: reward proportional fit.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        }
    }

    // Mild preference for bins below mean residual (keeps spread balanced).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 30.0; // perfect pair
        } else {
            score -= 18.0 * (1.0 - (next_fit_gap as f64) / (bin_capacity as f64));
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space proportionally to how big it is.
        let dead = (post_residual as f64).min(next_item_size as f64);
        score += 0.35 * dead;
    }

    // Compare post_residual against mean residual: avoid making this bin much worse than average.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.08 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && item_size >= 70 {
            score -= 10.0; // big item: fresh bin is attractive
        }
    }

    // Early stream: be slightly conservative, keep bins balanced.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to capacity)
    let tightness = post_residual as f64 / cap;
    score += tightness * tightness * 40.0;

    // Penalize bins whose residual is much larger than needed (wasteful big bins used early)
    let waste_ratio = (bin_residual - item_size) as f64 / cap;
    score -= waste_ratio * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits perfectly into post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty proportional to leftover dead space
            score += post_residual as f64 * 0.15;
        }
    }

    // Penalize creating very small unusable residuals (< 10 units dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Global state coupling: when mean residual across open bins is low, opening
    // new bins is cheap; when mean residual is high, prefer filling existing bins.
    let mean_gap = mean_residual - item_size as f64;
    if mean_gap > 0.0 {
        score -= mean_gap * 0.3;
    } else {
        score += (-mean_gap) * 0.3;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin early in stream or when open bins are few; penalize
        // opening new bins when many bins are open with slack available.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 * 3.0;
        score += 20.0 + open_pressure - progress * 15.0;
        // If no existing bin can fit the item, new bin is forced anyway (score irrelevant),
        // but if alternatives exist, make new bin slightly unattractive unless item is huge.
        if item_size > 70 {
            score -= 15.0;
        }
    }

    // Mild preference for bins with residual close to item size (best-fit flavor)
    let fit_gap = (bin_residual - item_size) as f64;
    score += fit_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Normalize post_residual and bin_residual to [0,1]
    let pr = post_residual as f64 / bin_capacity as f64;
    let br = bin_residual as f64 / bin_capacity as f64;

    // Smooth non-linear penalty on dead space, weighted by stream progress:
    // early on, waste is cheap; later, tight packing matters more.
    let dead_weight = 0.5 + 1.5 * progress * progress;
    score += dead_weight * (pr * pr) * bin_capacity as f64;

    // Reward near-perfect fills (post_residual small relative to capacity)
    score -= (1.0 - pr) * (1.0 - pr) * 20.0 * (0.5 + progress);

    // Penalize bins whose residual diverges from mean residual (imbalance)
    let imbalance = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * imbalance * imbalance * (1.0 - progress);

    // Smooth interaction: how well the NEXT item could use the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr * bin_capacity as f64 - ns).abs();
        let norm_gap = fit_gap / bin_capacity as f64;
        // If next item fits almost exactly into post_residual, strongly reward
        score -= 15.0 * (1.0 - norm_gap) * (1.0 - norm_gap) * (1.0 - progress * 0.5);
    } else {
        // Last item: prefer bins that end with minimal leftover
        score += 10.0 * pr;
    }

    // Last-chance bin: if this is the only bin that fits, penalize opening new bins mildly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - pr * pr);
    }

    // New-bin candidate: encourage opening a fresh bin only when current bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        let new_bin_bonus = 25.0 * (1.0 - crowding) + 20.0 * fullness * progress;
        score += new_bin_bonus;
    }

    // Mild coupling: prefer placing larger items into fuller bins
    let fill_ratio = 1.0 - br;
    score -= 5.0 * fill_ratio * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Penalize leftovers in "dead zones" that few item sizes can fill.
    // Classes (harmonic thresholds at 1/4, 1/2, 3/4 of capacity):
    if post_residual == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else if frac <= 0.25 {
        score += 12.0; // tiny sliver: likely dead space
    } else if frac <= 0.5 {
        score -= 6.0; // half-ish leftover: very reusable
    } else if frac <= 0.75 {
        score -= 2.0; // decent leftover
    } else {
        score += 0.0; // large leftover: neutral, bin still roomy
    }

    // Modulo class: leftovers divisible by common item sizes (10..80 multiples of 10)
    // are more reusable. Reward post_residual that is a multiple of 10.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: does the next item fit exactly in the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 8.0; // next item still fits here
        } else {
            score += 6.0; // next item won't fit: this bin may strand
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to mean residual, or open bins are already numerous.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / cap;
        let crowding = (open_bins_count as f64) / ((open_bins_count as f64) + 4.0);
        let late = (step_index as f64) / ((total_items as f64) + 1.0);
        // Base cost of a fresh bin; reduced when item is big, bins are crowded, or stream is late.
        score = cap * (1.0 - 0.35 * pressure - 0.3 * crowding - 0.2 * late);
        if next_item_size > 0 && next_item_size as f64 <= cap * 0.5 {
            score += 5.0; // next item may prefer an existing roomy bin
        }
    }

    // Slight preference for filling bins below the mean residual (tighter bins first).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space avoidance: small unusable gaps are the worst outcome.
    // Gaps below the minimum plausible item size (<= 10) are dead space.
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual <= 20 {
        score += 120.0;
    } else if post_residual <= 40 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover: leftover is likely dead space.
        score += 80.0;
    } else if next_item_size > 0 && post_residual - next_item_size < 10 {
        // Next item leaves another dead gap.
        score += 60.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 2.0;

    // Slight preference for fuller bins relative to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post-residual matches the next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;
        // perfect chain fit: this item leaves exactly the space the next item needs
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // next item fits in the leftover with room to spare is fine; near-miss is bad
        if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 8.0;
        }
    } else {
        // last item: just minimize leftover
        score += 0.0;
    }

    // Penalize unusable dead space (residual too small for any item)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer bins whose residual is below the mean (tighter packing first)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline penalty so existing bins win ties,
    // but relaxed when the stream is early and few bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 5.0 + 10.0 * (1.0 - progress) / openness;
        // If no existing bin leaves a good chain fit, opening fresh is attractive
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (small post residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for near-perfect two-item packing.
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    score += (open_bins_count as f64) * 0.8;

    // Bin far below mean residual (relatively empty): slight penalty to keep
    // emptier bins free for awkward future items.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual + 20.0 {
        score += (residual_f - mean_residual) * 0.15;
    } else if residual_f < mean_residual - 20.0 {
        score -= (mean_residual - residual_f) * 0.1;
    }

    // Time horizon: early in the stream, be conservative about opening new bins;
    // late in the stream, prefer tight fits even more (final packing matters).
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= progress * 8.0 * tightness;
    score += (1.0 - progress) * 4.0;

    // Empty new-bin candidate: make it attractive only when it's genuinely better
    // than cramming (large item into crowded state).
    if bin_residual == bin_capacity {
        score += 6.0;
        if item_size > bin_capacity / 2 && (fitting_bins_count as f64) <= 1.0 {
            score -= 20.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex so small dead space is tolerated
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in stream -> dead space matters more, so penalize residual quadratically
    let coupling = norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0);
    score += 12.0 * coupling;

    // Late-stream urgency: penalize residual more as stream completes
    score += pr * 0.5 * progress * progress;

    // Lookahead: reward if next item fits into post residual (smooth sigmoid-like term)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 20.0 * (1.0 - (-fits * 8.0).exp());
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Mean residual context: prefer bins deviating from mean (tighter bins)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, slightly penalized early, competitive late
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.25 * progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (post_residual % 10 == 0) are golden.
    let post = post_residual as u32;
    let residue_class = post % 10;
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if residue_class == 0 {
        score -= 25.0; // decile-aligned residual, likely reusable by 10-multiples
    } else if residue_class <= 3 {
        score += 8.0 + 2.0 * residue_class as f64; // tiny dead space penalty
    }

    // Dead-space zone: residuals too small for the smallest plausible next item.
    if post > 0 && post < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post {
            let slack = post - next_item_size;
            score -= 18.0 + slack as f64 * 0.4;
            // harmonic bonus if the chain keeps decile alignment
            if slack % 10 == 0 { score -= 8.0; }
        } else {
            // next item cannot fit here; penalize proportionally to overshoot
            score += 12.0 + (next_item_size - post) as f64 * 0.25;
        }
    } else {
        // last item: prefer tightest packing overall
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Many open bins: discourage fragmenting further; prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += crowding * 1.5;

    // Deviation from mean residual: prefer bins below mean (tighter bins get filled).
    let dev = post as f64 - mean_residual;
    score += dev * 0.3;

    // Integer-division threshold on fill fraction: quarters of capacity.
    let quarter = (post as f64 / (cap / 4.0)).floor();
    score -= quarter * 3.0;

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or nothing sensible fits elsewhere.
    if bin_residual == bin_capacity {
        if item_size as f64 > 0.6 * cap || fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min item size 1, but practically tiny gaps < 12)
    // are pure waste. Penalize them heavily and non-linearly.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 * (12.0 - post_residual as f64) / 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward tight fits proportionally to how much of the bin is used.
        let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fill * fill;
    }

    // If the next item fits exactly in the post residual, big bonus
    // (chain a second item into the same bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the known next item.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: discourage spreading across many bins when the
    // fit is loose; encourage using existing bins when many are open.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below the mean residual (tighter bins) slightly.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when current fit would leave
    // unusable dead space; otherwise keep item in open bins.
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual < 12 && post_residual > 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills leftover space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-item completion of this bin.
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item can also go here; prefer bins where it fits snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack * 0.4;
        } else {
            // Next item cannot fit here; penalize leftover dead space that is too small.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when the
    // current bin would leave a very awkward sliver.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = post_residual > 0 && post_residual < 10;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 200.0; // fresh bin + next item completes it perfectly
        }
        if awkward {
            score -= 30.0;
        }
        // Later in the stream, prefer reusing open bins: penalize new bins more.
        score += progress * 40.0;
        if open_bins_count > 0 && !awkward {
            score += 25.0;
        }
    }

    // Slight penalty for leaving residuals that are prime awkward sizes (1..9).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post-residuals that are too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit;
        } else {
            // Post-residual too small for the next item: mild penalty for fragmentation.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Discourage opening new bins when good alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin penalty grows with number of open bins and mean residual availability.
        let waste = mean_residual - item_size as f64;
        score += 55.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        if waste > 0.0 {
            score += 0.5 * waste;
        }
        // Late in the stream, avoid scattering items across new bins.
        if progress > 0.8 {
            score += 30.0 * progress;
        }
    } else {
        // Mild reward for using existing bins with above-average residual (consolidation).
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // Prefer balancing residuals: bins far below mean residual are less attractive.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) + norm_pr * norm_pr * norm_pr * (1.0 + 3.0 * t * t);
    score += 40.0 * poly;

    // Reward tight fits, stronger later in the stream
    score -= 25.0 * norm_item * norm_item * (0.5 + t);

    // Dead space penalty: small post_residual that is unusable
    if norm_next > 0.0 {
        let unusable = if norm_next > norm_pr { (norm_next - norm_pr).powi(2) } else { 0.0 };
        score += 15.0 * unusable * (1.0 + t);
    }

    // Last-chance bonus: prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Mild pressure from mean residual and open bin count
    score += 0.05 * (mean_residual - pr);
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize slightly so it's only chosen when others are poor
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 + t) + norm_next * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the leftover space: residues divisible by 10 are
    // "harmonic" (likely to be exactly filled by future items in a 1..100
    // integer stream); odd/prime-ish residues are dead-space prone.
    let pr = post_residual % 10;
    if pr == 0 {
        score -= 8.0; // perfectly harmonic leftover
    } else if pr <= 3 {
        score -= 3.0;
    } else if pr >= 7 {
        score += 5.0; // awkward residue class
    } else {
        score += 1.0;
    }

    // Integer-division threshold on post_residual: classify leftover into
    // capacity-fraction bands. Small leftovers (<20) are nearly complete bins.
    if post_residual <= 20 {
        score -= 6.0;
    } else if post_residual <= 40 {
        score -= 2.0;
    } else if post_residual <= 60 {
        score += 3.0;
    } else {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // (harmonic match), strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // next item's own harmonic class match with post residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
            // penalize if next item would waste most of the leftover
            if nxt / post < 0.5 {
                score += 8.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item can't use this leftover: leftover becomes dead space
            score += 10.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = (post_residual as f64 / cap).powi(2);
        score += 15.0 - 15.0 * desperation;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // early in stream, keep some openness
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Pull toward mean residual to avoid fragmenting the bin pool.
    score += 0.3 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100) are wasted.
    // Anything below the minimum item size is pure dead space -> heavy penalty.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 500.0;
    } else if post_residual < 10 {
        // Unusable dead space (smaller than any item) -> severe penalty.
        score += 300.0 + (10 - post_residual) as f64 * 10.0;
    } else if post_residual <= 20 {
        // Only fits very small items; moderate penalty scaled by tightness.
        score += 40.0 * (20 - post_residual) as f64;
    }

    // Reward bins whose residual was already tight (efficient packing).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 75.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's leftover; slight penalty for stranding space.
        score += 15.0;
    }

    // Last-chance bin: if only this bin can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when bins are few (early stream or after consolidations).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = 15.0 * (open_bins_count as f64) * (0.5 + progress);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus pressure.
        score += 120.0 + new_bin_bias;
        // Opening a bin is attractive if the item is large and would leave
        // a well-shaped residual, but never for tiny items late in the stream.
        if item_size >= 50 {
            score -= 60.0;
        }
        if progress > 0.5 && item_size < 30 {
            score += 80.0;
        }
    } else {
        // Slight reward for using existing bins proportional to open pressure.
        score -= 5.0 * (open_bins_count as f64).min(10.0);
    }

    // Mean-residual coupling: prefer bins deviating from the mean toward tightness.
    score -= 0.5 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 25.0;
    }
    // Penalize small dead space that next item can't use
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Favor bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Compare post_residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New empty bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the fit is very poor elsewhere (handled above).
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual near zero is ideal.
    score -= (1.0 - post / cap) * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if next item fits into the resulting residual, this placement
    // enables a chain — reward it; if next item would have fit the residual
    // before placement but no longer does, penalize dead-space creation.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 6.0 + nxt / cap * 4.0;
        } else if next_item_size <= bin_residual {
            score += 5.0 + nxt / cap * 6.0;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or open bins are congested (high mean residual).
    if bin_residual == bin_capacity {
        let congestion = (mean_residual / cap).clamp(0.0, 1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        let mut new_bin_penalty = 25.0
            - congestion * 18.0
            - item_frac * 15.0
            - progress * 5.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            new_bin_penalty -= 6.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Prefer bins with residuals below the mean (consolidate small spaces).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Mild pressure against accumulating too many open bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear emphasis that grows
    // as the stream progresses (dead space matters more late in the stream).
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Smooth polynomial coupling: penalize mid-range residuals (awkward gaps),
    // reward near-full fits and moderately small residuals.
    let coupling = norm_pr * (1.0 - norm_pr) * (norm_pr - 0.5);
    score += 40.0 * coupling * (1.0 + progress);

    // Lookahead: reward residuals that can host the next item, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let slack = ((pr - nxt).abs()) / cap;
        score -= 6.0 * fit_next * (1.0 - slack * slack) * (1.0 - progress);
        // penalize leaving just-barely-too-small residual for next item
        let miss = (nxt - pr) / cap;
        if miss > 0.0 && miss < 0.3 {
            score += 15.0 * (0.3 - miss) * (0.3 - miss);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Slight preference for bins with below-mean residual (consolidate fullness).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Penalize spreading across many open bins mildly.
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: only attractive when residuals elsewhere are poor.
    if bin_residual == bin_capacity {
        score = pr * (1.0 + 1.5 * progress * progress) + 8.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue mod 10 quantizes dead space.
    let residue_class = post_residual % 10;
    // Small nonzero residues are the worst dead space: penalize heavily.
    if post_residual > 0 && residue_class <= 2 {
        score += 18.0 - 4.0 * residue_class as f64;
    }
    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Residue in the "friendly" class (5..=9) leaves reusable chunks.
    if residue_class >= 5 && post_residual > 0 {
        score -= 3.0 + residue_class as f64;
    }

    // Integer-division harmonic: how many size-10 slots remain, and the leftover.
    let slots = post_residual / 10;
    let slot_leftover = post_residual % 10;
    score -= slots as f64 * 2.5;
    if slot_leftover != 0 && slots == 0 {
        score += 12.0; // sub-slot dead space with no reusable slot
    }

    // Couple with lookahead: if next item can exactly fill the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            score -= 8.0 - (next_left % 10) as f64;
        } else {
            // next item won't fit here; penalize more if we'd be stuck with tiny residue
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer tight bins over loose ones when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * (6.0 + 10.0 * progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if avg_pressure < 0.15 {
            score -= 4.0;
        } else {
            score += 10.0 + 20.0 * avg_pressure;
        }
    }

    // Mild preference to keep bin count from exploding mid-stream.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderately tight gap: mild penalty relative to baseline.
        score += 5.0;
    }

    // Reward tight fits generally: the smaller post_residual relative to item, the better.
    if item_size > 0 {
        score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64) * 20.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when the item fits poorly everywhere
    // (i.e., no tight fit exists) or few bins are open.
    if bin_residual == bin_capacity {
        let tight_fit_elsewhere = (bin_residual - item_size) < 10;
        let _ = tight_fit_elsewhere;
        // Base cost of opening a new bin, scaled by how many bins already exist.
        score += 40.0 + 2.0 * open_bins_count as f64;
        // A fresh bin leaves a large residual; acceptable early, costly late.
        score += (step_index as f64 / (total_items.max(1) as f64)) * 30.0;
        // If the next item is small, a fresh bin's large residual is useful.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 15.0;
        }
    } else {
        // Lookahead synergy: placing here leaves room for the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Slight preference for bins whose residual is close to the mean (balance).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect chain: next item leaves zero waste -> strong reward.
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportional to wasted potential.
        let overflow = (next_item_size - post_residual) as f64;
        score += 0.08 * overflow;
    }

    // Compare post-residual against mean residual: prefer bins that stay near the pack's average fill.
    let mean_post = mean_residual - item_size as f64;
    let dev = (post_residual as f64 - mean_post).abs();
    score += 0.05 * dev;

    // Tight fit reward: small post residual is good, but only if not creating dead space
    // that nothing else can use (sizes >= 1 in general case).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that makes it attractive
    // only when the current fit is poor or lookahead suggests a big item is coming.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.55 * bin_capacity as f64;
        let lookahead_big = next_item_size > 0 && next_item_size as f64 > 0.85 * bin_capacity as f64;
        if poor_fit || lookahead_big {
            score -= 8.0;
        } else {
            score += 15.0; // discourage opening new bins when decent fits exist
        }
    }

    // Early in the stream, be slightly more willing to open bins (builds a good pool);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space: residuals too small for the smallest item (1..100 unknown, use 10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 35.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty if we leave large unusable gap
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state: when many bins are open, prefer consolidating into existing ones.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * t);

    // Compare against mean residual: bins with residual far from mean are either
    // unusually tight (favor) or unusually empty (mild penalty vs new bin).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.15 * dev; // tighter than average -> lower score
    } else {
        score += 0.05 * dev;
    }

    // New-bin candidate bias: make empty bins mildly attractive only when the item
    // is large relative to capacity or no good existing fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 12.0 * large_item;
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Late-stream conservatism: as stream ends, avoid opening bins that will be mostly wasted.
    if t > 0.8 && post_residual > bin_capacity / 2 {
        score += 15.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), with polynomial shaping
    let mut score = x * x * (3.0 - 2.0 * x) + 0.5 * x;

    // Smooth interaction: waste penalty grows with stream progress
    score += 8.0 * x * x * progress;

    // Penalize large residual relative to mean residual (dead space risk)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Reward near-perfect fits more strongly late in the stream
    let perfect = 1.0 - x;
    score -= 2.0 * perfect * perfect * perfect * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 4.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    } else {
        // last item: minimize residual strictly
        score += 6.0 * x;
    }

    // Mild penalty for spreading across many bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division against capacity fractions (dead-space bands).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let band = (pr / (cap / 8.0)).floor() as i32; // 0..8 harmonic class

    // Penalize dead space non-linearly: tiny leftovers (< ~12) are nearly unusable.
    if band == 0 {
        score += 60.0 * (1.0 - pr / (cap / 8.0));
    } else if band == 1 {
        score += 15.0;
    } else if band >= 6 {
        // Large leftover is good: bin remains very reusable.
        score -= 10.0 + pr / cap * 20.0;
    }

    // Reward exact modular harmony: post_residual divisible into useful chunks.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Extra reward if next item leaves another harmonious remainder.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, opened only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream, prefer filling existing bins less aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with coupling).
    score += (pr - mean_residual) * 0.3;

    // Slight preference to pack into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (small leftovers that few future items can fill) are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 120.0; // worst kind of waste: tiny dead space
        } else if post_residual <= 20 {
            score += 40.0;
        } else if post_residual <= 35 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 150.0;
    }

    // Tight-but-not-perfect fits (post_residual <= 15) still mildly rewarded
    if post_residual > 0 && post_residual <= 15 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless the fit is good
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when the current fit is bad
    if bin_residual == bin_capacity {
        // neutral base for new bin; make it attractive when existing fits are poor
        score -= 10.0;
        if post_residual < item_size as f64 * 0.25 {
            score -= 20.0;
        }
    } else {
        // existing bin: compare residual against mean residual to favor below-average waste
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 100.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; dead space less costly
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: eliminate score entirely for exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size (chained perfect fill), penalize near-misses that
    // leave dead space unusable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0; // chain: this bin becomes perfect for next item
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to slack
            score -= 0.5 * (post - nxt);
        } else {
            // next item cannot use this bin's leftover: penalize dead space,
            // worse when the leftover is small (unusable fragment)
            let frag = post / 100.0;
            score += 40.0 * (1.0 - frag);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or open bins are crowded; otherwise penalize
    // opening new bins to keep existing residual capacity utilized.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_fit = mean_residual / bin_capacity as f64;
        score = 50.0
            - 60.0 * fill_frac      // large items deserve fresh bins
            - 30.0 * pressure       // many open bins -> consolidate less
            + 40.0 * mean_fit;      // high mean residual -> reuse open bins
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can also host the next item
        }
    }

    // Mild global pressure: tighten scoring late in the stream to avoid
    // fragmenting residual capacity when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / 100.0) * 10.0;

    // Prefer bins tighter than the mean residual (compact packing).
    score += 0.3 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 22.0 * tightness * tightness;

    // Penalize dead space that can never be filled by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // Penalize placements that strand space the next item could have used.
            let waste = post_residual as f64 - (bin_residual - next_item_size.min(bin_residual)) as f64;
            if waste > 0.0 {
                score += 0.25 * waste;
            }
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Early in the stream: be more willing to open new bins (exploration),
    // penalizing existing bins slightly less as time progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += 10.0 - 30.0 * progress;
        // If no open bin fits well, new bin becomes attractive.
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    } else {
        // Existing bins get a mild bonus that grows over time (pack tighter later).
        score -= 6.0 * progress;
        // Prefer bins below mean residual (less-full bins) to balance? No:
        // prefer bins near mean to keep spread controlled.
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev.abs();
    }

    // Prefer placing into bins whose residual is closest to item size (best fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity.
    let mut score = pr / cap;

    // Non-linear coupling: post_residual penalty modulated by stream progress.
    // Early on, moderate residuals are fine (room for future items);
    // late in the stream, residual dead space becomes costly.
    let norm_pr = pr / cap;
    let progress_coupling = norm_pr * (0.5 + 2.0 * progress * progress);
    score += 0.8 * progress_coupling;

    // Smooth quadratic dead-space term: residuals that are too small
    // (unusable for typical items) are penalized super-linearly.
    let dead = ((norm_pr - 0.15).max(0.0)) * ((norm_pr - 0.15).max(0.0));
    score -= 0.6 * dead;

    // Interaction with mean residual: placing into a bin whose residual
    // deviates below the mean tightens the packing distribution.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.25 * dev * dev - 0.15 * dev;

    // Lookahead: reward if the post-residual can still host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 0.5 * (ni / cap) * (1.0 - progress);
        } else {
            // Smooth penalty for wasting space the next item could have used.
            let gap = (ni - pr) / cap;
            score += 0.35 * gap * (1.0 - gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // New-bin candidate: bias against opening a new bin unless the item is
    // large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 0.9 - 0.6 * (it / cap) - 0.4 * progress;
    }

    // Mild diversity pressure: many open bins -> favor consolidation.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of 10, and small leftovers that
    // many item sizes can still absorb) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Reward exact decade residuals (harmonic alignment with typical sizes)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else {
        score += 3.0; // off-grid leftovers are dead space
    }

    // Reward very tight fits (post residual in low classes)
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 6.0;
    } else if post_residual > 50 {
        // leaving more than half a bin empty is wasteful unless bin is fresh
        score += (pr - 50.0) * 0.15;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover remains usable for the lookahead item -> reward
            score -= 4.0 + 0.05 * (next_item_size as f64);
            // harmonic bonus when leftover exactly matches next item class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 3.0;
            }
        } else {
            // leftover cannot host next item: penalize proportionally to waste
            score += 2.0 + 0.10 * (next_item_size as f64 - pr).max(0.0);
        }
    } else {
        // last item: prefer closing bins as full as possible
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Fresh bin candidate: only attractive when current stream is early
    // or no open bin fits well; penalize opening new bins mid-stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        score += 10.0 * progress;
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild preference to balance against mean residual: avoid draining
    // bins far below the average (keeps a spread of usable gaps).
    score += 0.05 * (pr - mean_residual).abs();

    // Integer-division threshold on item size: big items should go into
    // bins with small residuals to avoid splitting large gaps.
    let item_class = item_size / 20; // 0..4 harmonic classes
    match item_class {
        3 => score -= 3.0, // very large items: pack them now
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 0.0; // post_residual >= 0 always; placeholder for symmetry
    }
    // Penalize small unusable gaps that can never fit the smallest plausible item.
    // Gaps in (0, 10) are dead space for the classic range; for 1..100 range,
    // treat gaps below ~5 as near-dead and apply a steep superlinear penalty.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 5.0 {
        score += (5.0 - pr) * 8.0;
    } else if pr == 0.0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.35 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoidable bin increment).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        // Neutral baseline; make new bins slightly unattractive so they are
        // chosen only when existing bins would create bad fits.
        score += 12.0;
        // But if mean residual is small (open bins nearly exhausted), a new
        // bin is fine.
        score -= 0.25 * mean_residual;
        // If the next item would fit in the fresh bin's residual after this
        // item, opening is more attractive.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 8.0;
        }
    }

    // Lookahead: prefer bins whose post-residual still accommodates the next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 6.0;
        } else {
            // Post-residual too small for next item: penalize if it's also
            // small enough to be dead space.
            if pr > 0.0 && pr < (next_item_size as f64) {
                score += 0.3 * (next_item_size as f64 - pr);
            }
        }
    }

    // Late in the stream, consolidate harder (fewer bins matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward: post residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            // proximity bonus: closer post_residual to next item is better
            score -= 25.0 / (1.0 + gap / 10.0);
            // penalize residual that can't fit the next item at all (dead-ish space)
            if post_residual < next_item_size && post_residual > 0 {
                score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    } else {
        // last item: just minimize waste
        score += 5.0;
    }

    // Tight fit reward relative to item size
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual below mean (consolidate small leftovers)
    score += (post_residual as f64 - mean_residual) * 0.2;

    // New empty bin candidate: penalize unless current bins are nearly full or it's early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / cap;
        // open new bin only when existing bins are quite full or few fitting options
        let penalty = 55.0 - 25.0 * avg_fill - 10.0 * progress
            - if fitting_bins_count <= 1 { 20.0 } else { 0.0 };
        score += penalty.max(0.0);
    }

    // Slight preference for bins that become exactly half or fully packed
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual == bin_capacity / 2 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: exact or near-exact fills are excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the next item cannot use.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes mean_residual.
    // Only attractive when existing residuals are small relative to the item
    // (i.e., current bins are nearly full and the item is large).
    if bin_residual == bin_capacity {
        let waste = mean_residual;
        score += 12.0 + waste * 0.5;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        if progress > 0.6 && item_size >= 50 {
            score -= 18.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Prefer bins with residual below the mean (consolidate fullness).
    score += 0.2 * ((bin_residual as f64) - mean_residual);

    // Mild preference for using fewer bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = (item_size as f64 / cap).clamp(0.0, 1.0);

    // Smooth non-linear coupling: base on post residual, warped by stream progress.
    let mut score = norm_pr * (1.0 + 0.8 * progress * norm_pr);

    // Tight fits rewarded more strongly as stream progresses (smooth polynomial).
    score -= fit * fit * (1.0 + progress) * 12.0;

    // Dead-space penalty: cubic in normalized post residual.
    score += norm_pr * norm_pr * norm_pr * 20.0;

    // Last-chance bonus: prefer filling the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward leaving space for the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = (next_item_size as f64).min(cap) / cap;
        let gap = (norm_pr - nxt).abs();
        score -= nxt * (1.0 - gap) * 6.0;
        if pr > 0.0 && pr < next_item_size as f64 {
            score += 4.0 * (1.0 - pr / (next_item_size as f64));
        }
    }

    // Mild preference for consolidation when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 0.5;

    // Slight pull toward bins with residuals near the mean (smooth).
    let mean_norm = mean_residual / cap;
    score += ((norm_pr - mean_norm) * (norm_pr - mean_norm)) * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but keep post_residual in "useful" harmonic classes.
    // Dead space penalty grows quadratically once residual drops below small-item sizes.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 40.0 } else { 0.0 };
        score += dead * (10.0 - post_residual as f64).powi(2) / 100.0;
    } else {
        score -= 60.0; // perfect closure is excellent
    }

    // Harmonic class reward: post_residual that is a "nice" size (multiple of 10 or 5)
    // is more likely to be filled by future items drawn from typical distributions.
    let pr = post_residual;
    if pr > 0 && pr < bin_capacity {
        let nice = if pr % 10 == 0 { 12.0 } else if pr % 5 == 0 { 6.0 } else { 0.0 };
        score -= nice;
        // Penalize awkward residuals in (0,10) and (10,20) non-harmonic zones
        if pr < 20 && pr % 5 != 0 {
            score += 15.0;
        }
    }

    // Integer-division threshold coupling with lookahead item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward proportional to how well it closes the bin
            let next_post = pr - next_item_size;
            score -= 20.0;
            if next_post % 10 == 0 { score -= 10.0; }
            if next_post == 0 { score -= 25.0; }
        } else {
            // Next item cannot use this residual: penalize small leftover more
            if pr < next_item_size {
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }
        // Modulo affinity: residual matching next item's decile class
        if pr >= next_item_size && (pr % 10) == (next_item_size % 10) {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when open bins fit reasonably,
    // unless current open bins are badly fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Opening fresh bin is attractive early or when mean residual is large & unusable
        if mean_residual > 40.0 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.9 {
            score -= 10.0; // open new bin to preserve large residuals
        } else {
            score += 25.0 + 15.0 * (1.0 - progress);
        }
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Prefer filling more-fragmented bins when many bins are open
    if open_bins_count > 3 {
        let gap = mean_residual - bin_residual as f64;
        if gap > 0.0 { score -= gap * 0.2; } else { score += (-gap) * 0.1; }
    }

    // Mild pressure to close bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it's too small to hold even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 10 {
        score += 50.0; // dead space penalty
    }
    // Non-linear penalty on tiny post-residuals (hard-to-fill slivers).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 200.0 / pr; // sliver penalty: smaller gap -> larger penalty
    }

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Coupling with next item lookahead: if next item fits exactly into
    // post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 30.0; // next item can't use leftover -> dead space risk
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln() * 15.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + pressure;
        // But if item is large and would leave a big residual anyway, allow it.
        if item_size > 70 {
            score -= 40.0;
        }
    } else {
        // Existing bin: reward using it when open-bin pressure is high.
        score -= pressure * 0.5;
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's already "tight" — prefer filling it.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual close to next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.5;

        // Perfect chain: next item exactly fills this bin afterwards
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // leftover after next placement: penalize dead space
            let dead = post_residual - next_item_size;
            if dead < 10 {
                score -= 15.0;
            } else {
                score += dead as f64 * 0.3;
            }
        }
    } else {
        // Last item: prefer minimal waste
        score += post_residual as f64 * 0.5;
    }

    // Penalize large post_residual relative to mean residual (wasteful spread)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.4;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter bins (smaller residual before placement)
    score += (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Discard tiny unusable fragments
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: neutral baseline, only wins if open bins are bad
    if bin_residual == bin_capacity {
        score += 5.0 + post_residual as f64 * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fit quality: reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 10.0 * (1.0 - progress);
        } else if post_residual > 0 && post_residual < next_item_size {
            // Post-residual is useless for the known next item: penalize mildly.
            score += 8.0;
        }
        // If next item exactly fills post-residual, strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be pickier about tightness.
        score += tightness * 10.0;
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than spreading.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score += consolidation * 5.0;
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Time horizon: early in the stream, keep bins flexible (favor larger post_residual
    // less strongly); late in the stream, prioritize closing bins tightly.
    let late_bias = progress * 20.0;
    score -= late_bias * (1.0 - tightness);

    // New-bin candidate handling: an empty bin is only attractive when existing bins
    // would be badly fragmented or the item is large.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        let poor_options = mean_residual < item_size as f64;
        if large_item || poor_options {
            score -= 20.0;
        } else {
            score += 60.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mild preference for filling bins that are already partly full (reduce bin count).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * progress * progress);

    // Penalize dead space more as stream progresses (quadratic in progress)
    score += 6.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits: subtract for small post_residual, non-linearly
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        score += 3.0 * (fit - 1.0) / (fit + 1.0);
    }

    // Lookahead coupling: favor bins whose post_residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    } else {
        // Last item: minimize residual tightly
        score += 10.0 * norm_pr;
    }

    // Mean residual dispersion coupling
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // Mild preference for consolidating into fewer bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the resulting residual (capacity fractions) ----
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left after placement

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Modulo classes on post_residual: residuals that match common item-size
    // residues (multiples of 5, 10, 20, 25) are more reusable later.
    let r = post_residual % 10;
    if r == 0 {
        score -= 40.0;              // multiple of 10: highly reusable
    } else if r == 5 {
        score -= 20.0;              // multiple of 5: decent
    } else {
        score += 15.0;              // odd residue: dead-space risk
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 25.0;              // multiples of 20 pair with mid-size items
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 20.0;
    }

    // Integer-division thresholds: classify residual into usable bands.
    let band = post_residual / 10; // 0..=10
    match band {
        0 => score -= 60.0,          // tiny residual: nearly full bin
        1 | 2 => score -= 10.0,      // small but usable for small items
        3..=5 => score += 0.0,       // mid band: neutral
        6..=8 => score += 25.0,      // large leftover: wasted capacity
        _ => score += 45.0,          // nearly empty bin after placing: bad
    }

    // ---- Lookahead coupling with next_item_size ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here too: strong reward, scaled by slack quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack.min(60.0);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 30.0; // chain fit leaves a clean residual
            }
        } else {
            // Next item does NOT fit after this placement: penalize, but
            // less if the residual was going to be dead space anyway.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(80.0) * 0.8;
        }
    } else {
        // Last item: any placement is fine; prefer tightest fit.
        score -= 50.0;
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits; opening a new bin is costly.
        score -= 90.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new empty bin: it can absorb anything, but should only win
        // when no open bin gives a decent fit (i.e., penalize it so that
        // good existing fits beat it, yet bad fits lose to it).
        score += 140.0;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 60.0;
        // A new bin is more attractive if the item is large relative to capacity.
        score -= (item_size as f64 / cap) * 40.0;
        // If many bins are already open, discourage opening more.
        score += open_bins_count as f64 * 4.0;
    }

    // ---- Global state coupling ----
    // Prefer bins whose residual is close to the mean residual (keeps the
    // pool balanced); outliers create fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild pressure to fill fuller bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over spreading out; penalize new-bin candidates.
    let progress = step_index as f64 / total_items as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress);
    score += bin_pressure * 0.6;

    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no existing bin fits well.
        score += 25.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this
    // placement (creates a usable gap for the known successor).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap unusable by the known next item: mild penalty.
        score += 5.0;
    }

    // Prefer bins whose residual is already below average (closer to full),
    // keeping large residuals available for large future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            // next fits: reward tightness of the two-step packing
            let chain_tightness = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 12.0 * chain_tightness;
        } else {
            // next item cannot fit here: penalize leftover dead space
            score += 6.0 + 0.25 * (post_residual as f64 - nxt);
        }
    }

    // Penalize post_residual that is small but unusable (dead space below min item size ~1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (tighter bins fill first)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, prefer exact fills more strongly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening new bins when many are open with usable space
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly favor bins where the NEXT item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
        // If next item exactly matches post_residual, this is a perfect pair.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits among them.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when the fit is poor or open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so full bins win when fit is decent.
        score += 40.0;
        // But relax penalty when the item is large or many bins are open already.
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 45.0; // must open the first bin
        }
    }

    // Global residual pressure: if mean residual is low, bins are nearly full;
    // prefer consolidating into the emptiest usable bin.
    score -= 0.5 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with more slack as stream progresses
    // (future items need room).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = it / cap;

    // Smooth non-linear base: reward tight fits via polynomial shaping of post_residual
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 2.0 * pr_norm * pr_norm);

    // Progress-coupled penalty: as stream advances, waste becomes costlier
    score += progress * pr_norm * pr_norm * 3.0;

    // Interaction between fit tightness and stream progress
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * (1.0 + progress) * 2.0;

    // Last-chance bonus when few bins fit
    if fitting_bins_count <= 1 {
        score -= 1.5;
    }

    // Dead-space penalty: post_residual too small for typical future items
    let nx = next_item_size as f64;
    if nx > 0.0 && pr < nx {
        score += (nx - pr) / cap * (1.0 + 2.0 * (1.0 - progress));
    }

    // Mean-residual coupling: prefer bins near the mean residual for balance
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Mild penalty for proliferation of open bins late in stream
    score += (open_bins_count as f64).ln() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: dead space buckets
    // post_residual in class 0 (perfect fit) heavily rewarded
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    } else {
        // large dead space penalty, superlinear
        score += (post_residual as f64 - 20.0) * 0.5;
    }

    // Modulo-10 class: residuals divisible by 10 are more reusable for integer item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead compatibility: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item won't fit here: leftover likely becomes dead space
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        // opening a new bin: base cost
        score = bin_capacity as f64;
        if post_residual >= 20 && fitting_bins_count > 0 {
            // an open bin could hold it reasonably; discourage new bin
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing large items in fresh bins can help
            score -= 10.0;
        }
        // early stream: slightly cheaper to open bins (building a pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer filling bins with small residual relative to mean (consolidation)
    if bin_residual != bin_capacity {
        let r = bin_residual as f64;
        if r < mean_residual {
            score -= (mean_residual - r) * 0.3;
        } else {
            score += (r - mean_residual) * 0.3;
        }
    }

    // Many open bins: encourage closing them out (prefer bins with small residual)
    if open_bins_count > 4 {
        score += bin_residual as f64 * 0.05;
    }

    // Integer-division threshold: post_residual / item_size ratio classes
    if item_size > 0 {
        let ratio = post_residual / item_size.max(1);
        match ratio {
            0 => score -= 10.0,   // item dominates bin: good consolidation
            1 => score -= 3.0,
            _ => score += ratio as f64 * 2.0, // item tiny vs residual: wasteful placement
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to be useful are heavily penalized.
    // A residual is "dead" if it cannot hold even the smallest plausible item (1..=100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness reward scaled by fraction of bin consumed.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Pressure to close bins: more open bins -> prefer filling existing ones.
    score += 4.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item almost fits, slight penalty for leaving an awkward gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins with residuals close to the item (minimize waste relative to mean).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - mean_residual).abs();

    // Mild preference to use existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item size (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial match: closer post_residual to next item is better.
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Post residual too small for next item: dead space penalty, scaled by gap.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Compare post_residual against mean residual: leaving more than average waste is bad.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if next item would pair with a fresh bin nicely, soften the penalty.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten packing (avoid leftover slivers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual (dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize very small post-residuals that are unusable (< next item or < 10).
    let min_useful = if next_item_size > 0 && next_item_size < 10 { next_item_size } else { 10 };
    if post_residual > 0 && (post_residual as u32) < min_useful {
        score += 15.0;
    }

    // Lookahead: reward if next item fits exactly in post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * chain;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot chain here; slight penalty proportional to leftover.
        score += 8.0 * ((post_residual as f64) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when many bins are already open and mean residual is high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt() + 0.05 * mean_residual;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Slight preference for fuller bins among open bins (best-fit bias).
        score -= 0.1 * (bin_residual as f64) / bin_capacity as f64;
    }

    // Global pressure: when mean residual is low (bins nearly full), conserve capacity.
    score += 0.02 * mean_residual * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: waste after placement, scaled by smooth progress-dependent weight
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Non-linear quadratic coupling: penalize mid-range residuals more sharply late in stream
    score += 30.0 * post_norm * post_norm * (0.5 + progress);

    // Reward tight fits (low post_residual) with smooth cubic bonus
    score -= 25.0 * (1.0 - post_norm).powi(3);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Penalize bins that are much emptier than average (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev.abs();

    // Lookahead coupling: if next item fits into the post residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 15.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt / cap) * (1.0 - post_norm);
        }
    }

    // Slight preference to keep number of open bins down early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with smooth penalty so it loses to decent fits
    if bin_residual == bin_capacity {
        score += 60.0 - 30.0 * progress * progress + 20.0 * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse residue classes mod capacity fractions
    let item_class = item_size / 10;          // 0..10
    let next_class = next_item_size / 10;     // 0..10 (11 if next==0 handled below)

    // Reward tight fits: small post_residual is good, but dead space in
    // (0, 10) is nearly unusable -> penalize the "gap band" nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Harmonic pairing: if next item exactly fills post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Next item fits into post_residual with small slack
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }
    // Next item cannot fit here: mild penalty proportional to its class
    if next_item_size > post_residual && next_item_size > 0 {
        score += 2.0 + next_class as f64;
    }

    // Complementarity via integer division: item_class + next_class near 10
    // suggests a perfect two-item fill potential in this bin.
    if next_item_size > 0 && item_class + next_class >= 8 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation; few open bins: new bins cheap
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced when few bins are open
        score += 15.0 - consolidation.min(10.0);
        // Opening a new bin is attractive if current item is huge (class >= 7)
        // and mean residual is small (poor fits elsewhere)
        if item_class >= 7 && mean_residual < 30.0 {
            score -= 10.0;
        }
    } else {
        // Favor bins whose residual is harmonically aligned with item size
        let residual_class = bin_residual / 10;
        if residual_class == item_class {
            score -= 5.0;
        }
        // Reward filling bins below mean residual (tends to close them)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late in the stream: prefer closing bins (low post_residual weighted more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps (0 < post_residual < 10)
    // are heavily penalized; a perfect fit (post_residual == 0) is rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual <= 20 {
        // Moderately small gaps are also risky if they can't fit typical items.
        score += 8.0;
    }

    // Reward using this bin when it is the only one that fits (last chance),
    // avoiding a new-bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when plenty of open bins exist
    // (open-bins pressure): new bins should be rare.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 8.0).min(6.0);
        score += 10.0 + pressure * 4.0;
        // But if no open bin fits at all, soften the penalty.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // Lookahead: if the next item fits into this bin's post_residual,
    // reward the placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: dead space risk.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Mild preference for filling bins that are already relatively full
    // compared to the mean residual of open bins.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, tighten packing (less tolerance for waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 30.0;

    // --- 2-step lookahead: does the next item fit into the post residual? ---
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if n <= pr {
            // Reward: next item can also go here -> chain two items into one bin.
            let gap_after_next = pr - n;
            // Perfect chain (post_residual == next_item_size) is ideal.
            score -= 40.0 * (1.0 - gap_after_next / bin_capacity as f64);
            // Extra reward if the chain nearly exhausts the bin.
            if gap_after_next <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Penalize leaving a residual that the next item cannot use
            // (dead space relative to the lookahead).
            let dead = pr - (pr % n.max(1.0));
            score += dead * 0.6;
            // Strong penalty if post_residual is small and unusable.
            if pr < 10.0 && pr > 0.0 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += (bin_capacity as f64 - post_residual as f64) * -0.1;
    }

    // --- Relative to mean residual: prefer bins that are outliers to fill ---
    if mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual) / mean_residual.max(1.0);
        // Filling a bin far below mean residual (very full bin) is good.
        score -= rel.max(-2.0).min(2.0) * 8.0;
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item fits badly
        // everywhere else or few bins fit it.
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        // Base cost of a new bin, discounted when item is large / awkward.
        score += 60.0 - 40.0 * poor_fit;
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            score += 30.0; // keep the last-chance bin alive
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // --- Coupling: large items prefer large residuals, small items flexible ---
    let size_frac = item_size as f64 / bin_capacity as f64;
    score += size_frac * (bin_residual as f64 - item_size as f64) * 0.15;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is heavily preferred.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fit_ratio * fit_ratio;
    }

    // Penalize small dead space that likely becomes unusable (items >= 10..80 typical).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving large gaps slightly.
            score += 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // New bin attractive only when item is large relative to capacity late in stream,
        // or no real alternative exists (fitting_bins_count small).
        score += 120.0
            - 80.0 * fit_quality
            - 60.0 * progress
            - 30.0 * (fitting_bins_count as f64).recip();
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins harder.
    let residual_pressure = mean_residual / bin_capacity as f64;
    score += 15.0 * residual_pressure * (open_bins_count as f64).ln().max(1.0);

    // Mild time-horizon effect: early in stream, slightly prefer new bins (exploit future freedom);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress) - 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post-residual weighted by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize dead space that cannot fit the next item (smooth quadratic in gap)
    if next_item_size > 0 && pr > 0.0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 0.6 * gap * gap / cap;
        }
    }

    // Reward tight fits: subtract smooth function of item filling the bin
    let fill_ratio = item_size as f64 / cap;
    score -= 12.0 * fill_ratio * (1.0 + progress);

    // Last-chance bonus: only one bin fits, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + 0.5 * progress);
    }

    // Mildly discourage scattering across many bins relative to mean residual
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Penalize bins far below the mean residual (poor consolidation)
    score += 0.4 * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "usable"
    // anchors for typical item sizes; odd/prime-ish residuals are dead space.
    let res = post_residual;
    if res > 0 {
        if res % 10 == 0 {
            score -= 6.0; // perfectly harmonic residual
        } else if res % 5 == 0 {
            score -= 3.0;
        } else if res < 10 {
            score += 12.0; // tiny sliver: dead space
        } else {
            score += 4.0;
        }
    } else {
        score -= 15.0; // perfect fit: close the bin
    }

    // Fractional capacity coupling: how much of the bin remains
    let frac = post_residual as f64 / cap;
    score += 20.0 * frac * frac; // quadratic penalty on wasted space

    // Lookahead: reward residuals that can host the next item exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap);
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        score += 6.0; // next item can't reuse this bin
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation, penalize spreading
    score += 0.5 * open_bins_count as f64 * frac;

    // Early stream: keep bins flexible (larger residual acceptable)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * frac;

    // Mean residual anchoring: prefer bins near the mean (balanced packing)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: make it moderately attractive only when the fit is bad
    if bin_residual == bin_capacity {
        score += 3.0 + 0.2 * item_size as f64;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    if post_residual < 10 {
        // Perfect fill (post_residual == 0) is ideal; 1..9 is dead space.
        score -= (10 - post_residual) as f64 * 8.0; // pushes toward exact fills
        score += 40.0; // flat penalty for creating an unusable gap
    }

    // Penalize gaps that cannot fit the known next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward using a bin whose residual was already tight relative to the item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one;
    // the empty-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual deviates below the mean (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Early in the stream, be slightly more willing to open bins for good structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to smallest possible item (1).
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // 2-step lookahead: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here: mild reward proportional to fit quality
            score -= 50.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item cannot fit in leftover: penalize dead space creation
            score += 30.0 + 0.5 * (post_residual as f64 - nxt);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual < 20.0;
        let bad_fit = post_residual as f64 > 0.0 && post_residual < 10;
        if !crowded && !bad_fit {
            score += 400.0;
        } else {
            score += 50.0;
        }
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * fit_quality * fit_quality * fit_quality;

    // Penalize dead space that can never be filled by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are waste
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is a chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Global pressure: many open bins with high mean residual → prefer
    // consolidating into existing space rather than opening new bins.
    let pressure = mean_residual / bin_capacity as f64;
    if pressure > 0.5 {
        score -= 8.0 * pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits to keep
    // bins flexible); late in stream, just pack tightly anywhere.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pickiness = (1.0 - progress) * (1.0 - progress);
    score += pickiness * (post_residual as f64) * 0.6;

    // New-bin candidate handling: empty bin gets a mild penalty so it only
    // wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 14.0 + 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to mean (keep residuals uniform,
    // easier to combine later).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post-residual with stream progress.
    // Late in the stream, residual space is more costly -> weight grows.
    let progress_weight = 0.6 + 1.4 * progress * progress;
    let mut score = pr * progress_weight;

    // Smooth cubic penalty for small-but-not-tight residuals (dead space).
    let tightness = 1.0 - norm_pr; // near 1 when item nearly fills bin
    score -= 18.0 * tightness * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize residuals that are too small for typical future items,
    // scaled smoothly by how many bins could fit this item.
    let scarcity = (fitting_bins_count as f64).recip().min(1.0);
    let dead = (norm_pr - 0.10).max(0.0) * (norm_pr - 0.10).max(0.0);
    score += 25.0 * dead * scarcity;

    // Lookahead: reward bins whose post-residual fits the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 - (pr - nx) / cap } else { (pr - nx) / cap };
        score += 12.0 * fit_next * (0.3 + 0.7 * (1.0 - progress));
    }

    // Mild bonus for using crowded bins, smooth in open_bins_count.
    let crowd = 1.0 - (-(open_bins_count as f64) / 8.0).exp();
    score -= 6.0 * crowd * (1.0 - progress);

    // Deviation from mean residual: prefer bins below/above mean adaptively.
    score += 4.0 * ((pr - mean_residual) / cap) * (1.0 - 2.0 * progress);

    // New-bin candidate: gently discourage unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (fitting_bins_count.max(1) as f64 - 1.0).max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes
    let class = post_residual % 10;
    // Residues that are "dead space" (cannot fit smallest item = 1..10 range)
    // post_residual < 10 is unusable dead space -> penalize
    if post_residual < 10 {
        score -= 5.0; // filling a bin to near-exactness is good
    } else {
        // Penalize leftovers in awkward classes (7..9 hard to fill, 1..3 dead)
        match class {
            0 => score -= 4.0,          // perfect multiple of 10: excellent
            1..=3 => score += 3.0,      // nearly dead space
            4..=6 => score -= 1.0,      // fillable by mid items
            7..=9 => score += 2.0,      // awkward gap
            _ => {}
        }
    }

    // Integer-division threshold: post_residual / 10 gives fillability tier
    let tier = post_residual / 10;
    score += tier as f64 * 0.8;

    // Lookahead coupling: if next item fits the post residual exactly, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic match on classes: next item leaves a multiple-of-10 residue
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // placement creates bad dead space or mean residuals are already tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin costs ~1 bin; only prefer it if the alternative is wasteful
        if post_residual < 10 {
            score += 20.0; // never open a new bin when we can nearly close one
        } else {
            score += 30.0 - 15.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        }
    }

    // Prefer tighter bins (small residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Mean residual coupling: if this bin is far below mean residual, it's a good target
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Many open bins: encourage consolidation
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.35 * tightness;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty for stranding space.
        score += 0.15 * post_residual as f64;
    }

    // Open-bin pressure: discourage spreading across many bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // Deviation from mean residual: prefer bins that are outliers (nearly full
    // or nearly empty) rather than average-fill bins.
    score += 0.25 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // and would leave a well-shaped residual, or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this is a great chained placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain
        } else {
            // reward proportionally to how much of the leftover the next item consumes
            score -= 60.0 * (chain / post_residual as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space that the next item cannot use.
        let waste = if post_residual < next_item_size {
            next_item_size - post_residual
        } else {
            0
        };
        score += waste as f64 * 2.0;
    }

    // Compare post_residual against the mean residual of open bins:
    // favor bins that end up tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit well, especially early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // A new bin is acceptable only if post_residual would be large and unusable
        // relative to what open bins offer; mild penalty keeps consolidation.
        score += 80.0 * (1.0 - progress);
        if post_residual as f64 > mean_residual {
            score += 40.0; // new empty bin leaves more slack than average open bin
        }
    }

    // Slight preference to fill bins with larger residual first (best-fit flavor).
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward leaving zero dead space.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // prefer it heavily over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can still host the
    // next item; penalize bins that would strand space the next item needs.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate: penalize opening a fresh bin, more so when the
    // open-bin pool is already rich in residual space (mean_residual high).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 0.4 * mean_residual;
    }

    // Global coupling: mildly favor bins whose residual is below the mean
    // (i.e., tighter bins get filled first, keeping loose bins flexible).
    score += 0.1 * (mean_residual - post_residual as f64);

    // Time-horizon term: late in the stream, filling existing bins matters
    // more than keeping bins open for future items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap; // normalized post residual in [0,1]
    let base = pr * (1.0 - 0.5 * progress);
    let poly = pr_norm * pr_norm * (60.0 - 40.0 * progress); // penalize small residuals more early
    let mut score = base + poly;

    // Reward tight fits: low post residual relative to capacity
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 15.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: favor bins whose post residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Context terms: mean residual and open bins count
    score += 0.15 * (mean_residual - pr);
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New bin candidate: prefer it only when item is large relative to mean residual space
    if bin_residual == bin_capacity {
        let bias = 10.0 - 8.0 * (item_size as f64 / cap) - 6.0 * progress;
        score += bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item-size classes (multiples of 10) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize dead space that falls below the smallest item granularity,
    // weighted by harmonic class of post_residual.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Class bonus: post_residual congruent to 0 mod 10 is highly reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold classes on post_residual: small leftovers
    // (class 0..10) are nearly dead; large leftovers are flexible.
    let leftover_class = post_residual / 10; // 0..=10
    score += (10 - leftover_class.min(10)) as f64 * 0.8;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic class match between next item and leftover
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
            score -= 5.0;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size as f64 - post) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        // neutral baseline: score = capacity - item (post_residual = cap - item)
        // discourage premature opening when many bins exist with room
        let pressure = mean_residual / cap;
        score += (open_bins_count as f64).ln().max(0.0) * 10.0 * (1.0 - pressure.min(1.0));
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Slight preference for tighter bins (small residual before placement)
    score += (bin_residual as f64 / cap) * 3.0;

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small leftover gaps that few future items can use.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 40.0;

    // Progressive penalty for residuals that are small but nonzero
    // (unusable fragments), scaled by how tight the fit is.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.2;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = (item_size as f64) / (bin_residual as f64);
        score -= tightness * 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // this placement is loose; encourage using existing bins when many are open.
    score += open_bins_count as f64 * 0.15;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large or open bins are tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 5.0;
        if item_size >= 60 {
            score -= 10.0;
        }
        if pressure < 0.25 {
            score -= 8.0;
        }
        // Avoid opening new bins late in the stream for small items.
        if item_size < 30 {
            score += 10.0;
        }
    }

    // Lookahead: if the next item would fit the post_residual exactly,
    // reward leaving that gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // Penalize if next item is bigger than post_residual (gap is truly dead
    // for the immediate future).
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: big reward.
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // Penalize mismatch, scaled by how tight the bin already is.
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += diff * (0.5 + 1.5 * tightness);
        }
        // If next item cannot fit here either way, dead space is worse.
        if next_item_size > post_residual {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize post_residual directly (already base term).
        score -= 5.0;
    }

    // Penalize large unusable gaps relative to mean residual across open bins.
    if (post_residual as f64) > mean_residual + 15.0 {
        score += 3.0;
    } else if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and we want to spread capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they fit poorly.
        score += 25.0;
        // Early stream: opening bins is cheaper (more future flexibility).
        score -= 20.0 * (1.0 - progress);
        // If many bins already open, discourage spreading further.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If lookahead suggests a fresh bin will pair well with next item.
        if next_item_size > 0 {
            let fresh_gap = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() as f64;
            if fresh_gap == 0.0 {
                score -= 35.0;
            } else {
                score += fresh_gap * 0.3;
            }
        }
    }

    // Small penalty for leaving tiny dead space (< 10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post_residual dominates, but amplify near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space penalty: residual that is small but nonzero is the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual as u32 {
        score -= 8.0 + 0.1 * (next_item_size as f64);
    }
    // If next item cannot fit anywhere after this placement, mild penalty unless this is a great fit.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive early, less so later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Opening a new bin wastes capacity if open bins exist and fit is available.
        if open_bins_count > 0 {
            score += 10.0 + 20.0 * (1.0 - progress);
        } else {
            score -= 25.0; // no alternative, must open
        }
    }

    // Global state coupling: prefer bins below mean residual (spread load evenly),
    // keeping some bins with large residuals for large future items.
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // As stream progresses, consolidate: penalize bins that would leave large residuals.
    score += 0.05 * post * progress;

    // Many open bins: encourage filling existing ones rather than fragmenting.
    score -= (open_bins_count as f64).ln().max(0.0) * (cap - post) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Quadratic dead-space penalty growing with progress (late waste is costlier).
    score += 30.0 * progress * norm_pr * norm_pr;

    // Cubic interaction: large leftover at end of stream is heavily penalized.
    score += 20.0 * progress * progress * norm_pr.powi(3);

    // Reward tight fits: small post residual relative to item size.
    score -= 15.0 * norm_item * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual smoothly.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let fit_quality = (next_item_size as f64 / pr).min(1.0);
        score -= 12.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize leaving space that cannot serve the next item.
        score += 8.0 * progress * (1.0 - next_item_size as f64 / cap);
    }

    // Last-chance bonus: strongly favor using a bin when few alternatives exist.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure).
    score += 0.3 * ((pr - mean_residual) / cap).abs() * (1.0 + progress);

    // New-bin candidate: prefer opening fresh bin early or when fit is terrible.
    if bin_residual == bin_capacity {
        score = pr - 20.0 * (1.0 - progress) * (1.0 - norm_item) + 10.0 * progress * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in [1..=9] is nearly worthless,
    // [10..=19] mildly bad, exact zero is perfect.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        let pr = post_residual;
        let class_penalty = match pr {
            1..=9 => 14.0,
            10..=19 => 6.0,
            20..=29 => 0.0,
            30..=49 => 3.0,
            _ => 5.0,
        };
        score += class_penalty;
    }

    // Lookahead: reward if next item fits exactly into post_residual (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item divides post_residual reasonably
            let frac = next_item_size as f64 / post_residual as f64;
            if frac > 0.6 {
                score -= 18.0;
            } else if frac > 0.3 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual: penalize large leftover more
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins with small residual relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when item is huge and nothing fits well.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64 / cap) > 0.8;
        if tight {
            score -= 12.0;
        } else {
            score += 20.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Mild preference for tighter residual bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual that cannot accommodate even the smallest plausible future item is "dead space".
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating a gap that fails the next item but is too big to be dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // for the new-bin candidate, add pressure proportional to open_bins_count.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // A new bin is only attractive if existing bins would leave large dead space.
        score += 10.0;
        // Late in the stream, closing out bins matters more; keep new bins less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Favor filling already-open bins when many are open (reduce bin count).
        score -= open_bins_count as f64 * 0.3;
    }

    // Prefer bins whose residual is far from the mean residual (tighter bins get priority).
    score -= (mean_residual - post_residual as f64).abs() * 0.2;

    // Mild preference for bins with small current residual (best-fit flavor).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Slack left after a hypothetical next placement: mild penalty growing with gap
        let gap = (post_residual - next_item_size) as f64;
        score += gap * 0.35;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item can't fit here afterwards: dead-space penalty
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward small residuals that are unusable-but-tiny (near-perfect packing)
    if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate baseline: keep it unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in stream, opening new bins is cheaper; late, discourage strongly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If next item is huge, a fresh bin gives flexibility
        if next_item_size > 70 {
            score -= 25.0;
        }
    }

    // Slight bonus for filling large items into tight bins
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post-residual), but penalize dead space
    // that is too small to be useful for future items (items >= 1).
    let dead = post_residual as f64;
    if dead > 0.0 {
        // Dead space penalty grows quadratically; small leftovers are fine.
        score += 0.35 * (dead / bin_capacity as f64).powi(2) * bin_capacity as f64;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement: mild penalty unless
            // other bins can take it anyway.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fit_quality;
    }

    // Crowding: many open bins with high mean residual -> encourage consolidation
    // into bins with below-average residual (pack fuller bins first).
    if open_bins_count > 1 {
        let rel = bin_residual as f64 - mean_residual;
        score -= 0.05 * rel; // prefer bins with residual below mean (fuller bins)
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large post_residual relative to item) or when bins are very crowded.
        let waste_existing = if fitting_bins_count > 0 {
            (bin_capacity as f64 - item_size as f64)
        } else {
            0.0
        };
        // Default: make new bin unattractive.
        score += 20.0;
        // But if placing in an existing bin would leave huge unusable residue
        // and many bins are open, allow opening a fresh one.
        if fitting_bins_count > 0 && waste_existing > 60.0 && open_bins_count > 3 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Slight preference for bins whose residual is close to item size (perfect fit).
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 6.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);

    let mut score = pr + 20.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= item_size as f64 * tightness * (0.5 + progress);

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 5.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 3.0 * (ni - pr) / cap;
        }
    }

    // Penalize wasted dead space relative to mean residual
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild pressure to reuse open bins vs opening new ones
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible into halves/quarters
    // of capacity are "harmonic" and easy to fill later.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -8.0 // perfect fit
    } else if cap as u32 % pr == 0 || (100 % pr == 0) {
        -3.0 // harmonic leftover (50, 25, 20, 10, ...)
    } else if pr % 10 == 0 {
        -1.5 // decade-aligned leftover
    } else if pr < 10 {
        6.0 // dead space
    } else {
        0.0
    };
    score += class;

    // Integer-division threshold: leftover that exactly fits the next item is gold.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 6.0; // next item fills this bin exactly
            } else if slack % 10 == 0 {
                score -= 2.0;
            }
        } else {
            score += 2.5; // next item cannot use this leftover
        }
    }

    // Capacity-fraction coupling: reward leaving multiples of capacity quarters.
    let quarter = bin_capacity / 4;
    if pr > 0 && pr % quarter == 0 {
        score -= 1.8;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: open a fresh bin only when current fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > cap * 0.45;
        if poor_fit {
            score -= 4.0 + 2.0 * progress;
        } else {
            score += 3.0; // prefer existing decent-fit bins over opening new
        }
    }

    // Penalize bins far below mean residual (wasteful large holes) mildly.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Slight preference for tighter bins as stream progresses.
    score *= 1.0 + 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps.
    // Assume smallest possible item is 1; gaps below typical item sizes are waste.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 40.0; // tiny dead space is nearly unusable
    } else if post_residual as f64 > 0.0 && (post_residual as f64) < min_item * 10.0 {
        score += 20.0;
    }

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: prefer leaving space for the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 35.0; // perfect pairing
        } else if gap > 0 && gap < 10 {
            score += 10.0; // leaves another dead sliver
        }
    }

    // Mean residual coupling: bins far below mean residual are less urgent.
    score += 0.1 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();

        if diff == 0.0 {
            // Perfect match for the next item: huge reward.
            score -= 60.0;
        } else if next <= post {
            // Next item still fits after this placement: reward proportionally
            // to how tight the match is.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the leftover space: penalize dead space,
            // worse when the leftover is small but unusable.
            let waste_ratio = post / bin_capacity as f64;
            score += 15.0 * (1.0 - waste_ratio);
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins already have plenty of room,
    // but allow it when residuals are tight (mean_residual low).
    if bin_residual == bin_capacity {
        let mean_bonus = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // New bin is attractive if existing bins are nearly full (low mean residual).
        score -= 30.0 * (1.0 - mean_bonus);
        // Slight penalty to prefer reusing bins with good lookahead fits.
        score += 5.0;
    } else {
        // Reward placing into bins that are already partially filled when
        // their residual is below the mean (consolidating tight bins).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Early in the stream: allow more bin openings to build diverse residuals;
    // late in the stream: consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing can reuse (dead space < 10 is nearly useless,
    // but exact/zero post residual is perfect).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving room for the next item, punish when post_residual
    // is awkward for it (just barely too small or leaves a sliver).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: good, but don't over-save space.
            score -= 6.0 * (next_item_size as f64 / post_residual as f64).min(1.0);
        } else {
            // Wasted potential: post residual can't host next item.
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the current item
    // is large relative to typical residual space and open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        // Base new-bin penalty; discount when open bins are crowded and mean residual is small.
        let mut nb = 18.0 + 10.0 * (1.0 - progress);
        nb -= 0.15 * fragmentation.min(60.0);
        nb -= 0.5 * open_bins_count as f64;
        // If next item is large too, hoarding two large items apart is fine.
        if next_item_size >= item_size {
            nb -= 5.0;
        }
        score += nb.max(2.0);
    }

    // Mild penalty for leaving residual far from the "harmonic" reusable sizes (10..80).
    if post_residual > 0 {
        let dev = (post_residual as f64 - 50.0).abs();
        score += 0.05 * dev;
    }

    // Encourage consolidation when many bins are open.
    score += 0.3 * open_bins_count as f64 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;
    let fit = fitting_bins_count as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let poly = norm_pr * norm_pr * (1.0 - p) + norm_pr * p * p;
    score += 12.0 * poly * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    score -= (it / cap) * (1.0 + 2.0 * p) * 8.0;

    // Penalize creating dead space that likely can't be reused
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fit - 1.0).ln().max(0.0);
    }

    // Lookahead coupling: prefer bins whose post-residual fits next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 + p);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Mild preference for consolidating into fewer bins early
    score += (open_bins_count as f64) * 0.05 * (1.0 - p);

    // Mean-residual coupling: prefer bins near mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it moderately attractive only for poor fits
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (it / cap);
        score -= 5.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // "harmonic" divisors of the capacity are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward residuals that align with common item-size classes (multiples of 10, 25, 50)
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 2.0; }
    } else {
        // Perfect fit is ideal
        score -= 40.0;
    }

    // Penalize small unusable dead space (harmonic "dead zone" classes)
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr >= 10 && pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / cap);
        if pr == next_item_size {
            score -= 20.0; // chain of perfect fits
        }
    }

    // Fraction-of-capacity coupling on the item itself
    let item_frac = item_size as f64 / cap;
    if item_frac > 0.5 {
        score -= 5.0 * item_frac; // large items prefer tight bins
    }

    // Last-chance bin: strong penalty for opening a new bin when only this
    // bin fits, unless the fit is very tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate: make it mildly unattractive unless residuals are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // but attractive if all open bins would leave big dead space
        if mean_residual < 0.15 * cap && open_bins_count > 0 {
            score -= 18.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer filling bins with below-average residual (balance toward tight bins)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild pressure to close bins as stream matures
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    // Gaps below the minimum item size (1) are impossible, but gaps that no
    // realistic item (>= 10) can use are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item almost fits but leaves dead space, penalize slightly.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over opening new ones; when few bins are open, be less picky.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 6.0 * pressure;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when existing
    // residuals are poor. Penalize opening a new bin, more so late in stream
    // and when mean residual is still usable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * progress;
        if mean_residual > 25.0 {
            score += 10.0;
        }
    }

    // Slight preference for bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: nearly zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 400.0; // next item fills this bin perfectly
        } else if diff <= 5 {
            score -= 200.0 - 20.0 * diff as f64;
        } else {
            // Penalize post_residuals that are too small to be useful (dead space)
            // but too large to be closed out.
            score += 30.0 * (1.0 - diff as f64 / bin_capacity as f64);
        }
        // Chain bonus: if this bin could also fit the next item afterwards.
        if post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins below the mean residual
    // (tighter bins get emptied first), penalize bins far above mean.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless the
    // item is large and no open bin fits well. Penalize new bin mildly, but
    // reduce the penalty for large items.
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 100.0 * large_item_bonus;
        // If no open bin fits at all, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Slight preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powf(6.0);

    // Penalize dead space: post_residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64).powf(3.0);
        } else {
            // Next item can't follow here; mild penalty scaled by gap.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin is attractive only when fits are bad.
    if bin_residual == bin_capacity {
        // Neutral-ish base; penalize slightly when good fits exist elsewhere.
        score += 10.0;
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // Few open bins -> new bin less costly.
        score -= 2.0 * open_bins_count as f64;
    } else {
        // Reward using already-open bins, more so when many are open.
        score -= 0.2 * open_bins_count as f64;
        // Prefer bins below mean residual (consolidating emptier bins).
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: as stream progresses, tighten everything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: normalized post-residual with smooth quadratic shaping.
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + pr_norm * pr_norm);

    // Non-linear coupling: residual usefulness decays quadratically with progress
    // (early on, leaving room is cheap; later, dead space is costly).
    let dead_penalty = pr_norm * pr_norm * (0.5 + 2.0 * progress * progress);
    score += dead_penalty;

    // Smooth fit reward: strongly favor tight fits via inverse-quadratic term.
    let tightness = 1.0 - pr_norm;
    score -= 1.5 * tightness * tightness * (1.0 + fit_ratio);

    // Lookahead coupling: smooth polynomial interaction between post-residual
    // and next item size (can next item still fit?).
    if next_item_size > 0 {
        let can_next = (pr as f64 - next_ratio * cap).max(0.0) / cap;
        let compat = 1.0 - ((next_ratio - pr_norm).abs());
        let compat_pos = compat * compat;
        score -= 0.8 * compat_pos * (1.0 - progress);
        score += 0.3 * (1.0 - can_next) * pr_norm * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    // smoothly (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - pr_norm * pr_norm);
    }

    // Crowd coupling: many open bins with high mean residual -> prefer filling
    // existing bins; interaction term with progress.
    let crowd = (open_bins_count as f64).ln() / 5.0;
    score += crowd * (mean_residual / cap) * (0.5 + progress);

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap);
        score += 2.0 + 1.5 * avg_tightness * avg_tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual modulo 10 defines
    // "dead space classes". Residuals in {0} are perfect; small residues
    // (1..9) are nearly dead; residues near class boundaries are reusable.
    let post_class = post_residual % 10;
    match post_class {
        0 => score -= 12.0,                    // perfectly divisible residual
        1..=3 => score += 8.0,                 // nearly-dead sliver
        8..=9 => score += 3.0,                 // awkward but small
        _ => {}                                // 4..7 mid classes neutral
    }

    // Integer-division thresholds: residual >= 50 keeps half-capacity utility.
    if post_residual >= bin_capacity / 2 {
        score -= 15.0;
    } else if post_residual >= bin_capacity / 3 {
        score -= 7.0;
    } else if post_residual >= bin_capacity / 5 {
        score -= 2.0;
    } else {
        // Below 1/5 capacity: dead space penalty scaled by how dead it is.
        score += (bin_capacity / 5 - post_residual) as f64 * 0.8;
    }

    // Perfect complementarity: next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward proportional to how much it consumes.
            let fill_frac = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill_frac;
            // Harmonic pairing: (item + next) divisible by 10 -> clean class.
            if (item_size + next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: penalize large unusable leftovers.
            score += (post_residual as f64).powf(1.3) * 0.15;
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Penalize opening a new bin unless current residuals are badly fragmented
    // (mean residual low relative to item needs) or nothing fits well.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty makes new bins lose against decent fits...
        score += 30.0;
        // ...but early in the stream or with fragmented residuals, new bins win.
        score -= 20.0 * (1.0 - fragmentation) * (1.0 - progress);
        if post_residual < item_size {
            score -= 10.0; // safety (shouldn't trigger on empty bin)
        }
    }

    // Tight fits are good: small post-residual already favored by base term,
    // but add a quadratic squeeze for near-perfect packing.
    if post_residual <= 5 {
        score -= 10.0;
    }

    // Mild preference to consolidate across many open bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // If the leftover gap can still fit the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If the leftover gap cannot fit the next item but could fit a typical
    // small item, mildly penalize creating stranded space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.4 * progress);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with below-average residual (tighter bins), keeping
    // looser bins available for future large items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it mildly unattractive unless it truly is
    // the best option (dead-space penalty above can still dominate).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward (small dead space relative to item)
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score -= 30.0 * (1.0 - tightness.min(1.0));

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish: strong reward scaled by how snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.6 * slack.min(100.0);
        } else {
            // dead space the next item cannot use: penalize
            score += 0.5 * ((next_item_size - post_residual) as f64);
        }
    }

    // Penalize bins with residual far above mean (wasteful hoarding), reward below-mean
    score += 0.4 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when many bins are open and mean residual is low
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * (mean_residual) + 2.0 * (open_bins_count as f64);
    }

    // Late in the stream: prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tightness * tightness;

    // Penalize exact fits slightly less: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small for any plausible future item
    // (items >= 1, so any residual > 0 is technically usable, but small
    // residuals under ~15 are hard to fill).
    if post_residual > 0 && post_residual < 15 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin wastes capacity of open bins.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: it should only win when the fit into
        // existing bins is poor (post_residual large there).
        score = post_residual as f64 + 35.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If many bins are open already, discourage proliferation.
        score += 1.5 * open_bins_count as f64;
        // If next item is large, a fresh bin can host it later; mild discount.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    } else {
        // Mild bonus for using already-open bins, scaled by how "full" the fleet is.
        score -= 0.05 * mean_residual;
    }

    // Global balance: prefer bins whose residual is below the mean (fill emptier
    // relative space first keeps large residuals available for big items).
    score += 0.08 * (mean_residual - bin_residual as f64).max(0.0);

    // Time-horizon coupling: late in the stream, prioritize minimizing current
    // post residual even harder (fewer chances to fix waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - 0.5 * norm_pr * (1.0 - progress);

    let mut score = pr + 40.0 * poly;

    // Penalize tiny residuals more aggressively as the stream progresses
    let tiny = ((10.0 - pr) / 10.0).max(0.0);
    score += tiny * tiny * (5.0 + 20.0 * progress);

    // Reward tight fits (low post residual) via smooth exponential coupling
    score -= 15.0 * (-pr / 8.0).exp() * (1.0 + progress);

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - pr / cap);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: keep neutral baseline so it wins only on genuinely bad fits
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * open_bins_count as f64 / (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" modulo classes (multiples of small sizes) are more valuable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 5 == 0 {
        -15.0
    } else if pr >= 10 {
        -5.0
    } else {
        30.0 // dead space below smallest item
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual vs next item lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin could also host the next item: reward exact/near fit chains.
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
        } else {
            // Post residual cannot host next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Harmonic pairing: item + next fills bin exactly
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (smaller post_residual wins via base term).
        score += (fitting_bins_count as f64) * 1.5;
    }

    // Reward filling bins close to capacity using capacity fractions.
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Early stream: keep bins flexible (avoid many partially filled bins early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += mean_residual * 0.05;
    } else {
        score -= mean_residual * 0.02;
    }

    // Penalize opening new bins when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 - (open_bins_count as f64).min(15.0);
        if post_residual >= 50 {
            score -= 5.0; // fresh bin fine for large leftover planning
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful are heavily penalized.
    // A residual below the minimum plausible item size is dead space.
    let min_item = 1.0f64;
    let dead_threshold = 20.0f64; // residuals below this are rarely re-usable
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_threshold {
        // Small-but-nonzero gaps are the worst outcome: penalize steeply.
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward: strongly subtract for exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward placements that still leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Creating a gap that cannot host the next item is undesirable.
        score += 5.0;
    }

    // Tight-fit reward relative to bin residual: favor bins where the item occupies
    // a large fraction of the current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage opening more bins /
    // spreading items; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits
    // well. Penalize it mildly so good existing fits win, but keep it competitive
    // when open bins have poor residuals.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // If mean residual across open bins is large, opening a new bin is less needed.
        score += 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit in the leftover: dead space penalty scaled by wasted capacity
    else if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += 15.0 * (waste / 50.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (fragmented bins) mildly
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // New empty bin candidate: only attractive when current item leaves useful space
    // for the next item, or when no good existing fit exists.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            // New bin promising a perfect chain
            if post_residual == next_item_size {
                score = base - 55.0;
            } else {
                score = base - 20.0;
            }
        } else {
            // New bin with no lookahead synergy: discourage unless forced
            score = base + 10.0;
            if fitting_bins_count == 0 {
                score -= 200.0; // must open a new bin
            }
        }
    }

    // Slight preference late in the stream for consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0 * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size).
    if post_residual > 0 {
        score -= (item_size as f64 / post_residual as f64) * 8.0;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives, to preserve choice diversity.
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * 2.0;
    }

    // Lookahead: penalize if next item could have used this residual better.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item still fits after placement: good chaining.
            score -= 10.0;
            // Extra reward if next item exactly fills the post residual.
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            // We consumed space the (larger) next item could have used.
            score += 12.0;
        }
    }

    // Prefer bins with residual below the mean (consolidating fuller bins),
    // penalize draining bins that are already roomier than average.
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // Encourage using existing bins over opening new ones, more so early on.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins when fits are terrible.
        score += 55.0 - 20.0 * progress;
        // If next item is large and current item is small, a fresh bin is less costly.
        if next_item_size > 60 && item_size < 30 {
            score -= 10.0;
        }
    } else {
        score -= 5.0;
    }

    // Slight preference for bins among many open ones (reduce sprawl).
    score += open_bins_count as f64 * 0.15;

    // Small deterministic tie-breaker favoring fuller bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: raw post residual
    let mut score = post;

    // Reward tight fits: large fill fraction gets a smooth quadratic discount
    score -= fit_frac * fit_frac * 40.0 * (1.0 + progress);

    // Penalize unusable dead space: small post_residual relative to item sizes is risky,
    // smooth penalty when post_residual is small but nonzero
    let dead = (1.0 - post / cap).max(0.0);
    score -= dead * dead * 10.0;

    // Penalize very large post_residual (wasteful low-fill placement), scaled by progress
    let waste = post / cap;
    score += waste * waste * 25.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits into the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty proportional to leftover
        score += 5.0 * waste;
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (i.e., tighter bins) — smooth interaction with post residual
    score += (post - mean_residual) * 0.15 * (0.5 + progress);

    // Early stream: prefer keeping large residuals for future items
    score += waste * 20.0 * (1.0 - progress);

    // Mild new-bin preference early, discourage late when many bins open
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress) - 5.0 * progress;
        score += open_bins_count as f64 * 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let pr = post_residual;
    let q = pr / 10; // decade class
    let r = pr % 10;

    // Dead-space penalty: residuals that no future item (>=1, multiples common) can use well.
    // Residuals in (0, 10) are nearly dead; residuals exactly 0 are perfect.
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64;
    }
    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic-class bonus: post_residual divisible by common item granularities (5, 10, 20, 25)
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 20 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // chain fit
        } else if next_item_size <= pr {
            let nxt = next_item_size as f64;
            let frac = nxt / cap;
            // Favor leaving residuals in the same harmonic band as next item
            let band = (frac * 10.0).floor();
            let pr_band = (pr as f64 / cap * 10.0).floor();
            if (band - pr_band).abs() < 1.5 {
                score -= 10.0;
            }
            // Waste measure relative to next item
            score += 0.15 * (pr as f64 - nxt);
        } else {
            // next item cannot fit here: residual becomes dead space for lookahead
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // baseline: residual after placement in fresh bin
        // Open a new bin if existing bins are highly fragmented (low mean residual)
        if mean_residual < (item_size as f64) * 0.6 && open_bins_count > 2 {
            score -= 15.0;
        }
        // Late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.8 {
        score -= 15.0 * (fill - 0.8) * 5.0;
    }

    // Mild normalization by mean residual state
    score += 0.05 * (mean_residual - pr as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0,10] are unusable for any
    // future item (min size 1..100 stream, but small gaps rarely help) —
    // penalize heavily; large residuals are valuable, keep them.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (best-fit flavor).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh space; favor compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: opening a new bin is only attractive if
    // existing bins are nearly full on average and the next item is large.
    if bin_residual == bin_capacity {
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        let next_pressure = next_item_size as f64 / bin_capacity as f64;
        score -= 18.0 * mean_tight + 10.0 * next_pressure - 8.0;
        // Never open a new bin when a good fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual >= 0 {
            score += 30.0 * (1.0 - mean_tight);
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward creating that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_use = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * gap_use;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Gap the next item cannot use: mild penalty.
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled down.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Last chance: this is the only bin that fits — strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists elsewhere. Penalize opening new bins early/often.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items benefit from a fresh bin; small items should reuse space.
        score -= 120.0 * item_frac;
        // Penalize new bins when many open bins still have room.
        score += 8.0 * open_bins_count as f64;
        // Mean residual high => plenty of slack around; discourage new bin.
        score += 1.5 * mean_residual;
        // Lookahead: if next item pairs well with the leftover after this item,
        // a new bin is fine; otherwise mild penalty.
        if next_item_size > 0 {
            let pair = (post_residual as u64).saturating_sub(next_item_size as u64);
            if pair > 0 && pair <= 30 {
                score -= 30.0;
            } else if next_item_size as f64 > post_residual as f64 {
                score += 20.0;
            }
        }
    } else {
        // Placing in an existing bin: lookahead pairing bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Slightly prefer bins with lower residual among fitting bins.
        score += 0.05 * bin_residual as f64;
    }

    // Time horizon: as stream progresses, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 60.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;

    // Non-linear waste penalty: squared normalized post-residual, modulated by stream progress
    score += fit_ratio * fit_ratio * cap * (0.5 + 0.5 * t);

    // Tight-fit reward: smooth bell around small post_residual
    let tightness = 1.0 - fit_ratio;
    score -= tightness * tightness * (item_size as f64) * 0.6;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - t);
    }

    // Scarcity pressure: many open bins relative to progress discourages new bins,
    // encourages filling existing ones
    let scarcity = (open_bins_count as f64) / (1.0 + t * 10.0);
    score += scarcity * fit_ratio * 0.3;

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = 1.0 - (next_item_size as f64 / pr.max(1.0));
        score -= 4.0 + 4.0 * slack * slack;
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving awkward gaps
        score += 2.0 * (1.0 - fit_ratio);
    }

    // Mean-residual contrast: prefer bins deviating below mean residual (tighter bins)
    score += 0.15 * ((mean_residual - bin_residual as f64) / cap);

    // New-bin candidate handling: empty bin gets baseline cost unless item is huge
    if bin_residual == bin_capacity {
        let big = (item_size as f64 / cap).powi(2);
        score = cap * 0.55 - 20.0 * big + 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: classify dead space into buckets ---
    // Residual classes of width 10 (capacity fractions of C=100).
    let class = post_residual / 10;
    match class {
        0 => score -= 25.0,            // 0..=9: near-perfect fit, reward strongly
        1 => score -= 12.0,            // 10..=19: good fit
        2 => score -= 4.0,             // 20..=29: acceptable
        3 => score += 6.0,             // 30..=39: mediocre
        4 => score += 14.0,            // 40..=49: poor
        _ => score += 22.0,            // 50+: large dead space
    }

    // Exact-fill bonus (item closes the bin perfectly).
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Modulo coupling: post_residual and next_item_size divisibility ---
    // If the next item would exactly consume the post-residual, huge reward (lookahead perfect fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    }
    // Harmonic congruence: next item leaves a small remainder again (chained near-fits).
    if next_item_size > 0 && post_residual > next_item_size {
        let chained = post_residual - next_item_size;
        if chained <= 5 {
            score -= 18.0;
        } else if chained <= 15 {
            score -= 8.0;
        }
    }
    // Penalize leaving a residual in a "dead class": too small for typical items (1..100 unknown,
    // but small residuals < 10 are only usable by rare tiny items).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // --- Integer-division threshold on next_item_size (harmonic thirds of capacity) ---
    let third = bin_capacity / 3;
    let two_thirds = 2 * bin_capacity / 3;
    if next_item_size > 0 {
        if next_item_size >= two_thirds {
            // Big next item: prefer keeping a large residual open for it.
            if post_residual < next_item_size {
                score += 15.0; // this bin can't host the next item either way
            }
        } else if next_item_size >= third {
            // Medium next item: reward residuals in its harmonic neighborhood.
            if post_residual >= next_item_size && post_residual <= next_item_size * 2 {
                score -= 10.0;
            }
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0; // strongly prefer the only bin that fits before opening a new one
    }

    // --- New-bin candidate handling: empty bin gets a mild penalty unless all else is bad ---
    if bin_residual == bin_capacity {
        // Neutral-ish default; the class bonuses above will make good existing fits win.
        score += 30.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // --- Tie-breaking: prefer bins tighter than the mean residual (low waste) ---
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Prefer placing into fewer crowded bins when many bins are open (reduce bin count pressure).
    score += 0.5 * open_bins_count as f64;

    // Small deterministic jitter from harmonic modulo of step and residual for tie-breaking.
    let jitter = ((step_index * 31 + post_residual as usize * 17) % 7) as f64;
    score += jitter * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item (1..=100,
    // but practical minimum item ~1) are pure waste. Penalize unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for the next item: mild penalty unless it's tiny dead space already handled.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count, but relax
        // when current bin would leave a very poor fit.
        score += 10.0 + open_pressure * 2.0;
        // If the new bin is the only way to get a good fit (item nearly fills a bin),
        // soften the penalty.
        if item_size >= 80 {
            score -= 25.0;
        }
    } else {
        // Reward using existing bins more when many are open.
        score -= 2.0 * open_pressure.ln().max(0.0);
    }

    // Slight preference for bins below mean residual (consolidate emptier bins' space).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in stream: be more conservative, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (low post residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; penalize large unusable post residual
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when post residual is large
        // (i.e., item is small relative to capacity) and fit elsewhere is poor
        score += 120.0 - 0.5 * post_residual as f64;
        if post_residual as f64 > mean_residual {
            score -= 40.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that no plausible future item can use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - t);
    }

    // Reward tight fits (small post residual relative to capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted pairing chance.
            score += 5.0 * (next_item_size as f64 - post_residual as f64).min(50.0) / 50.0;
        }
    }

    // Prefer bins with below-mean residual (keep large residual bins for larger future items).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // When many bins are open, discourage opening new ones (favor consolidation).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 25.0 * pressure * (1.0 - t);
    } else {
        score -= 10.0 * (1.0 - t);
    }

    // Fullness bonus: reward placing into already well-used bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 20.0 * fullness * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening.
    let mut score = prn * (1.0 + 0.9 * prn * prn);

    // Smooth polynomial coupling with stream progress: late in stream,
    // tighten more strongly (dead space matters more).
    score += 0.35 * prn * (1.0 - progress) * (1.0 - progress);
    score -= 0.25 * prn * progress * progress;

    // Penalize residuals that cannot fit the next item (dead space),
    // smoothly scaled by how close the gap is.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let gap = (nx - pr) / cap;
            score += 0.6 * gap * (1.0 + gap);
        } else {
            let slack = (pr - nx) / cap;
            score -= 0.15 * slack * (1.0 - slack.abs());
        }
    }

    // Last-chance bin bonus: if only this bin fits, avoid opening new bins
    // unless post_residual is terrible.
    if fitting_bins_count == 1 {
        score -= 0.8 * (1.0 - prn);
    } else {
        // Mild penalty for spreading across many fitting bins.
        score += 0.02 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Reward bins tighter than the mean residual (good consolidation).
    let mean_n = mean_residual / cap;
    score += 0.1 * (prn - mean_n) * (1.0 + progress);

    // Discourage opening new bins when several open bins exist and fit is decent.
    let is_new = (bin_residual == bin_capacity) as f64;
    score += is_new * (0.5 + 0.4 * (open_bins_count as f64).tanh()) * (1.0 - prn * prn);

    // Small bonus for exact-ish fits.
    if post_residual == 0 {
        score -= 1.0;
    } else if post_residual < 10 {
        score -= 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let r_mod = post_residual % 10;
    // Penalize residuals in "dead zones" (1..9 small slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    score += match r_mod {
        0 => -6.0,           // perfect decade residual, highly reusable
        1..=3 => 8.0,        // awkward sliver
        4..=7 => 2.0,
        _ => -2.0,
    };

    // Integer division thresholds: post_residual / 20 tiers
    let tier = post_residual / 20;
    score += tier as f64 * 3.0; // prefer tighter fills (lower tier)

    // Reward near-perfect packing
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.3;
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0; // next item leaves harmonic residual
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual too small for next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish score; open new bin only if open bins fit poorly
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // early stream: prefer consolidation later, open bins freely early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild preference to spread across many bins when mean residual is high
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    } else {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space penalty: residuals that are too small to host
    // typical items (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Non-linear waste shaping: penalize mid-range dead space quadratically.
    let waste = post / cap;
    score += 12.0 * waste * waste;

    // Pressure from number of open bins: prefer filling existing bins
    // when many are open, encourage consolidation.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when residual is huge and mean
    // residual of open bins is small (nothing fits well anyway).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if post_residual == bin_residual {
            score -= mean_residual * 0.3;
        }
    }

    // Lookahead: if next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Progress coupling: as the stream advances, be more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Mean residual alignment: prefer bins whose residual is close to mean
    // (balanced depletion) unless it is a perfect fit.
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect two-item packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong reward.
        if diff == 0.0 {
            score -= 40.0;
        } else if diff <= 3.0 {
            score -= 25.0 - 5.0 * diff;
        } else {
            // Penalize post-residual that is uselessly larger than next item.
            score += 0.3 * diff;
        }
        // If next item can't fit here at all, mild penalty for dead space.
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 0.0;
    }

    // Compare against mean residual: bins tighter than average are precious.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= 0.5 * (mean_residual - resid_f);
    } else {
        score += 0.7 * (resid_f - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: strongly discourage opening a new bin unless
    // the item is large and current residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Open a new bin only if open bins are quite full and item is big.
        let large_item = (item_size >= 60) as f64;
        let incentive = 20.0 * (1.0 - avg_pressure) + 10.0 * large_item * progress;
        score += 45.0 - incentive;
    }

    // Prefer filling bins tightly: penalize leaving awkward small residuals
    // (unusable dead space below the minimum item size).
    if resid_f > 0.0 && resid_f < 10.0 {
        score += 12.0; // tiny dead space is worst case
    }

    // Slight preference for bins with more residual consumed so far.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: small but nonzero post_residual that likely cannot fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward post_residual that can fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // Bonus if lookahead exactly fits post_residual (perfect pairing).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current item
    // is large and would leave awkward residue, or late in the stream with many bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Time horizon coupling: as stream progresses, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 20.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if mean_residual > (item_size as f64) * 1.5 && !is_new_bin {
        score -= 6.0;
    }
    if open_bins_count > 10 && is_new_bin {
        score += 5.0;
    }

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / cap; // fraction of capacity used overall
    let fit_tightness = item / bin_residual.max(1) as f64; // how much of this bin's free space is consumed
    score -= 18.0 * fit_tightness * fit_tightness;

    // Dead-space penalty: small post_residual that cannot plausibly fit future items.
    // Smooth polynomial coupling with progress: late in the stream, tiny leftovers matter more.
    let tiny = (post_residual as f64 / cap).powi(3);
    score += 60.0 * tiny * (0.5 + 0.5 * progress);

    // Reward leaving residual space that the lookahead item can use exactly or nearly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack * slack) * (0.6 + 0.4 * progress);
    }
    // Penalize if post_residual is nonzero but smaller than the next item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0 * (post_residual as f64 / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when the current
    // fit is poor (large post_residual would be wasted) or few bins fit the item.
    if bin_residual == bin_capacity {
        let poor_fit = fit_tightness < 0.5;
        let scarcity = (fitting_bins_count as f64).max(1.0);
        let new_bin_bonus = 14.0 * (1.0 - fit_tightness) * (1.0 - fit_tightness) / scarcity;
        if poor_fit || fitting_bins_count <= 1 {
            score -= new_bin_bonus;
        } else {
            // Prefer reusing open bins with good fits; make fresh bin mildly unattractive.
            score += 6.0 + 4.0 * progress;
        }
    }

    // Mild preference for bins whose residual is below the mean (consolidate emptier space).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early-stream: encourage keeping bins balanced; late-stream: chase tight fits harder.
    score *= 1.0 - 0.15 * progress * fit_tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "harmonic" fit classes.
    let post = post_residual;
    let residue = post % 10;

    // Reward residuals that are harmonic (near multiples of 10) -> reusable slots.
    let harmonic_bonus = match residue {
        0 => 12.0,
        1 | 9 => 8.0,
        2 | 8 => 5.0,
        3 | 7 => 2.5,
        4 | 6 => 0.5,
        _ => -1.0, // residue 5: awkward half-slot, penalize
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: classify dead-space zones.
    let zone = post / 25; // 0..4
    match zone {
        0 => score += 10.0,          // tiny residual (0..25): near-dead space
        1 => score -= 3.0,           // 25..50: decent slot
        2 => score -= 6.0,           // 50..75: good slot
        _ => score -= 9.0,           // 75..100: excellent slot
    }

    // Coupling with next item (lookahead): does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post >= next_item_size {
            // Exact harmonic match: next item fills bin completely.
            if post == next_item_size {
                score -= 20.0;
            } else {
                score -= (next_item_size as f64) * 0.15;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to overshoot.
            score += (next_item_size - post) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make it attractive only when open bins are fragmented
    // or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are used only when worthwhile.
        score += 8.0;
        // If mean residual across open bins is small (fragmented), new bin looks better.
        score -= mean_residual * 0.25;
        // If many bins compete for the item, new bin less urgent.
        score += (fitting_bins_count as f64) * 2.0;
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild penalty for spreading across many open bins when this bin is already tight.
    if bin_residual < item_size * 2 {
        score -= 2.0;
    }

    // Small normalization by capacity fraction.
    score *= 100.0 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2) when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // New-bin candidate: only attractive when residual is tiny/fragmented
    // relative to mean residual (i.e., open bins are poorly usable).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 && open_bins_count > 0 {
            score -= 25.0 * (0.25 - fragmentation) * 4.0;
        } else {
            score += 30.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Slight preference for tighter-fitting bins overall.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        let perfect = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + perfect);
        // If next item fits exactly after this placement, strongly favor this bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize if this placement leaves residual too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.1 * post_residual as f64;
    }

    // Compare residual against mean residual of open bins: prefer bins with larger residual (best-fit style)
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when an open bin fits well (empty-bin candidate handling)
    if bin_residual == bin_capacity {
        score += 8.0;
        // Allow new bin only if item is large relative to capacity
        score += 0.05 * item_size as f64;
    }

    // Penalize tiny dead space (unusable residuals below min item size)
    if post_residual < 10 && post_residual > 0 {
        score += 10.0;
    }

    // Late in stream: be more conservative, keep residuals tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize small post_residual (dead space).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 2.5 * tightness * tightness * cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize large dead space that nothing (min size 1..100) may fill.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.8;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // next item can still fit here: mild reward
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize leaving awkward gap
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: when many bins are open, prefer consolidating (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 0.5 * (0.5 + progress);
    } else {
        // New-bin candidate: penalize slightly more as stream progresses,
        // but allow opening fresh bins when mean residual is fragmented.
        score += 15.0 + 20.0 * progress;
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 0.4;
        }
    }

    // Prefer bins whose residual is below mean (use the fuller bins first).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual, smooth polynomial coupling with stream progress
    let x = pr / cap; // in [0,1]
    let t = progress;

    // Early stream: prefer tight fits (low post-residual); late stream: tolerate slack less
    let poly = x * x * (1.0 - t) + x * x * x * t;
    score += 40.0 * poly;

    // Reward filling bin deeply, scaled by how much of the bin the item consumes
    let fill_ratio = item_size as f64 / cap;
    score -= 15.0 * fill_ratio * (1.0 - x) * (0.5 + 0.5 * t);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many bins compete (encourage consolidation)
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item could fit into the resulting post-residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - t);
        } else {
            // Penalize leaving residual that likely becomes dead space
            score += 8.0 * ((nx - pr) / cap) * (0.3 + 0.7 * t);
        }
    }

    // Mild preference for keeping number of open bins low
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover matches a
    // "harmonious" residue class (dividing capacity evenly) are more reusable.
    let cap = bin_capacity;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // classify leftover by divisibility with capacity
        if cap % post_residual == 0 {
            score -= 25.0; // perfect harmonic class (e.g. 50, 25, 20, 10...)
        } else if post_residual <= 10 {
            score += 45.0; // dead space, too small for any item
        } else if post_residual % 10 == 0 {
            score -= 12.0; // decade-aligned class
        } else {
            score += (post_residual % 10) as f64 * 1.5; // off-class penalty
        }
    }

    // Lookahead coupling: does the leftover invite the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact match with lookahead
        } else if next_item_size < post_residual {
            // reward small waste relative to next item
            score -= (post_residual - next_item_size).min(20) as f64 * 0.8;
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more so when many bins are open and mean residual is large.
    if bin_residual == cap {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * progress + 0.05 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Tie-break toward tighter fits among many candidates.
    score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Any post_residual in (0, 10) is pure waste since min item size is 1 but
    // practically hard to reuse; penalize heavily, worst near ~half of small range.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual > 10 && post_residual <= 20 {
        // Moderately risky gap: reusable only by small items.
        score += 18.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer reusing existing ones
    // rather than fragmenting further; penalize relative to open count.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item fits poorly everywhere else (large dead space would be created).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with existing open bins.
        score += 40.0 + open_bins_count as f64 * 1.2;
        // If item fills most of a fresh bin, opening is genuinely good.
        if item_size as f64 / bin_capacity as f64 > 0.85 {
            score -= 55.0;
        }
        // Lookahead: if next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Lookahead synergy: if this bin's post_residual can host the next item,
    // reward it (keeps chains going).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post_residual is nonzero but smaller than next item, slightly penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins) when many bins are open.
    if open_bins_count > 3 {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.25;
    }

    // Mild early-stream exploration: early on, keep bins balanced.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match for next item (within small slack)
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 45.0 - slack * 4.0;
        } else {
            // penalize leftover that likely becomes dead space
            score += slack * 0.15;
        }
    }
    // post_residual too small for next item: dead space penalty
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Tightness reward: smaller absolute residual is better
    score -= (bin_capacity as f64 - post_residual as f64) * 0.10;

    // Compare against mean residual: bins with less residual than average
    // are more valuable to fill tightly
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 2.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are too small for typical future items
    // (dead space), but reward exact/near-exhaustion.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 12.0; // near-perfect fill, reward
        } else {
            score += 0.35 * dead * (1.0 - fit_ratio);
        }
    }

    // Lookahead: if next item fits in the post residual, big bonus.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let chain = next_item_size as f64 / (post_residual.max(1) as f64);
            score -= 30.0 * (0.5 + chain);
        } else {
            // next item won't fit here; mild penalty proportional to leftover gap
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin, decreasing over time if many open bins linger.
        let mut new_bin_cost = 55.0;
        // If mean residual is large (lots of scattered space), discourage new bins.
        new_bin_cost += 0.4 * mean_residual;
        // If few fitting bins and current fit is bad, allow new bin more readily late in stream.
        if fitting_bins_count <= 1 {
            new_bin_cost -= 20.0 * progress;
        }
        // Penalize opening a bin for small items.
        new_bin_cost += 0.3 * (bin_capacity as f64 - item_size as f64);
        score += new_bin_cost;
    }

    // Global pressure: many open bins with high mean residual -> push toward consolidation.
    if open_bins_count > 2 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 8.0 * pressure * (open_bins_count as f64).ln();
    }

    // Prefer larger residual bins slightly when item is small (keeps big gaps for big items).
    if item_size < 40 {
        score += 0.10 * bin_residual as f64;
    } else {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: quadratic post-residual scaled by stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * (0.5 + 0.5 * progress);
    score += 20.0 * poly;

    // Dead-space penalty grows with progress: small residuals become less usable
    let dead = (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 15.0 * dead * progress;

    // Lookahead: reward if next item fits into post residual (smooth logistic-like)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_frac = (pr / nxt.max(1.0)).min(2.0) * 0.5;
        let bonus = fit_frac / (1.0 + fit_frac);
        score -= 10.0 * bonus;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Crowd penalty: many open bins -> favor consolidating into existing ones
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - norm_pr);

    // Mean residual coupling: penalize bins far from mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize mildly unless residual would be very small
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: smaller post_residual is better (already base), boost it.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Harmonic class logic on post_residual: residuals divisible by common
    // item sizes are more reusable; classify by modulo structure.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else {
        // Residuals in "harmonic" classes (multiples of 10 within 1..=100 items)
        // are more likely to be filled by future items.
        let h = pr % 10;
        if h == 0 {
            score -= 12.0;
        } else {
            score += (10 - h) as f64 * 0.8; // penalize off-grid residuals
        }
        // Very small residuals are dead space unless they exactly close the bin.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 10.0;
            }
            score += nxt_post as f64 * 0.05;
        } else {
            // next item won't fit here; slight penalty if this is the only fitting bin
            if fitting_bins_count == 1 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are poor fits
    // or the item is huge relative to mean residual structure.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 55.0;
        // If current item is large and mean residual is small, new bin is justified.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 30.0 * (frac - 0.5) * 2.0;
        }
        if mean_residual < item_size as f64 * 0.6 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If many bins already open and none fit well, prefer new bin.
        if open_bins_count > 3 && mean_residual < 25.0 {
            score -= 10.0;
        }
    }

    // Mild penalty for using a bin when many bins fit (prefer tightest anyway via base).
    if fitting_bins_count > 2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score += 60.0; // tiny unusable gap
    } else if post_residual <= 30 {
        score += 15.0; // risky gap
    }

    // Reward when post_residual can still host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (best-first-fit for big items) or stream is early.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0 * (1.0 - item_frac);
        new_bin_penalty -= 20.0 * (1.0 - progress); // cheaper to open bins early
        if open_bins_count == 0 {
            new_bin_penalty = -100.0; // must open
        }
        score += new_bin_penalty;
    }

    // Mild pressure from number of open bins: consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residuals close to the item (tight packing).
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: item + next item exactly fills the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits too: reward tight combined packing.
            let combined = item_size + next_item_size;
            let slack = bin_residual - combined;
            score -= (slack as f64) * 0.6;
            // Bonus if the pair nearly fills the bin.
            score -= (combined as f64 / bin_capacity as f64) * 15.0;
        } else {
            // Next item cannot use the leftover: penalize dead space,
            // scaled by how close it came to fitting.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.5;
            // Small dead space is very bad (unusable).
            if post_residual < 10 {
                score += 25.0;
            }
        }
        // If next item is huge and this bin would be nearly full, that's fine.
        if next_item_size > post_residual && post_residual < 15 {
            score += 10.0;
        }
    } else {
        // Last item: prefer the fullest packing possible.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Reward tightness relative to the fleet's mean residual.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        let tight_exists = next_item_size > 0 && post_residual == bin_capacity;
        score += 30.0 + (tight_exists as i32 as f64) * 0.0;
        // Allow a new bin late in the stream if open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize dead space that is too small to be useful later (below min item size 1..100, use ~10 threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this bin's remaining space; mild penalty if post_residual is large (wasted).
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more selective (penalize mediocre fits);
    // late in the stream, prioritize closing bins (reward using existing bins).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 0.1 * post_residual as f64;
    score -= t * 5.0;

    // Global state: many open bins -> prefer filling existing ones; few bins -> allow new bins.
    let open_norm = open_bins_count as f64;
    score += 0.03 * open_norm * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean (it's an outlier hole), discourage wasting it on a loose fit.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual - 10.0 && post_residual > 15 {
        score += 6.0;
    } else if bin_res_f > mean_residual + 10.0 {
        // Large hole bin: placing here is fine, slight reward.
        score -= 2.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // But if the item is large relative to capacity, opening a new bin is natural.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * frac * frac;
        // If many bins are open and this is a late step, opening new bins spreads load — mild discount.
        score -= 0.02 * open_norm * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = (pr / cap).powf(2.0);
    let mut score = pr;
    // reward tight fits more strongly as stream progresses
    score -= 2.0 * cap * (1.0 - fit) * (0.5 + progress);
    // penalize small-but-unusable post residual (dead space), smooth via sigmoid-like term
    let dead = (pr / cap - 0.5).powi(3);
    score += 3.0 * cap * dead * (1.0 - progress);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= cap * 0.5 * (1.0 + progress);
    }
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score += 0.3 * gap;
        if pr >= n {
            score -= 0.5 * n;
        }
    }
    // mild preference to fill already-open bins vs opening new ones
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;
    // deviation from mean residual: prefer bins near mean to balance load
    score += 0.2 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer filling bins tightly (minimize post_residual).
    let mut score = post;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in "awkward" classes (just above
    // common item sizes) are dead space -> penalize; near-zero or large
    // reusable leftovers are fine.
    let q = post_residual / 10; // class 0..=10
    let class_penalty = match q {
        0 => -40.0,                       // perfect/near-perfect fit
        1 => -10.0,                       // small but often reusable
        2 | 3 => 25.0,                    // awkward gap 20..40
        4 | 5 => 5.0,                     // moderate, half-capacity zone
        6 | 7 => 30.0,                    // awkward gap 60..80
        8 | 9 => 12.0,                    // large-ish, still usable
        _ => 0.0,                         // fresh-bin class
    };
    score += class_penalty;

    // Exact modulo harmony: leftover divisible by 10 aligns with item grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post - next_item_size as f64;
        score -= 15.0 + 25.0 * (1.0 - slack / cap).max(0.0);
    } else if next_item_size > post_residual {
        // Next item cannot follow here; leftover likely stranded.
        score += 10.0 * (post_residual as f64 / cap);
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Fresh-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early/many bins already open with fragmented space.
    if bin_residual == bin_capacity {
        // New bin has full residual: its raw score is high; adjust by context.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post).abs();
        score -= 20.0 * fragmentation / cap;
        score -= 30.0 * (1.0 - progress); // early on, opening bins is cheap
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: must open
        }
    } else {
        // Mild preference for already-open bins to keep bin count low.
        score -= 5.0;
    }

    // Penalize bins whose residual deviates far from the mean (keeps diversity).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Small tie-breaker: prefer bins with more residual used overall.
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Any post_residual below the minimum item size (1) is impossible here,
    // but tiny residuals (< ~20) are hard to fill later -> quadratic penalty.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * (20.0 - pr) * 1.5;
        } else if pr < 35.0 {
            score += (35.0 - pr) * 0.8;
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via its large residual, but
    // add explicit pressure scaled by open_bins_count).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mild reward proportional to how well residual is used.
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a residual that wastes space.
        score += (post_residual as f64) * 0.5;
    }

    // Mean residual coupling: if this bin is much emptier than average,
    // prefer packing here to consolidate open space.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Penalize unusable dead space harder as it gets smaller (wasted capacity).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap == 0.0 {
            score -= 500.0; // chain perfect fit
        } else {
            score -= 120.0 / gap.sqrt().max(1.0);
        }
    }

    // Penalize if next item cannot fit here (bin likely closes with dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize so we only open when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Exception: large item with no fitting bins context — still slightly
        // prefer fresh bin if item is big and would leave huge dead space elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small dead space (hard to reuse later).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
        // Perfect chaining: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is very fragmented
    // or the fit is poor. Empty bin has post_residual == bin_capacity - item_size.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // If many bins are open and mean residual is large, opening new bins is wasteful.
        score += 0.5 * open_bins_count as f64;
        score += 0.3 * mean_residual;
        // Allow opening a new bin late in the stream if item is large (poor fits elsewhere).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 {
            score -= 25.0 * progress;
        }
        // Big items deserve a fresh bin when little fits.
        if fitting_bins_count <= 2 && item_size > 50 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate emptier bins first),
    // keeping fuller bins available for small future items.
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, prioritize just closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in the stream, penalize waste more
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= progress_coupling;

    // Polynomial interaction: post_residual vs mean_residual deviation
    let dev = norm_pr - mean_residual / cap;
    score += 30.0 * dev * dev - 20.0 * dev;

    // Reward last-chance bins (fitting_bins_count == 1) smoothly
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 - norm_pr);

    // Lookahead: reward if next item fits into post-residual (smooth polynomial term)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64 / pr).min(1.0);
        score -= 15.0 * fit_quality * (2.0 - fit_quality);
    }

    // Penalize many open bins slightly to encourage consolidation
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: leftover is a multiple of a small harmonic unit.
    for unit in [10u32, 20u32, 25u32, 50u32] {
        if post_residual % unit == 0 && post_residual > 0 {
            score -= 3.0 + unit as f64 / 25.0;
        }
    }
    if post_residual == 0 {
        score -= 12.0; // exact fill is ideal
    }

    // Penalize dead space: leftover too small for typical items (1..100 unknown,
    // but small leftovers below ~15 are nearly unusable).
    if post_residual < 15 && post_residual > 0 {
        score += 20.0 - pr;
    }

    // Modulo-class coupling with next item: does the leftover land in a class
    // that can host the next item exactly?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 10.0; // chain-perfect fit for lookahead item
        } else if post_residual > next_item_size {
            // reward leftover that keeps a harmonic remainder for the next item
            let rem = post_residual % next_item_size.max(1);
            if rem == 0 {
                score -= 6.0;
            } else {
                score += rem as f64 * 0.3;
            }
        } else {
            // next item won't fit here: penalize proportionally
            score += (nx - pr).max(0.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        score += 8.0
            + mean_residual * 0.15
            + (open_bins_count as f64) * 0.5;
        // late in the stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
    }

    // Prefer fuller bins (smaller residual) mildly, modulated by mean residual.
    score += (mean_residual - pr) * 0.2;

    // Integer-division threshold: leftovers in mid harmonic bands are valuable.
    let band = post_residual / 25; // 0..4
    score -= match band {
        0 => 2.0,
        1 => 4.0,
        2 => 3.0,
        _ => 1.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Anything below the minimum item size (1..=10)
    // is pure waste; slightly larger gaps are partially wasted.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // unusable dead space
        } else if post_residual <= 20 {
            score += 25.0; // barely usable gap
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: reward strongly
        score -= 100.0;
    }

    // Reward leaving a gap that can exactly host the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post_residual is just below the next item (near-miss gap)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage scattering across many bins
    score += open_bins_count as f64 * 2.0;

    // Prefer bins whose residual is close to what is consumed (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Mean-residual coupling: when open bins are already full-ish,
    // slightly favor packing into them rather than opening new ones.
    if bin_residual != bin_capacity && mean_residual < (item_size as f64 + 10.0) {
        score -= 10.0;
    }

    // New-bin candidate: make it moderately attractive only when no tight
    // option exists (its base post_residual = capacity is already large).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64 * 0.5)).max(0.0);
        // Perfect 2-step fit: post_residual equals next_item_size exactly
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize dead space that next item cannot use
        if next_item_size > post_residual && post_residual > 0 {
            score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit
        score += 10.0;
    }

    // Relative to mean residual: bins with residual above mean are better to fill
    let mean_gap = bin_residual as f64 - mean_residual;
    score -= 0.15 * mean_gap;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin when decent fits exist
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 45.0 * pressure;
        // Late in stream, prefer closing out open bins
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 20.0 * progress;
        // New bin is more attractive if mean residual is small (open bins nearly full)
        score -= 0.2 * mean_residual;
    }

    // Slight penalty for very small unusable post_residual (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < next_item_size as f64 && next_item_size > 0 {
        score += 8.0; // residual likely unusable by next item
    }

    // Reward residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // When many bins are open, prefer consolidating into fuller bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early on, be picky about residual quality; late, just fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Deviation from mean residual: prefer bins near the mean to keep balance,
    // but late in the stream prefer emptier bins to drain them.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (1.0 - progress) * 0.15 * dev - progress * 0.10 * dev;

    // Slight bias toward using already-open bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling: penalize small-but-nonzero post_residual (dead space)
    // most severely mid-stream; large residuals become more acceptable late.
    let dead = (1.0 - norm_pr) * norm_pr; // peaks at norm_pr = 0.5
    score -= 6.0 * dead * cap * (0.4 + 0.6 * progress);

    // Reward tight fits (post_residual near 0), stronger as stream progresses.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * progress);

    // Penalize leaving residual that cannot fit the next item (smooth quadratic gap).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score -= 4.0 * (1.0 - gap / cap) * (1.0 - gap / cap) * (gap / cap) * cap * 0.5;
        // If next item fits exactly well, reward.
        let fit_q = (pr - next_item_size as f64).max(0.0) / cap;
        score += fit_q * fit_q * cap * 0.3;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild pressure against scattering across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Prefer bins below mean residual slightly (use emptier bins first? no —
    // prefer bins whose residual is close to item size, i.e. above mean).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= dev * 2.0;

    // New-bin candidate: penalize mildly so it wins only for poor fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit gets a massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual falling on capacity fractions (C/2, C/3, C/4)
    // leaves room for standard-sized companions later.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual == half { score -= 60.0; }
    if post_residual == third { score -= 45.0; }
    if post_residual == quarter { score -= 30.0; }

    // Dead space: residuals too small for any plausible item (1..=10) are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained harmonic pairing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but imperfectly: reward proportional to how snug.
        score -= 20.0 * (1.0 - ((post - next_item_size as f64) / cap).abs());
    } else if next_item_size > post_residual {
        // Next item won't fit here: mild penalty scaled by how much it misses.
        score += 5.0 * ((next_item_size as f64 - post) / cap);
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals across
    // open bins are nearly exhausted (mean residual below item size).
    if bin_residual == bin_capacity {
        let mean_res = mean_residual;
        let pressure = (cap - mean_res) / cap; // 0 = full bins, 1 = empty bins
        score += 30.0 + 60.0 * pressure;
        // Late in the stream, opening new bins is less costly (no long tail of waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
    }

    // Modulo arithmetic on post_residual: multiples of 10 harmonize with
    // item sizes drawn on a 10-grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Prefer tighter bins among fitting ones: reward small current residual.
    score += (bin_residual as f64 / cap) * 10.0;

    // Crowding: with many open bins, consolidate into existing ones.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Dead space as fraction of capacity, superlinear penalty.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap slightly larger than the next item (wasted space).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 12.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Late in stream: be more conservative, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make opening a new bin costly unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Strongly discourage new bin if this bin is a last-chance fit.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // Early in stream, new bins are cheaper; late, prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        return score;
    }

    // Reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // 2-step lookahead: if next item exactly fits the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to leftover space
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit in leftover: penalize large unusable leftovers
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residual below mean (compact bins) slightly.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Penalize leaving dead space that nothing (10..80) could use well.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // nearly perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // Penalize leaving dead space that likely can't be reused
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64).powi(2);
        score = 60.0 + pressure * 20.0 - (fitting_bins_count as f64) * 4.0;
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= 0 {
            // big item coming: opening fresh bin can be wise
            score -= 15.0;
        }
        if mean_residual > item_size as f64 {
            score += 10.0; // existing bins have room; don't open new
        }
    }

    // Lookahead coupling: if next item fits in post_residual, reward
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() < 10 {
            score -= 3.0;
        }
    }

    // Global state shaping
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.08 * (1.0 - progress);
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Prefer fuller bins early, be more exploratory late
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * fill * 10.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;
    let fit = fitting_bins_count as f64;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, mild waste tolerance; later, demand near-perfect packing.
    score += 40.0 * norm_pr * progress * progress;
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - progress) * (1.0 - progress);

    // Reward filling bins that are relatively full already (non-linear).
    let fill = 1.0 - norm_pr;
    score -= 10.0 * fill * fill * fill;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 3.0 / fit;
    }

    // Penalize bins whose residual deviates badly from the mean (fragmentation).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead: bonus if next item fits exactly in the resulting residual.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    } else {
        // Last item: strongly prefer zero post_residual.
        score += 5.0 * norm_pr;
    }

    // Mild preference to keep number of open bins from exploding early.
    score += 0.2 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are
    // "friendly" (most item sizes 10..80 align), odd residuals are dead space.
    let post = post_residual as i64;
    let class_bonus: f64 = match post % 10 {
        0 => -12.0,
        5 => -4.0,
        r if r % 2 == 0 => -1.5,
        _ => 3.0,
    };
    score += class_bonus;

    // Harmonic class of the item itself: items on a 10-grid pack well together.
    if item_size % 10 == 0 {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item on same grid as post-residual remainder.
            if post_residual % 10 == 0 || next_item_size % 10 == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; penalize based on wasted slack class.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
            if post_residual < 10 {
                score += 10.0; // unusable sliver
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no open bin fits well, allow it: scale with open bins count.
        score -= 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from the mean (keep balance of classes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold: bins whose residual // 10 is small are tight.
    let tight_class = bin_residual / 10;
    if tight_class <= 1 {
        score -= 4.0; // using a nearly-full bin is good
    } else if tight_class >= 8 {
        score += 2.0; // nearly-empty bin: keep for large items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps below the minimum item size are worthless.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        // perfect fit, reward
        score -= 25.0;
    } else if post_residual < 10 {
        // tiny unusable sliver -> heavy penalty
        score += 18.0 + 2.0 * (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        // awkward small gap
        score += 6.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill;

    // Exact-fit style bonus when post_residual is 0
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            // next item cannot use this gap: penalize proportionally
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage scattering across many bins
    score += 0.35 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins)
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive for large items or when no bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so new bins are opened only when justified
        score += 8.0;
        // large items waste less space in a fresh bin; allow opening more readily early on
        score -= 0.20 * item_size as f64;
        score -= 5.0 * (1.0 - progress);
        if post_residual < 10 {
            score -= 10.0; // big item in fresh bin leaves no dead space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild penalty to prefer consolidation elsewhere.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting space now.
            score += 2.0;
        }
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, pack aggressively (reward filling bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - fit_ratio);

    // Global pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading out.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0 * mean_residual / bin_capacity as f64;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all poor fits (mean residual far below item size).
    if bin_residual == bin_capacity {
        score += 18.0;
        if mean_residual < item_size as f64 {
            score -= 22.0; // no open bin is a good home; open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // large items coming, fresh capacity useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = pr / cap;

    // Base: prefer small post residual, smoothly non-linearly scaled
    let mut score = pr as f64 + 8.0 * post_frac * post_frac * cap;

    // Reward tight fits (small post_residual) with smooth polynomial coupling to progress
    let tightness = 1.0 - post_frac;
    score -= 14.0 * tightness * tightness * (0.6 + 0.4 * progress);

    // Last-chance bonus: only bin that fits; stronger late in stream
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // penalize leaving residual that next item barely misses
            let miss = (nx - pr) / cap;
            score += 5.0 * (1.0 - miss) * (1.0 - miss) * (1.0 - progress);
        }
    }

    // Penalize opening a new bin when open bins exist and fit is decent, smoothly
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / cap);
        score += 4.0 + 3.0 * progress + 0.5 * crowding.sqrt();
        // but allow new bin if it would waste little and current fits are bad
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty when this bin's residual deviates from mean residual (harmonization)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Discard very small unusable residuals late in stream
    if pr > 0 && pr < 10 {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items sized 1..100, so dead space
    // is only "wasted" if it falls below the smallest plausible future item.
    // Classify residual into modulo-10 buckets (harmonic classes).
    let r = post_residual;
    let class = r / 10; // integer division threshold class
    // Dead-space penalty: residuals below 10 are near-unusable.
    if r < 10 {
        score += 40.0 * (10 - r) as f64;
    } else {
        // Reward residuals that are exact harmonic divisors of capacity-ish
        // sizes (10,20,25,50): easy to fill later.
        let harmonic = (r == 10 || r == 20 || r == 25 || r == 50 || r == 40 || r == 30) as f64;
        score -= 15.0 * harmonic;
        // Mild penalty proportional to class depth (large leftover = loose fit)
        score += 0.05 * (class as f64 - 2.0).max(0.0);
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if next_item_size <= r {
            let new_post = r - next_item_size;
            // favor lookahead placements leaving harmonic residuals
            let lh = (new_post % 10 == 0) as f64;
            score -= 10.0 + 20.0 * lh - 0.1 * (new_post as f64);
        }
    }

    // Last chance: if this is the only fitting bin, penalize opening a new bin
    // (i.e., reward using this bin) unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized early in stream
    // to prefer packing into existing bins, but encouraged when many bins and
    // mean residual is small (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.5 + 20.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).ln1p();
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 30.0; // fragmented: better to open fresh bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity - 1) {
            score += 10.0;
        }
    }

    // Tie-breaker: prefer tighter existing fits via residual ratio.
    score += 0.3 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are nearly unusable
    // since items are >= 1 but practical waste concentrates in tiny gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer bins whose residual was large relative to mean (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using a bin when it's the only fitting option (last chance).
    score += open_bins_count as f64 * 0.5;
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // Base new-bin cost; offset if lookahead item would fit the leftover
        // of a placement here poorly anyway.
        score = 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Opening a bin lets next item also land here: strong bonus.
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Placement leaves a gap the next item cannot use: penalize.
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover is reusable by the lookahead item: reward.
        score -= 10.0;
    }

    // Late-stream tightening: as the stream progresses, avoid creating
    // fragmented residuals, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // 2-step lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward a good chaining fit; penalize large slack left after chaining.
            score -= 10.0 - 0.15 * slack;
        } else {
            // Next item won't chain here; penalize dead space creation.
            score += 6.0;
            // Extra penalty if post-residual is a small unusable sliver.
            if post_residual < next_item_size && post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Compare against mean residual: prefer bins whose post residual deviates
    // favorably (below mean) — keeps a spread of usable residuals.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin (only one fitting bin): strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation risk).
    if open_bins_count > 3 {
        score += 0.02 * (open_bins_count as f64) * (post_residual as f64);
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    // New-bin candidate: make it moderately attractive only when the fit is
    // perfect (full capacity) or when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 4.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Penalize large dead space that can't fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when many bins are open and mean residual is large
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * mean_residual + 0.3 * open_bins_count as f64;
        // But if this is late in the stream and residuals are fragmented, opening fresh is fine
        let t = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 12.0 * t;
        }
    }

    // Mild time pressure: prefer filling existing bins as stream progresses
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Discourage leaving residuals near awkward mid-range values (hard to fill)
    let r = post_residual as f64;
    if r > 20.0 && r < 50.0 {
        score += 0.1 * (r - 35.0).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = rn * rn * (1.0 - progress) + rn * (0.5 + progress) - rn * rn * rn * progress;

    let mut score = poly * 100.0;

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize deviating far from mean residual (keeps residual spread balanced)
    score += 0.3 * (r - mean_residual).abs();

    // Slight preference for tighter fits (small post_residual)
    score += 0.05 * r;

    // Late-stream: discourage opening many new bins
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: post_residual divisible by small sizes is reusable space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best outcome
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 12.0; }
        if pr % 20 == 0 { bonus += 10.0; }
        if pr % 5 == 0 { bonus += 5.0; }
        if pr % 25 == 0 { bonus += 8.0; }
        score -= bonus;

        // Dead space: residuals in awkward mid bands are hard to fill.
        if pr > 0 && pr < 10 {
            score += 25.0; // tiny unusable sliver
        } else if pr < 20 {
            score += 10.0;
        }
        // Large residual is valuable: keep big spaces alive.
        if pr > 50 {
            score -= 8.0 + (pr as f64 - 50.0) * 0.3;
        }

        // Coupling with lookahead: residual that exactly fits next item is golden.
        if next_item_size > 0 {
            if pr == next_item_size {
                score -= 40.0;
            } else if pr >= next_item_size && pr - next_item_size < 10 {
                score -= 15.0; // next item nearly fills this bin
            } else if pr < next_item_size {
                score += 12.0; // residual too small for the known next item
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 3.0;
        let mean_gap = (mean_residual - item_size as f64).abs();
        score += 40.0 - pressure.min(35.0) - mean_gap * 0.2;
        // Late in the stream, new bins are relatively cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny slivers are pure waste
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    } else {
        // Larger residuals are still usable; reward proportionally less.
        score -= 0.05 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            // dead space locked against the known next item
            score += 0.3 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.4 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins first).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a new bin is only attractive when the item is large
    // relative to capacity or all existing residuals are poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item || (fitting_bins_count == 0) {
            score -= 20.0;
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score -= 0.5 * (bin_residual as f64 - item_size as f64).abs().recip() * 10.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let diff = (post_residual as f64 - nr).abs();
        if post_residual as f64 >= nr {
            // next item fits exactly -> strong reward
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit -> penalize wasted space
            score += 0.3 * diff;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: penalize so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // but if lookahead shows nothing fits open bins well, soften
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 5.0;
        }
    }

    // Late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect pairing: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill_ratio * (open_bins_count as f64).ln();

    // Time horizon: early in stream, be more willing to open new bins
    // (penalize new-bin less early, more late)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_call = bin_residual == bin_capacity;
    if new_bin_call {
        score += 15.0 * progress;
        // Opening a bin is fine if no existing bin fits well
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Existing bin: reward being below mean residual (using up scattered space)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Slight penalty for very loose fits regardless
    if post_residual as f64 > 0.5 * bin_capacity as f64 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_norm = post / cap;

    // Base: prefer small post residual (tight fits)
    let mut score = post;

    // Non-linear polynomial coupling of residual with stream progress.
    // Early on, large residuals are more acceptable (smooth penalty grows with progress).
    let poly = residual_norm * residual_norm * (0.5 + 1.5 * progress)
             + residual_norm * (1.0 - progress);
    score += 60.0 * poly;

    // Dead-space penalty: residuals too small for any future item are worthless.
    // Smooth trough around unusable zone rather than hard threshold.
    let unusable = ((next_item_size as f64 - post) / cap).max(0.0);
    score += 25.0 * unusable * unusable * (1.0 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smooth).
    let next_fit = 1.0 - ((next_item_size as f64 - post).abs() / cap).min(1.0);
    score -= 20.0 * next_fit * next_fit;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - residual_norm);
    }

    // Prefer bins with residuals below mean (consolidate small leftovers).
    score += 10.0 * ((bin_residual as f64 - mean_residual) / cap).max(0.0);

    // New-bin candidate handling: brand-new empty bin has post == cap.
    // Penalize it smoothly unless it's a near-perfect item size (large item early).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let fill = item_size as f64 / cap;
        // Reward opening a bin for big items; penalize for small items.
        score += 15.0 * (1.0 - fill) * (1.0 + 0.5 * progress);
        score -= 10.0 * fill * fill;
        // Mild early-stream bonus to keep bins fresh for future pairings.
        score -= 5.0 * (1.0 - progress) * fill;
    }

    // Slight preference for reusing bins over opening new ones, decaying with progress.
    score += 3.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" classes (0..=10) are excellent (tight fit) -> reward strongly.
    let small_class = post_residual <= 10;
    let mid_class = post_residual > 10 && post_residual <= 25;

    if small_class {
        score -= 30.0;
    } else if mid_class {
        score -= 8.0;
    } else {
        // Large leftover: penalize dead space, scaled by how dead it is.
        score += (post_residual as f64 / cap) * 20.0;
    }

    // Modulo-10 harmony: post_residual divisible by 10 pairs well with
    // typical item sizes; give a mild discount.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, this is
    // a perfect chain -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits but not perfectly: mild reward proportional.
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: penalize small unusable leftovers more.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large or the mean residual across open bins is very small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        score += 45.0
            - 30.0 * item_frac
            - 20.0 * (1.0 - mean_residual / cap) * progress;
    }

    // Slight preference for bins with residuals below mean (consolidate
    // fullness into fewer bins).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: gaps too small to hold any item (min size 1..~10)
    // are wasted; penalize them heavily, scaled by how "stuck" the stream is.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        score += 15.0; // risky zone: only tiny items can use it
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual > 0 {
        score -= 20.0 * (1.0 - post_residual as f64 / 40.0).max(0.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but allow new bins when open bins have low mean residual (poor fits).
    if bin_residual == bin_capacity {
        // new-bin candidate: base penalty so it only wins on bad fits
        score += 30.0 + open_bins_count as f64 * 2.0;
        if mean_residual < 15.0 {
            score -= 35.0; // open bins are nearly full -> new bin is fine
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0; // lookahead won't fit anyway
        }
    } else {
        // existing bin: slight preference to keep bins balanced / close them out
        score += open_bins_count as f64 * 0.5;
        // if the next item fits exactly in post_residual, reward strongly
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0; // next item can't use this bin's remainder
        }
    }

    // Progress-aware tightening: later in the stream, be more conservative
    // about dead space since fewer chances to recover.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap == 0.0 {
                score -= 150.0; // chain of perfect fits
            } else {
                // reward proportional to how snugly next item fits
                score -= 60.0 * (1.0 - gap / bin_capacity as f64);
                // penalize leaving a gap that nothing small can use
                if gap < 10.0 {
                    score += 40.0; // tiny dead gap after next item
                }
            }
        } else {
            // next item won't fit here: penalize more if we leave large unusable residue
            if post_residual < 10 {
                score += 30.0; // dead space below min item size
            } else {
                score += 10.0;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer filling already-open bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0;

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // neutral-ish baseline; good fits in existing bins will score lower
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity)
    score += (post / cap) * 10.0;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0;
        // extra reward when next item fills the remaining space exactly-ish
        let gap = post - next_item_size as f64;
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
    } else if next_item_size > 0 {
        // penalize creating dead space that the next item cannot use
        score += 4.0 * (post / cap);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins that are already tight before placement if fit is loose
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // nearly perfect fill
    } else if post_residual >= 10 && post_residual < item_size {
        // residual smaller than any plausible future item -> dead space
        score += 6.0;
    }

    // Time horizon: late in the stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0 * (mean_residual / cap);

    // Many open bins: prefer spreading to reduce mean residual variance pressure
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (post_residual as f64) < (next_item_size as f64) * 0.5);
        if bad_fit {
            score -= 20.0;
        } else {
            score += 12.0; // discourage opening new bins when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: post residual, scaled by stream progress (dead space matters more later)
    let mut score = pr * (1.0 + 2.0 * progress * progress);

    // Smooth polynomial coupling: reward tight fits via (1 - pr)^2
    score -= (1.0 - pr) * (1.0 - pr) * 3.0;

    // Penalize residuals that are too small to be useful (smooth ramp)
    let useless = (0.25 - pr).max(0.0) / 0.25;
    score += useless * useless * 6.0 * (0.5 + progress);

    // Lookahead: reward if next item fits the post-residual (smooth kernel)
    if next_norm > 0.0 {
        let diff = pr - next_norm;
        let kernel = (-diff * diff * 40.0).exp();
        score -= 4.0 * kernel * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward for using it
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else {
        // Mild penalty when many bins compete (prefer spreading)
        score += (fitting_bins_count as f64).ln() * 0.4;
    }

    // Mean residual coupling: prefer bins near the mean residual (balanced use)
    let mean_norm = mean_residual / cap;
    let dev = pr - mean_norm;
    score += dev * dev * 2.0;

    // New-bin candidate handling: penalize opening a new bin early,
    // reward it late when open bins are poor fits
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 3.0 * (1.0 - progress);
        score -= 1.5 * progress;
    }

    // Mild penalty for too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let q = (bin_capacity as f64) / 8.0;
    let band = (post_residual as f64 / q).floor() as i32; // 0..8

    // Penalize dead space nonlinearly, worst near small-but-unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    score += (post_residual as f64).powi(2) / (bin_capacity as f64) * 0.4;

    // Harmonic classes of item size via modulo arithmetic (classic 1/2, 1/3, 1/4 splits).
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Reward tight fits (post_residual small) strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= quarter {
        score -= 25.0;
    } else if post_residual <= third {
        score -= 10.0;
    }

    // Modulo coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Extra harmonic reward if next item's class matches the residual band
        let next_class = (next_item_size as f64 / q).floor() as i32;
        if next_class == band {
            score -= 10.0;
        }
    }
    // Penalize if next item would be blocked (residual too small for it but nonzero).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mild penalty so we prefer reusing bins unless residual is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if current bin would leave dead space smaller than next item, new bin looks better.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 35.0;
        }
    }

    // Mean residual coupling: prefer placing into below-average-residual bins (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progress-based tie-break: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (100.0 - post_residual as f64) * progress * 0.1;

    // Integer-division threshold: items in (half, capacity) are "big" — prefer near-full bins.
    if item_size > half {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: residuals in [1, 9] are nearly unusable
    // (min item size is 1, but statistically small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Residuals in [10, 25] are partially usable: mild penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current item + next item can
    // combine nicely, or open bins are crowded / fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // If the next item fits together with the current one in a fresh
        // bin, opening is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 55.0;
        }
        // Many open bins with low mean residual -> prefer packing into them.
        if open_bins_count > 0 && mean_residual < item_size as f64 * 1.3 {
            score += 30.0;
        }
    } else {
        // Favor bins whose residual can still host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Prefer tighter bins (less waste of large residual).
        score += (bin_residual as f64 - item_size as f64) * 0.05;
        // Open-bin pressure: with many open bins, discourage spreading.
        score += open_bins_count as f64 * 0.8;
    }

    // Early stream: be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness;

    // 2-step lookahead: if next item exactly fits the post_residual, big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Penalize leaving residual that is just barely too small for next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: minimize wasted space strongly.
        score += 20.0 * (post_residual as f64);
    }

    // Reward bins with residual below mean (compact usage), penalize above mean.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only fitting bin, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when good fits exist, especially early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - 0.3 * progress);
        // Opening a new bin is fine if item is large and next item could fill the rest.
        if next_item_size > 0 && (next_item_size as i64 - post_residual as i64).abs() <= 5 {
            score -= 20.0;
        }
    }

    // Slight preference to fill bins with more items already packed (fewer open bins better).
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) more aggressively via quadratic shaping.
    score -= ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 30.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins; encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin, but less when current bin
    // would leave a very large residual that no small next item can use.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 15.0 + 0.3 * waste;
        // If next item is small, an open bin with residual >= next_item is fine;
        // opening a new bin is less necessary -> stronger penalty.
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual {
            score += 20.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0;
    } else if next_item_size > 0 {
        // Next item won't fit here anyway; slightly penalize leaving awkward residual.
        score += 3.0;
    }

    // Deviation from mean residual: prefer bins whose residual is already below average
    // (concentrate filling) unless this is the new-bin candidate.
    if bin_residual != bin_capacity {
        score += 0.2 * (bin_residual as f64 - mean_residual).abs();
    }

    // Time horizon: early in the stream, be conservative about opening bins;
    // late in the stream, allow more freedom since fewer items remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear shaping
    let mut score = r.powf(1.0 + 0.5 * progress) * (1.0 + 0.3 * rn);

    // Smooth polynomial coupling: penalize large residuals more as stream progresses
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 40.0 * (rn * rn) * (0.5 + p2);
    score -= 10.0 * rn * (1.0 - p3);

    // Dead-space penalty: residuals too small for typical future items
    let dead = ((20.0 - r).max(0.0)) / 20.0;
    score += 25.0 * dead * dead * (1.0 + progress);

    // Lookahead: reward residuals that can host the next item
    if next_item_size > 0 {
        let fits_next = (r as f64 - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            score -= 8.0 * fits_next * (1.0 - progress);
        } else {
            score += 6.0 * (-fits_next) * (0.5 + p2);
        }
    }

    // Last-chance bin bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Congestion term: many open bins -> prefer tightening existing bins
    let congestion = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 15.0 * congestion * rn * rn;

    // Mean residual coupling: if mean residual is large, tolerate waste; if small, be picky
    let mrn = mean_residual / cap;
    score += 10.0 * (mrn - rn) * (mrn - rn) * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless residuals elsewhere are hopeless
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress) - 15.0 * mrn * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 classes of 10.
    let class = post_residual / 10;
    // Dead-space penalty grows superlinearly for small unusable residuals.
    if post_residual < 10 {
        score += 40.0;
    } else {
        score += (10 - class as i32).max(0) as f64 * 1.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward when next item exactly matches residual class (harmonic pairing).
            let pair = post_residual.saturating_sub(next_item_size);
            if pair == 0 {
                score -= 60.0;
            } else if pair < 10 {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to wasted lookahead.
            score += 5.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * (1.0 - progress);
        // Allow new bin only if mean residual is very tight (fragmented state).
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        // Prefer tighter bins: reward small residuals relative to mean.
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.2;
    }

    // Modulo harmonic bonus: residuals that are multiples of common item sizes
    // (10/20/25/50) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Mild preference for consolidating when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit even the smallest
    // plausible future item are pure waste -> heavy penalty.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 35 {
        score += 10.0;
    }

    // Reward near-perfect fits (small but usable residual).
    if post_residual > 0 && post_residual <= 15 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer filling it rather than opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this residual -> the leftover is likely dead space
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins, but a new
    // empty bin candidate should be penalized when decent fits exist.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // New-bin candidate: only attractive when it enables a large upcoming item
    // or existing residuals are fragmented/small.
    if bin_residual == bin_capacity {
        let base = 25.0 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 20.0;
        }
        score += base;
    } else {
        // Prefer bins tighter than the mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect pair: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Post-residual too small for next item: dead space penalty if unusable
        if post_residual < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit only
        score -= 10.0;
    }

    // Reward bins below mean residual (filling emptier bins first keeps balance)
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate slightly unless post_residual is perfect for lookahead
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Late in stream: tighten packing, avoid leaving scattered small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but exact fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    }

    // Penalize dead space relative to capacity: wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use leftover space: penalize proportionally.
            score += 6.0;
        }
    } else {
        // Last item: any residual is pure waste; strongly prefer tightest.
        score += 20.0 * waste_frac;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current
    // fits are poor. Give the empty bin a mild baseline penalty that grows with
    // how many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // But late in the stream with big lookahead mismatch, allow new bins more.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * t;
    }

    // Global state coupling: prefer filling bins whose residual is far from mean
    // (balance residual diversity to preserve a wide range of usable gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for bins that are already well-filled.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: polynomial in post_residual with progress modulation
    let x = post / cap; // normalized post residual in [0,1]
    let p = progress;

    // Base: prefer tight fits (small post_residual), with progressive sharpening
    let mut score = x * (1.0 + 2.0 * p * p) + 4.0 * x * x * (0.5 + p);

    // Penalize dead space that likely cannot be reused later in the stream
    let avg_item = if total_items > step_index + 1 && item_size > 0 { item_size as f64 } else { item_size as f64 };
    let unusable = (x - (avg_item / cap).min(x)).max(0.0);
    score += 6.0 * unusable * unusable * (1.0 + p);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * p;
    }

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 1.5 * (1.0 - (post - nx) / cap);
        } else {
            score += 1.5 * (nx - post) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * (open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0))) * (0.5 + p);

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * (1.0 - p) - 2.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, or large enough to host typical items)
    // are favored. Dead-space classes (small odd residues) are penalized.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let class = pr % 10;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect fit
    } else if pr >= 50 {
        class_bonus -= 25.0; // roomy bin, still very usable
    } else if pr % 20 == 0 {
        class_bonus -= 18.0; // harmonic even class
    } else if class <= 5 {
        class_bonus += 12.0; // awkward sliver
    }

    // Integer-division threshold: how many average items (~25) still fit
    let slots = pr / 25;
    class_bonus -= 6.0 * slots as f64;

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx == pr {
            class_bonus -= 40.0;
        } else if nx < pr {
            class_bonus -= 10.0 * (1.0 - (pr - nx) as f64 / cap as f64);
        } else {
            class_bonus += 8.0; // next item won't fit here; keep bin flexible anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        class_bonus -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly; scale with fragmentation
        class_bonus += 35.0 + 10.0 * (open_bins_count as f64).sqrt() - 20.0 * progress;
    }

    // Deviation from mean residual: prefer bins that reduce dispersion
    score += class_bonus;
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual > 0 && post_residual <= 20 {
        score -= 15.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual > 0 && post_residual < 10 {
            score += 70.0; // undo: dead space here is worse than a new bin
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(1.0) * 4.0;
    if bin_residual != bin_capacity {
        score -= pressure * (item_size as f64 / bin_capacity as f64);
    } else {
        // New-bin candidate: penalize moderately; allow opening only when bins are few
        // or the stream is early.
        score += 30.0 - 12.0 * (open_bins_count as f64).ln().max(0.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0) * (1.0 - diff / 100.0).max(0.0);
        // Bonus if post_residual can still hold next item with small slack
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Penalize tiny dead space (<10) that no item can ever use, unless it exactly matches lookahead.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_residual as f64 - item_size as f64).max(0.0);
        score = bin_capacity as f64 - 10.0 + waste_if_open * 0.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin supports the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base; amplify it.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits, but reward proportional to how well it fills afterwards
            let second_post = post_residual - next_item_size;
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
            if second_post < 10 && second_post > 0 {
                score += 8.0;
            }
        } else {
            // next item won't fit here; slight penalty if we leave a large awkward gap
            if post_residual as f64 > mean_residual {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.15 * crowding * (bin_residual as f64 - mean_residual).abs() * 0.1;

    // Early phase: keep bins flexible (prefer balanced residuals); late phase: pack greedily.
    if progress < 0.3 {
        score += 0.2 * (bin_residual as f64 - mean_residual).abs();
    } else {
        score -= 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate handling: only prefer a fresh bin when current bins are crowded
    // and this bin's fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.6;
        if poor_fit && open_bins_count > 2 && progress > 0.1 {
            score -= 15.0; // prefer opening a new bin
        } else {
            score += 30.0; // otherwise discourage new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth dead-space penalty: small residuals are bad, penalized more later.
    score += 60.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Reward tight fits: polynomial in item/capacity ratio.
    let fit_ratio = item_size as f64 / cap;
    score -= 40.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Lookahead coupling: bonus if next item fits the post residual (smooth term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = (pr - nxt).max(0.0) / cap;
        score -= 25.0 * (1.0 - compat).powi(2) * (1.0 - progress);
    }

    // Last-chance bonus: few fitting bins, penalize alternatives smoothly.
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    } else {
        score += 5.0 * ((fitting_bins_count - 1) as f64).ln().min(3.0);
    }

    // Mild pressure from mean residual and open-bin count.
    score += 0.1 * (mean_residual - pr).abs();
    score += 0.5 * (open_bins_count as f64).powf(1.2) * progress;

    // New-bin candidate: neutral baseline, penalized mildly when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residual mod small moduli indicates
    // how "reusable" the leftover space is for typical item sizes.
    let pr = post_residual as i64;
    let mod10 = (pr % 10) as f64;
    let mod20 = (pr % 20) as f64;
    let mod25 = (pr % 25) as f64;

    // Residuals that are multiples of 10/20/25 align with common item sizes
    // drawn from integer ranges -> these leftovers are more likely reusable.
    if pr % 10 == 0 { score -= 4.0; }
    if pr % 20 == 0 { score -= 3.0; }
    if pr % 25 == 0 { score -= 2.5; }
    // Very small dead space (<10) is nearly unusable since min item is 1..100,
    // but tiny leftovers relative to typical sizes are penalized mildly.
    if pr > 0 && pr < 10 { score += 6.0; }

    // Dead-space penalty grows superlinearly for unusable mid-range leftovers
    if pr > 0 && pr < 20 { score += (20 - pr) as f64 * 0.5; }

    // Modulo-class coupling between post_residual and next_item_size:
    // if the next item could exactly consume a harmonic class of the leftover,
    // reward this bin strongly.
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if n <= pr {
            if pr % n == 0 { score -= 8.0; }               // perfect future fill
            else if pr % (n * 2) == 0 { score -= 5.0; }    // two future fills
            else {
                let waste = pr - (pr / n) * n;             // leftover after next fill
                score += waste as f64 * 0.6;               // penalize misaligned class
            }
        } else {
            // next item too big for leftover: leftover becomes dead space
            score += 3.0 + mod10 * 0.2;
        }
    } else {
        // last item: prefer exact fill
        score -= 5.0 * (1.0 - pr as f64 / bin_capacity as f64);
    }

    // Integer-division threshold on post_residual: bins whose residual falls
    // into "large usable" band (>= 50) are valuable reservoirs.
    let band = pr / 25; // 0..4 harmonic band
    score -= band as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild preference for tighter fits already handled;
    // add small penalty proportional to open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good harmonic fit and item is large.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && {
            let best = post_residual; // for empty bin, post == capacity - item
            let _ = best;
            false
        };
        let _ = good_fit_exists;
        // Reward opening a new bin for large items (poor future flexibility otherwise)
        if item_size >= 51 {
            score -= 6.0;
        }
        // Penalize new bins when stream is nearly done or many bins open
        score += (step_index as f64 / total_items.max(1) as f64) * 4.0
               + open_bins_count as f64 * 0.3;
        // If the item would leave a harmonic-class residual in a fresh bin, bonus
        let fresh_post = (bin_capacity - item_size) as i64;
        if fresh_post % 10 == 0 || fresh_post % 25 == 0 { score -= 3.0; }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's
    // already "specialized"; slight bonus to keep filling it.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Final small shaping: prefer exact-fill classes via capacity fraction
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= (fill_frac * 10.0).floor() * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    }
    // Residuals that can only fit a narrow band of items are semi-dead space.
    if post_residual >= 10 && post_residual < 25 {
        score += 30.0 + (25 - post_residual) as f64 * 2.0;
    }

    // Perfect or near-perfect fits are highly rewarded.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 - (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; if this bin becomes near-dead, penalize.
            if post_residual < 20 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over opening new ones; with few open bins, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins; penalize proportionally, but relax when the
    // current fit would create dead space anyway.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.8;
        if post_residual < 25 && post_residual > 0 {
            score -= 10.0; // still better than fragmenting an open bin badly
        }
    }

    // Slight preference for tighter bins overall (small residual before placement).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this bin is ideal for a two-item sequence.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild bonus proportional to leftover match.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Post residual cannot host next item: dead space penalty scaled
            // by how close it is to the next item (wasted opportunity).
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / 100.0);
        }
    }

    // Compare post_residual against mean residual: leaving a residual below
    // the mean helps reduce overall fragmentation.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((post_residual as f64) - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so a fresh bin is opened only when no
    // open bin offers a reasonable fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, prefer consolidating into open bins even more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 20.0;
        }
    }

    // Mild preference for bins that are already fairly full.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = post_residual as f64 / cap;
    score += 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual < next_item_size && next_item_size > 0 {
        score += 8.0 * (1.0 - post_residual as f64 / cap);
    }

    // Reward bins whose residual can exactly or nearly fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 6.0 * (1.0 - gap as f64 / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidating into existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - tightness);

    // Global state coupling: if mean residual is high, we have slack; prefer
    // bins below the mean residual (tighter bins) to preserve loose bins.
    score += 3.0 * ((mean_residual - bin_residual as f64) / cap);

    // New-bin candidate handling: opening a new bin is attractive only when the
    // item is large relative to capacity or no good fit exists.
    if is_new_bin {
        let large_item = item_size as f64 / cap;
        let poor_fit_everywhere = fitting_bins_count <= 1;
        // Early stream: new bins are cheap; late stream: prefer filling existing bins.
        let time_bonus = 6.0 * (1.0 - progress);
        let penalty = 10.0 * (1.0 - large_item) + if poor_fit_everywhere { -8.0 } else { 6.0 };
        score += penalty - time_bonus;
        // A fresh bin has perfect post-residual for the next item if next item is small.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 3.0;
        }
    } else {
        // Slight preference for bins that are already partially filled (less fragmented).
        score -= 2.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Late in the stream, tighten everything: minimize leftover space aggressively.
    score *= 1.0 + 0.5 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening.
    let mut score = pr + 30.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling: as stream progresses, tighten tolerance for dead space.
    let tight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * tight * norm_pr * norm_item;

    // Reward bins whose post-residual matches the next item (lookahead fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 25.0 * (1.0 - gap) * (1.0 - progress);
    }

    // Penalize residual mismatch with mean residual (avoid fragmenting spread).
    score += 8.0 * ((pr - mean_residual) / cap).abs();

    // Last-chance bonus: smooth in 1/fitting_bins_count.
    if fitting_bins_count > 0 {
        score -= 15.0 / (fitting_bins_count as f64);
    }

    // Mild preference for consolidating into fewer bins as bins accumulate.
    score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 10.0)) * (1.0 - norm_pr);

    // New-bin candidate: penalize unless current bin would leave tiny unusable space.
    if bin_residual == bin_capacity {
        score += 12.0 - 24.0 * norm_item * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes modulo common item sizes
    let pr = post_residual;
    // Residuals in {0} are perfect; tiny residuals (<10) are near-perfect dead space
    if pr == 0 {
        score -= 50.0;
    } else if pr < 10 {
        score -= 20.0;
    } else {
        // Penalize residuals that no future item class can fill well
        let class_penalty = match pr % 10 {
            0 => -6.0,          // multiples of 10 are highly reusable
            5 => -2.0,          // half classes moderately reusable
            _ => 3.0,           // odd fragments tend to be dead space
        };
        score += class_penalty;

        // Integer-division thresholds: how many "average items" fit in the leftover
        let avg_item = 40.0f64.min(cap * 0.4);
        let fits_count = (pr as f64 / avg_item).floor();
        score -= fits_count * 4.0;
    }

    // Reward tight fits relative to capacity fraction
    let fill = item_size as f64 / cap;
    score -= fill * 15.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        if fragmentation < 0.25 || open_bins_count == 0 {
            score -= 30.0; // prefer fresh bin when existing ones are cramped
        } else {
            score += 20.0 + fragmentation * 30.0; // discourage hoarding empty bins
        }
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps below the minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strong penalty for dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual) beyond raw value
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 5.0;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress) * 0.3;

    // Prefer bins below mean residual (consolidating space)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New empty bin candidate: penalize unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual < next_item_size && post_residual > 0;
        if bad_fit {
            score -= 20.0; // allow opening a new bin when this placement creates dead space
        } else {
            score += 30.0; // discourage opening new bins on good fits
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: item fills bin exactly to fit next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the residual left behind (near-perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: dead-space penalty.
        score += 0.35 * post_residual as f64;
    }

    // Reward tight fits relative to mean residual.
    let fit_tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 25.0 * fit_tightness;

    // Penalize leaving residual far above the mean residual (fragmentation).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it would be a clean fit for the next item too.
    if bin_residual == bin_capacity {
        let mut new_bin_score = item_size as f64 * 0.8;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            new_bin_score -= 20.0;
        }
        score = score.min(new_bin_score + 10.0);
    }

    // Late in the stream, be more conservative with new bins (consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item leaves a still-usable residual.
            let nr = post_residual - next_item_size;
            if nr >= 10 {
                score -= 6.0;
            }
        } else if next_item_size > bin_residual {
            // Next item can't fit this bin anyway; residual waste here is fine.
            score -= 4.0;
        } else {
            // Next item fits bin now but would be blocked by this placement.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate when existing bins can fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 25.0 + 5.0 * (fitting_bins_count as f64);
        } else {
            score -= 20.0;
        }
    }

    // Mild preference for filling bins below the mean residual (balance avoidance).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Late in the stream, be more conservative about leaving tiny residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * progress;
    }

    // Slight penalty for many open bins: prefer consolidating into fewer bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * coupling;
    // Reward near-perfect fits smoothly
    let fit = 1.0 - norm_pr;
    score -= 25.0 * fit * fit * fit;
    // Penalize dead space below plausible next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 0.3 * (pr - nx).min(30.0);
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Mild pressure toward consolidating bins
    score += 0.05 * open_bins_count as f64 * norm_pr;
    // New-bin candidate: penalize opening a bin when open bins fit
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: dead space value depends on divisibility
    // by common item-friendly denominators of capacity (100).
    let cap = bin_capacity as f64;
    if post_residual > 0 {
        let pr = post_residual;
        // Residuals that are multiples of 10 remain "usable" by typical sizes.
        if pr % 10 == 0 {
            score -= 20.0;
            if pr % 20 == 0 {
                score -= 15.0;
                if pr % 50 == 0 {
                    score -= 20.0;
                }
            }
        } else if pr % 5 == 0 {
            score -= 8.0;
        } else {
            // Odd dead space is penalized more as it shrinks.
            score += (10 - (pr % 10)) as f64 * 1.5;
        }

        // Dead space too small for the minimum plausible item (<= 5) is worthless.
        if pr <= 5 {
            score += 60.0;
        } else if pr < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: reward if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 30.0;
            if gap % 10 == 0 {
                score -= 10.0;
            }
            if gap > 40 {
                score += (gap - 40) as f64 * 0.5;
            }
        } else {
            // Next item cannot use this bin's remainder anyway: mild penalty
            // proportional to unusable leftover.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Integer-division thresholds on post_residual (harmonic bands).
    let band = post_residual / 25; // 0..4
    score -= match band {
        0 => 40.0, // residual < 25: nearly full, good
        1 => 15.0,
        2 => 0.0,
        3 => -5.0,
        _ => -10.0, // residual >= 100: empty bin
    };

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it only wins when
    // all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin pairs nicely with next item if current item is huge
            if item_size >= 70 {
                score -= 20.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    // Progression: later in stream, tighten packing (favor filling existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Slight preference to balance residuals toward mean.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard reward for perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward bins whose residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0; // dead space relative to next item
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + pressure;
    } else {
        score -= pressure * 0.05;
        // Prefer bins tighter than the mean residual (good consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual matches next_item_size,
    // so the next item can fill this bin exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Next item fits after this placement: reward closeness to perfect chain.
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
            if diff < 1.0 {
                score -= 15.0; // perfect two-item chain
            }
        } else {
            // Next item won't fit here afterward: penalize leaving a gap that
            // neither fits the next item nor is likely reusable.
            score += 8.0 * (post_residual as f64 / (bin_capacity as f64));
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (consolidating waste) but penalize bins far below mean (fragmentation risk).
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.5 * (res - mean_residual);
    } else {
        score += 0.3 * (mean_residual - res);
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // aggressively to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin unless current bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, reduced if many open bins are crowded
        // or the item is large relative to typical residual.
        score += 10.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity as f64) * 0.5 {
            score += 5.0; // small next item: better keep filling open bins
        }
        if mean_residual < item_size as f64 {
            score -= 12.0; // open bins mostly too small: new bin justified
        }
    }

    // Late in stream: prefer closing bins tightly rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize creating dead space that nothing can use (items >= 1)
    if post_residual > 0 {
        let dead = if (post_residual as f64) < mean_residual * 0.5 { 0.0 } else { post_residual as f64 };
        score += 0.15 * dead;
    } else {
        // perfect fill is excellent
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for leaving a gap
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 70.0;
        // cheaper to open a new bin late in the stream or when bins are crowded
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
        score -= (open_bins_count as f64).min(20.0) * 1.5;
        // opening a new bin is fine if item is large (little waste risk)
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Slight preference for bins with residual far from mean (diversity of gap sizes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * cap * 0.5;
    // penalize wasted space relative to mean residual
    score += (pr - mean_residual).powi(2) / cap;
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr).powi(2) * (0.5 + progress);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }
    // lookahead: favor leaving space for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 3.0 * (1.0 - ((pr - ni) / cap).powi(2));
        } else {
            score += 2.0;
        }
    }
    // mild penalty for opening new bins when many already open
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * (open_bins_count as f64 / (1.0 + progress * 10.0)).ln().max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 (dead-space granularity)
    let residue = post_residual % 10;
    // Small nonzero residues are nearly-unusable dead space -> penalize
    if residue > 0 && residue < 5 {
        score += 3.0 + 0.5 * (5 - residue) as f64;
    }
    // Perfect harmonics (0 or exact half) are excellent
    if residue == 0 {
        score -= 4.0;
    }
    if post_residual == bin_capacity / 2 {
        score -= 2.0;
    }

    // Integer-division harmonic: post_residual / next_item_size coupling
    if next_item_size > 0 {
        let q = post_residual / next_item_size.max(1);
        if q >= 1 {
            // next item fits here exactly or with good residue -> reward
            let next_post = post_residual - next_item_size;
            if next_item_size <= post_residual {
                score -= 3.0;
                if next_post % 10 == 0 {
                    score -= 2.0;
                }
                if next_post < 5 && next_post > 0 {
                    score += 2.0;
                }
            }
        } else {
            // next item won't fit here; if this bin is the last chance, prefer filling it
            if fitting_bins_count == 1 {
                score -= 5.0;
            }
            // penalize leaving a residue smaller than next item (stranded space)
            if post_residual < next_item_size {
                score += 2.0;
            }
        }
    } else {
        // last item: just minimize residual
        score -= 1.0;
    }

    // New-bin candidate: only attractive late in stream or when many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 6.0 + 10.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        score += penalty;
        // opening a new bin is good if mean residual is small (open bins nearly full)
        if mean_residual < 10.0 {
            score -= 8.0;
        }
    }

    // Last-chance bin reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    // Tight fits (large item fraction of residual) rewarded
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items are "dead space". Penalize small nonzero post_residuals hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Penalize residuals too small to fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }
    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward using the last bin that can fit the item (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(12.0);
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item fits poorly everywhere else (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0) || (item_size >= 70 && fitting_bins_count <= 1);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 18.0 + 0.5 * item_size as f64;
        }
    } else {
        // Prefer bins whose residual is close to what we consume (tight fits).
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64;
        score -= 8.0 * tightness;
        // Mild bonus for placing into below-average-residual bins (more full bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

