    // Penalize dead space relative to mean residual
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.5;
    } else {
        score += diff * 0.2; // below-mean residual slightly rewarded
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 200.0 + 2.0 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // late in stream, prefer packing into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: prefer bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Leftover can't host next item: penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 40.0;
        // But if the new-bin candidate would be strictly better, allow it:
        if post_residual > bin_capacity / 2 {
            score += 25.0;
        }
    }

    // Tightness reward: bins that are already well-filled are good targets.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Global state coupling: many open bins -> encourage consolidation into
    // existing bins (penalize new bins) to reduce bin count.
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are many open bins.
        score += 15.0 + pressure * 3.0;
    } else {
        score -= pressure * 0.5;
    }

    // Time horizon: early in the stream, keep bins flexible (moderate residuals);
    // late in the stream, prioritize filling bins completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 1.5;
    score += (1.0 - progress) * post_residual as f64 * 0.3;

    // Mean-residual anchoring: prefer bins below mean residual (fill the emptier
    // ones early to consolidate), unless very late when we want tight fits.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * (1.0 - progress);
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

