    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes increasingly costly.
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snugness = (nxt / cap) * (1.0 - (pr - nxt) / cap);
            score -= 12.0 * snugness;
        } else {
            // post_residual too small for next item: penalize wasted residual.
            let waste = (nxt - pr) / cap;
            score += 8.0 * waste * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the item fits badly everywhere (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // Neutral baseline with mild penalty; only beaten by poor fits in open bins.
        score = 0.55 * cap + 0.3 * (mean_residual - pr).abs() - 5.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 3.0; // fresh bin preserves flexibility for medium next items
        }
    }

    // Mild dispersion term: prefer bins whose residual deviates from the mean
    // in the direction of tighter packing.
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
