        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Progression term: late in the stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more so later in the stream.
        score += 10.0 + 15.0 * progress;
    } else {
        score -= 2.0 * progress;
    }

    // Slight pressure toward fewer open bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    // Sizes 1..=10 are considered "filler" sizes; a post_residual below 10 that
    // cannot accommodate a typical filler item is treated as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and encourage
    // compacting into existing ones.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 2.5 * open_pressure;
    } else {
        // Reward using existing bins, scaled by how many are open.
        score -= 1.5 * open_pressure;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item cannot use the leftover: mild dead-space penalty.
            score += 10.0;
        }
    }

    // Late in the stream, tighten packing: dead space becomes more costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // Slight bias toward bins with low mean residual spread (compact bins).
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 300.0;
        } else if post >= nxt {
            // next item can still fit here: mild reward scaled by tightness
            score -= 60.0 * (1.0 - diff / cap);
        } else {
            // next item won't fit in leftover: penalize large dead space
            score += 0.35 * post;
        }
    }

    // Compare residual against mean residual across open bins
    let dev = post - mean_residual;
    score += 0.25 * dev;

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a mostly-full bin on a small item late in stream
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.3 {
        score += 40.0 * (1.0 - fill_ratio);
    }

    // New-bin candidate handling: keep it competitive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score = post + 60.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size as f64 <= cap * 0.5 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item cannot use leftover space; penalize proportionally to waste.
            score += 0.25 * (post_residual as f64) * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fits exist.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 20.0 + 40.0 * scarcity - 10.0 * progress
            - 0.15 * (item_size as f64)
            + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size > mean_residual.max(0.0) {
            score -= 8.0; // next item is big; a fresh bin helps
        }
    }

    // Mild penalty for spreading across too many open bins vs mean residual.
    score += 0.02 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_frac = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills; later, tolerate larger residuals.
    let progress_weight = 0.5 + 0.9 * progress * progress;
    score += progress_weight * (norm_pr * cap) * (norm_pr * (1.0 - norm_pr) * 4.0);

    // Penalize dead space quadratically, modulated by progress.
    score += (pr * pr) as f64 / cap * (0.3 + 1.2 * progress);

    // Reward good fit (large item fraction) with smooth saturation term.
    score -= 12.0 * fit_frac * fit_frac * (1.0 - progress * 0.5);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.3);
    }

    // Lookahead: reward leaving space for the next item (smooth kernel).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        if diff >= 0.0 {
            let x = diff / cap;
            score -= 8.0 * (x * (1.0 - x) * 4.0);
        } else {
            score += 6.0 * (-diff / cap);
        }
    }

    // Mild preference for fuller bins relative to mean residual state.
    score -= 0.15 * (mean_residual - pr);

    // Slight aversion to bin proliferation early in the stream.
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 0.8;

    // New-bin candidate: penalize opening a fresh bin unless residual is hopeless.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by modulo classes
    let pr = post_residual;
    let small_class = pr % 10;          // fine-grained harmonic class
    let class_bonus = match small_class {
        0 => 12.0,                       // post_residual multiple of 10 → highly reusable
        5 => 6.0,                        // half-class still flexible
        2 | 4 | 6 | 8 => 3.0,            // even classes moderately reusable
        _ => -4.0,                       // odd classes leave awkward dead space
    };
    score -= class_bonus;

    // Integer division thresholds: residual "harmonic bands"
    let band = pr / 10;                  // 0..10 bands of capacity fraction
    score -= band as f64 * 2.0;

    // Penalize creating tiny unusable slivers (dead space)
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does this bin's post_residual harmonize with next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or leaves another multiple-of-10 class
            let next_post = pr - next_item_size;
            if next_post % 10 == 0 {
                score -= 15.0;
            }
            score -= (next_post as f64) * 0.5;
        } else {
            // next item won't fit here: mild penalty scaled by mismatch class
            let mismatch = next_item_size - pr;
            score += (mismatch % 10) as f64 * 0.8 + 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless all alternatives are poor
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64;
        // but if item is large relative to mean residual, new bin is reasonable
        let mean_r = mean_residual.max(0.0);
        if (item_size as f64) > mean_r + 10.0 {
            score -= 40.0;
        }
    }

    // Stream progression: later in stream, tighten packing (prefer tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * progress;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum item size (10) are pure waste; gaps that cannot
    // hold the next item are also likely dead space.
    if post_residual < 10 {
        score -= 60.0; // perfect fill: strongly reward
    } else {
        // penalize gaps that are too small for the next item (likely dead)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }
        // penalize awkward mid-range gaps (hard to fill later)
        if post_residual >= 10 && post_residual < 25 {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual != bin_capacity {
        score -= open_pressure;
    } else {
        // New-bin candidate: only attractive when current bins are crowded
        // (low mean residual) or nothing fits well.
        score += 20.0 + mean_residual * 0.5;
    }

    // Slight preference for tighter fits as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when the next item exactly fills the post_residual (perfect 2-step match).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Partial match: reward proportionally to how well next item fits leftover.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 40.0 * fill;
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover; penalize dead space growth.
        score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Penalize residuals far below the mean residual (fragmenting a well-packed bin).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but reward it late in the stream when open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin can serve the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.6) * 0.05;
    } else {
        score -= 15.0; // perfect fit bonus
    }

    // Reward high fill ratio of the bin.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item won't fit here: penalize leaving a large awkward gap
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += gap * 0.15;
            }
        }
    }

    // Time horizon: early in the stream, prefer opening new bins less (conserve);
    // late in the stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Global state: many open bins with high mean residual -> encourage consolidating.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to the average residual (poor fits elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64) * 2.5;
        score += openness;
        // If current item would leave big dead space in any bin, new bin is fine.
        if item_size as f64 >= mean_residual {
            score -= 10.0;
        }
        // Late stream: discourage new bins.
        score += progress * 10.0;
        // If the item is huge, a fresh bin guarantees a good fit.
        if item_size >= 60 {
            score -= 8.0;
        }
    }

    // Small dead-space threshold: residuals that only fit tiny items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // smooth non-linear coupling of post residual with stream progress
    score -= 30.0 * x * (1.0 - x) * (1.0 + progress);
    score += 12.0 * x * x * progress;
    // penalize dead space relative to mean residual
    score += 0.4 * (pr as f64 - mean_residual).abs();
    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // lookahead: reward residual that still fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64;
            score -= 15.0 * (1.0 - slack / cap) * (1.0 - progress);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }
    // mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of small divisors) are more valuable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward post_residuals that are multiples of common item classes (10, 20, 25, 50).
    if post_residual % 10 == 0 {
        score -= 8.0;
        if post_residual % 50 == 0 {
            score -= 6.0;
        } else if post_residual % 25 == 0 {
            score -= 4.0;
        } else if post_residual % 20 == 0 {
            score -= 3.0;
        }
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Penalize awkward dead space in low harmonic bands: residue mod 10 in {1..3}
    // is nearly unusable for items >= 10.
    let dead = post_residual % 10;
    if dead > 0 && dead <= 3 {
        score += 6.0 + 2.0 * dead as f64;
    }

    // Integer-division threshold: post_residual bucketed by quarter capacity.
    let quarter = (post_residual * 4) / bin_capacity;
    score += (3 - quarter.min(3)) as f64 * 5.0;

    // Perfect fit is supreme.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility: next item keeps residue in good class
            let np = post_residual - next_item_size;
            if np % 10 == 0 {
                score -= 10.0;
            }
            score -= 3.0;
        } else {
            // next item won't fit here: penalize proportional to mismatch class
            let gap = (next_item_size - post_residual) / 10;
            score += 4.0 + gap as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bins should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // base penalty so full open bins usually win
        score += 30.0;
        // but if the stream is early and bins are few, opening is cheap-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if current item is large and mean residual is small, new bin attractive
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
        // avoid opening when item leaves a harmonic-friendly residual in an existing bin
        if post_residual % 10 == 0 && post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild pressure toward bins with larger residual (better fit quality overall).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Slight tie-breaker preferring fewer open bins (consolidation).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 80.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large leftover even if above dead-space threshold.
    if post_residual >= 10 {
        score += 0.15 * post_residual as f64;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item is large and would need a fresh bin anyway, mild reward for compacting now.
    if next_item_size > post_residual && post_residual < 10 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage opening new bins when alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 45.0 + 3.0 * fitting_bins_count as f64;
        } else {
            score += 5.0; // still slight preference to reuse if possible
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it.
        score -= 50.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild stream pressure: later in stream, be slightly more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin { score += 10.0 * progress; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item size (perfect chaining), penalize waste otherwise.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: post_residual == next_item_size -> big reward.
        if gap == 0.0 {
            score -= 25.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits: scale reward by tightness of the match.
            score -= 15.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item cannot fit: penalize proportional to leftover dead space.
            score += 0.5 * gap;
        }
    } else {
        // Last item: minimize leftover as usual.
        score += 0.1 * post_residual as f64;
    }

    // Contextual adjustment relative to mean residual across open bins:
    // prefer bins whose residual is below average (tighter bins first),
    // unless this is the last fitting bin (then avoid opening a new bin).
    let res = bin_residual as f64;
    if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to avoid opening a new bin,
        // but only if the fit is reasonably tight.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 + 10.0 * tightness;
    } else {
        // Prefer below-mean-residual bins (best-fit-like ordering).
        score += 0.3 * (res - mean_residual);
    }

    // Early in the stream, be slightly more willing to spread items
    // (keep flexibility); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    // Mild penalty for very large dead space that likely becomes unusable
    // (items are between 1 and 100; residuals < smallest plausible item are dead).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: opening a new bin is only attractive when no open bin
    // offers a tight fit. Give it a baseline penalty so it loses unless
    // existing bins have large post_residuals.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual with a superlinear term.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.6 * (pr * pr) / cap;

    // Reward high fill ratio of the bin.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 2.0 * fill;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Dead space for the known next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins,
    // keep flexibility); late in the stream, pack aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 6.0;

    // Many open bins with slack: encourage consolidating into fuller bins.
    if open_bins_count > 2 {
        score += 0.05 * open_bins_count as f64 * (1.0 - fill);
    }

    // Prefer bins whose residual is close to the mean residual (balanced usage),
    // unless this is a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when current fit is bad and there is
    // slack in the stream (early steps or few fitting bins).
    if bin_residual == bin_capacity {
        let bad_fit = pr as f64 / item_size.max(1) as f64;
        let new_bin_bonus = 12.0 * bad_fit + (1.0 - t) * 15.0;
        // If the item fits an existing bin reasonably well, discourage new bin.
        score += 30.0 - new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin accommodates the lookahead item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), with polynomial shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (leave room for future items);
    // late in the stream, penalize wasted residual more strongly.
    let w = 1.0 + 2.5 * progress * progress; // smooth quadratic ramp
    score += w * 30.0 * x * x;

    // Cubic interaction: mid-stream, moderately tight fits are extra valuable
    score += 12.0 * (1.0 - x) * x * (progress * (1.0 - progress) * 4.0);

    // Reward scarce fitting capacity (last-chance bin) more strongly as stream progresses
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Penalize bins whose residual deviates from the mean residual (fragmentation control)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // Lookahead coupling: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n).abs();
        if pr >= n {
            score -= 18.0 * (1.0 - diff / cap);
        } else {
            score += 8.0 * diff / cap;
        }
    }

    // Mild penalty for proliferation of open bins, smoothed by progress
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // Brand-new empty bin: neutral-ish candidate; slightly favored when current bin fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * (1.0 - x) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets
    let frac = item_size as f64 / bin_capacity as f64;
    let class = (frac * 4.0).floor() as i32; // 0..3 harmonic class

    // Penalize dead space that no future item can plausibly fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual: residues near multiples of 10 are
    // more likely to be filled by items of size 10..80
    let r = post_residual % 10;
    if post_residual >= 10 {
        score -= (10 - r.min(10 - r)) as f64 * 0.8; // reward round residuals
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item exactly fills the post-residual, big bonus
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let rem = post_residual - next_item_size;
            if rem == 0 {
                score -= 20.0;
            } else if rem < 10 {
                score += 10.0; // creates sliver for next item
            }
        } else {
            score += 8.0; // next item won't fit here anyway
        }
    }

    // Tight-fit preference: reward small post_residual relative to item size
    score += (post_residual as f64 / (item_size as f64 + 1.0)) * 6.0;

    // Class-based bias: large items (class 3) should prefer tightest bins
    if class == 3 {
        score += post_residual as f64 * 0.3;
    } else if class == 0 {
        score -= post_residual as f64 * 0.05;
    }

    // Late in stream: consolidate, prefer existing bins over new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // existing bins can fit the item
        let mut nb = 15.0 + progress * 20.0;
        if fitting_bins_count > 0 {
            nb += 10.0 * fitting_bins_count as f64;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            nb -= 12.0; // reserving fresh bin for next big item can help
        }
        score += nb;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // a good "garbage absorber" for small items
    if (mean_residual - bin_residual as f64) > 0.0 && item_size <= 30 {
        score -= 6.0;
    }

    // Integer-division threshold: bins whose residual is in [50, 80] are
    // prime targets for mid-size items
    let half = bin_capacity / 2;
    if bin_residual >= half && bin_residual <= (bin_capacity * 4) / 5 {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it's too small to fit even the smallest plausible item.
    let min_dead = 8.0;
    if (post_residual as f64) < min_dead {
        score += 500.0; // creates a tiny unusable hole
    } else if (post_residual as f64) < 20.0 {
        // small gap zone: penalize proportionally, but less than dead
        score += 120.0 * (1.0 - (post_residual as f64 - min_dead) / 12.0);
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).sqrt() * 15.0;
    if bin_residual == bin_capacity {
        // candidate is a brand-new bin: apply pressure as penalty
        score += pressure;
        // still allow new bin if it would leave a large usable gap in existing bins
        if post_residual >= 40.0 {
            score += 60.0; // discourage wasting a fresh bin on tiny items
        }
    } else {
        // existing bin: reward filling it down
        score -= pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 40.0;
    }
    // If next item would leave this bin stranded, mild penalty.
    if next_item_size > 0 && next_item_size > bin_residual {
        score += 10.0;
    }

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (prefer bins that are already tight).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.8;

    // Early-stream: be a bit more willing to open bins when few exist.
    if (step_index as f64) / (total_items.max(1) as f64) < 0.1 && open_bins_count < 3 {
        if bin_residual == bin_capacity {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

