    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.3 * lookahead_waste;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize mildly
        score += 5.0;
    }

    // Relative to mean residual: prefer bins whose post_residual deviates favorably
    let mean_post = mean_residual - item_size as f64;
    score += 0.5 * (post_residual as f64 - mean_post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize dead space (small unusable residuals)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-poor unless nothing fits well
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

