    score -= (item_size as f64) * 0.55;

    // Strongly reward near-perfect packing.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize creating dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
