            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.10;
        }
    }

    // Prefer filling bins when many bins are open (reduce fragmentation).
    score += (open_bins_count as f64) * 0.6;

    // Prefer bins below mean residual (keep balanced residuals, save fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in stream, be more willing to open new bins for good fits;
    // late in stream, prefer closing out existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large relative to capacity
        // and few alternatives exist, or late in stream with many open bins.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 30.0;
        score -= large_item * 35.0;
        score += progress * 10.0;
        if fitting_bins_count > 3 {
            score += 20.0; // plenty of alternatives; new bin less costly
        }
    } else {
        // Existing bin: late in stream, reward usage more aggressively.
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let poly = prn * prn * (1.0 - progress) + prn * progress * (1.0 - prn);
    score += 8.0 * poly;

    // Reward tight fits more strongly late in the stream
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual) / cap;
    score += 6.0 * dead * dead;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: reward leaving space for the next item (smooth interaction)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fit_next = (prn * cap - ni).max(0.0) / cap;
        score -= 5.0 * fit_next * (1.0 - fit_next) * 4.0 * (1.0 - progress);
    }

    // Mild penalty for bin proliferation, smoothed by progress
    score += 0.4 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

