    // Class residuals into bands of 10 (item minimum size), rewarding residuals
    // that are exactly reusable by future small items.
    let post_class = post_residual / 10;
    let exact_fit = (post_residual % 10) == 0;
    if exact_fit {
        score -= 4.0; // leftover aligns with the item-size granularity
    } else {
        score += (10 - post_residual % 10) as f64 * 0.4; // dead space penalty
    }

    // Prefer tight fits strongly
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    } else if post_residual <= 30 {
        score -= 2.0;
    }

    // Lookahead coupling: does this bin's post residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // harmonic match: post class equals next item class
            if post_residual == next_item_size {
                score -= 18.0;
            } else if post_residual / 10 == next_item_size / 10 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            // leftover too small for next item -> likely dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: closing bins fully is free win
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        // A fresh bin is good if the current item is large and open bins are fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 6.0 + fragmentation * 0.2 - (item_size as f64) * 0.15;
        if open_bins_count == 0 {
            score -= 50.0; // must open
