    }

    // Slight preference for fuller bins (small residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Stream progression: early on, be a bit more liberal about new bins;
    // late in the stream, squeeze everything into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (fitting_bins_count as f64).recip().max(0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
