    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a brand-new bin when decent fits exist: the new-bin call
    // starts at score == capacity; make it unattractive unless the item is large
    // and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * item_size as f64;
        // but if the item is huge relative to residual of typical bins, allow it
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 60.0;
        }
    }

    // Late in the stream, tighten packing further (less tolerance for loose fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // penalize placements that strand space incompatible with the next item.
    if next_item_size > 0 && !is_new_bin {
        if post_residual >= next_item_size {
            score -= 3.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin for a marginal gain.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tight fits even more (sharpen competition).
        score += 0.2 * fitting_bins_count as f64;
    }

    if is_new_bin {
        // New-bin candidate: moderate default score. It should win against very poor
        // fits (large post_residual in existing bins) but lose to decent fits.
        // Slightly cheaper to open when few bins are open; costlier late in stream
        // if many bins are already open with usable space.
        score += 2.0 + 0.4 * open_bins_count as f64 - 2.0 * t;
    } else {
        // Prefer bins that are tighter than the fleet average (low dead-space risk),
        // but avoid over-concentrating when mean residual is already tiny.
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 4.0 * rel;
        // Mild time pressure: as the stream progresses, favor consolidation
        // (closing out existing bins) over spreading items.
        score -= 1.5 * t * (bin_residual as f64 / bin_capacity as f64);
    }

    // Small penalty for creating very small unusable slivers (dead space).
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr + 0.4 * norm_pr * norm_pr);

    // Penalize post-residuals that are dead space (too small for typical future items)
    let dead_threshold = 10.0;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * (2.0 + 3.0 * progress);
    }

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (cap - pr) * 0.15 * (1.0 + progress);

    // Last-chance bonus: strongly favor using this bin if it's the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item fits into resulting residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin mildly, scaled by progress
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.1 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod 10.
    // Small dead-space classes (1..9 mod 10) are the least reusable -> penalize.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        match class {
            0 => score -= 12.0,                  // perfectly aligned residual, highly reusable
            1..=4 => score += 8.0 + (5 - class) as f64 * 2.0, // tiny dead space, worst case
            5..=9 => score += (10 - class) as f64 * 0.8,      // medium class, mild penalty
            _ => {}
        }
    }

    // Perfect fit is best.
    if pr == 0 {
        score -= 40.0;
    }

    // Coupling with next item: harmonic match between post_residual and next_item_size.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // next item exactly fills this bin
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            let gap_class = gap % 10;
            // reward if leftover gap after next item is a "clean" class (0 or >=10)
            if gap == 0 {
                score -= 25.0;
            } else if gap_class == 0 {
                score -= 10.0;
            } else if gap < 5 {
                score += 6.0; // would leave tiny dead space
            }
        } else {
            // next item won't fit here; if this bin is the last chance, force use
            if fitting_bins_count == 1 {
                score -= 20.0;
            } else {
                score += 5.0;
            }
        }
    } else {
        // last item: prefer zero residual
        score += pr as f64 * 0.5;
    }

    // Integer-division thresholds on post_residual: bins with residual >= half capacity
    // remain flexible; heavily penalize residuals in awkward mid-range via division classes.
    let half_class = pr / 25; // 0..4 classes
    match half_class {
        0 => { if pr > 0 { score += 6.0; } }        // nearly full bin: good if item placed
        1 => score -= 3.0,                          // residual 25-49: decent
        2 => score -= 6.0,                          // residual 50-74: very flexible
        _ => score -= 2.0,                          // large residual: mild preference
    }

    // Last-chance bin bonus scaled by stream progress.
    if fitting_bins_count == 1 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tight_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual - item_size) >= 0;
        // baseline cost of opening a new bin
        score = (bin_capacity - item_size) as f64 + 18.0;
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a new bin anyway
        }
        // open new bin early if mean residual across open bins is small (all bins tight)
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // next item won't fit the fresh remainder either; discourage
            score += 8.0;
        }
        let _ = tight_exists;
    } else {
        // slight preference for fuller bins (waste-aware)
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Mild penalty for proliferating bins when many are open with slack.
    if open_bins_count > 3 && mean_residual > 30.0 && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // gap too small for the minimum item -> dead space, big penalty
        score += (10.0 - pr) * 8.0;
    } else if pr == 0.0 {
        // perfect fit: strong reward
        score -= 25.0;
    } else if pr < 20.0 {
        // awkward small gap that only fits a few item sizes
        score += (20.0 - pr) * 2.5;
    }

    // Reward tight fits relative to bin residual (waste ratio)
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 12.0;
    }

    // If next item can use the post_residual, reward leaving exactly that gap
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0; // leaves room perfectly for lookahead item
        } else if post_residual >= next_item_size {
            score -= 4.0; // next item still fits here
        } else {
            score += 3.0; // next item won't fit in the leftover
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if this bin is much emptier than average, prefer filling it
    score -= (mean_residual - pr).max(-50.0).min(50.0) * 0.3;

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad gap
    if bin_residual == bin_capacity {
        // baseline competitiveness of a fresh bin
        score = (bin_capacity - item_size) as f64 + 10.0;
        if post_residual < 10.0 {
            score -= 20.0; // item nearly fills a fresh bin -> great to open new bin
        }
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Near-match: next item fits with small slack left over.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0);
    }
    // Next item does NOT fit in the resulting residual: penalize if the
    // leftover is small (dead space), mildly reward large leftovers.
    else if next_item_size > 0 && post_residual < next_item_size {
        if post_residual < 10 {
            score += 40.0; // unusable dead space
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are tight
    // (poor fits) or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let poor_fits = (post_residual as f64) > mean_residual + 20.0;
        let tight = fitting_bins_count <= 1;
        if poor_fits || tight {
            score -= 25.0;
        } else {
            score += 50.0; // discourage opening new bins when fits exist
        }
    }

    // Reward placing into bins with residual below the mean (tight packing).
    let mean_diff = mean_residual - bin_residual as f64;
    score += 0.3 * mean_diff.max(-40.0);

    // Slight preference for using already-open bins as stream progresses.
    if bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize large post-residual quadratically, but reward perfect fits.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward filling bins that waste little relative to capacity.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward;
    // if next item would be stranded by leftover space, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // leftover dead space relative to next item
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.15 * gap;
        }
    }

    // Time horizon: early in stream, be more open to starting bins (spread);
    // late in stream, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: cheaper early, expensive late
        score -= 20.0 * (1.0 - progress);
        score += 25.0 * progress;
        // discourage new bins when many bins already open with room
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Global residual pressure: high mean residual means slack exists, be pickier.
    score += 0.05 * mean_residual;
    // Slight penalty for accumulating too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, but with non-linear saturation
    let mut score = (norm_pr.powf(1.4)) * cap;

    // Smooth coupling: as stream progresses, penalize residual more strongly
    let progress_weight = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_weight;

    // Non-linear interaction of post_residual with mean residual deviation
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * cap - 6.0 * dev * cap;

    // Reward tight fits (small post residual relative to item)
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 20.0 * tightness * tightness;

    // Last-chance bin bonus (avoid opening new bins needlessly)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
    }

    // New-bin candidate: penalize opening bins early, allow late in stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 - progress);
        // discourage new bin if any open bin fits well
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 25.0;
        }
    }

    // Small bonus for perfectly filling a bin
    if post_residual == 0 {
        score -= 10.0;
    }

    // Mild penalty scaling with open bins count to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "large residue"
    // classes are less attractive (waste), while small residues are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quotient/remainder decomposition of post_residual relative to capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 harmonic class
    match class {
        0 => { score -= 30.0; }                       // near-perfect fit
        1 => { score -= 10.0; }                       // good fit
        2 => { score += 0.0; }
        3 => { score += 15.0; }                       // poor fit
        _ => { score += 5.0; }                        // empty-bin class handled below
    }

    // Modulo coupling: post_residual divisible by common item sizes is reusable
    let mod_penalty: f64 = if post_residual == 0 {
        -25.0
    } else {
        let mut m = 0u32;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 { m += 1; }
        }
        -6.0 * m as f64
    };
    score += mod_penalty;

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0; // next item won't fit here -> dead space risk
        }
    }

    // Last-chance bin: only fitting bin, avoid opening new bin unless residual is tiny
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly; only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 35.0 + 0.1 * (open_bins_count as f64);
    } else {
        // prefer tighter-than-average bins
        score -= (mean_residual - pr).clamp(-50.0, 50.0) * 0.3;
    }

    // Late-stream consolidation: favor filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Dead space in mid-range gaps is also risky (few item sizes fit).
    if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit into post_residual, mild penalty (wasted future space).
    if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer placing into existing bins when many are open,
    // making the new-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 3.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (best-fit bias).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be more willing to open bins for good structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // next fits, reward tightness
        } else {
            // next item cannot fit here; penalize leaving medium dead space
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 20.0 {
                score += 15.0; // unusable sliver
            }
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins)
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let good_fit = (bin_residual - item_size) as f64;
        let base = 40.0
            + if next_item_size > 0 && next_item_size <= item_size { 0.0 } else { 10.0 };
        // if an open bin would leave tiny waste, avoid new bin
        if fitting_bins_count > 0 {
            score += base;
        } else {
            score -= 10.0; // must open a new bin anyway
        }
        let _ = good_fit;
    }

    // Slight stream-progression pressure: later in stream, tighten packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // Mild penalty proportional to waste created
    score += 0.3 * post_residual as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score -= (1.0 - fit_ratio) * 30.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 20.0;
            // Extra reward if next item exactly fills remaining space.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Dead space the next item can't use: penalize proportionally.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Global state coupling: prefer bins with residual far from mean residual
    // (keeps a diverse residual portfolio for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.08 * dev;

    // Time horizon: early in the stream, be more conservative (favor tight fits,
    // penalize opening new bins); late in stream, be more permissive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Many open bins: mild pressure to fill existing ones rather than open more.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin is a fallback; make it expensive
    // unless no open bin can fit (fitting_bins_count == 0) or fits are terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            score += 45.0 + 0.5 * item_size as f64; // prefer filling existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear waste penalty: quadratic in normalized post-residual
    score += 40.0 * norm_post * norm_post;

    // Polynomial coupling of post-residual with stream progress:
    // early on, prefer tight fills less aggressively; late, punish slack strongly
    let coupling = norm_post * norm_post * (1.0 - progress) - norm_post * progress;
    score += 30.0 * coupling;

    // Reward placements that leave room for the lookahead item (smooth cubic interaction)
    if next_item_size > 0 {
        let fit_gap = (norm_post - norm_next).abs();
        score -= 25.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * norm_item;
    } else {
        // last item: strongly favor minimal final residual
        score -= 60.0 * (1.0 - norm_post);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize spreading residual far above/below the mean across open bins
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate shaping: make empty bin attractive only when item is large
    // or no good fit exists, via smooth interaction with item size and progress
    if bin_residual == bin_capacity {
        let large_item = norm_item * norm_item;
        score -= 20.0 * large_item * (0.5 + progress);
        score += 25.0 * (1.0 - large_item) * (1.0 - progress);
    }

    // Mild penalty for opening many bins early
    score += 2.0 * open_bins_count as f64 * progress * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: residual modulo 10 — small dead space classes are penalized
    let r_mod = post_residual % 10;
    if post_residual > 0 {
        score += match r_mod {
            0 => -20.0,                    // clean class: residual usable by 10-multiples
            1..=3 => 15.0 + 5.0 * r_mod as f64, // tiny dead space, worst waste class
            4..=6 => 5.0,
            _ => -5.0,                     // 7..=9 leaves room for mid-size items
        };
    }

    // Integer-division thresholds: how many 10-units remain
    let units = post_residual / 10;
    score -= units as f64 * 2.0;

    // Lookahead coupling: does post_residual fit the next item exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = if post_residual > 0 && post_residual < 10 { 200.0 } else { 0.0 };
        score += 40.0 - waste - progress * 30.0;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are penalized heavily.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 * (min_useful as f64 - post_residual as f64);
    }

    // Dead space relative to the next item's needs (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Reward tight fits: post_residual near zero (but usable) is great.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Perfect fit into a fresh bin is ideal.
    if bin_residual == bin_capacity && post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the next item when it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: penalize spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin before opening a new one: strong bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight nudge toward bins with below-average residual (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Early in the stream, allow opening bins more freely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: lower score for small post_residual
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain match
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that placement
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
        } else {
            // next item does not fit here -> dead space risk
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (compact bins)
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early stream: slightly prefer reusing existing bins (consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if the fit would be perfect-chain in a fresh bin, allow it
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_ratio * waste_ratio;

    // Perfect or near-perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // chain fit: next item also nearly fills after the lookahead
            let chain = post_residual as f64 - next_item_size as f64;
            if chain < 10.0 {
                score -= 6.0;
            }
        } else {
            // dead space unless post_residual is small enough to be negligible
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - waste_ratio);

    // Global state: if this bin's residual is far below the mean, it's a good filler target.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be conservative with new bins;
    // late in the stream, waste matters less, tighten toward exact fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * waste_ratio;
    score -= progress * 5.0 * waste_ratio;

    // New empty bin candidate: only attractive when no open bin fits well
    // (large residual gap to item) or stream is early and item is large.
    if bin_residual == bin_capacity {
        let gap = (bin_capacity as f64 - item_size as f64);
        score = gap + 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let prog_curve = progress * (1.0 - progress) * 4.0; // peaks mid-stream, 0 at ends
    score += 12.0 * pr_norm * pr_norm * (1.0 + prog_curve);
    score -= 18.0 * pr_norm * prog_curve;

    // Penalize tight fits less as stream advances (dead space matters more early)
    let tightness = (pr_norm - 0.5) * (pr_norm - 0.5);
    score -= 8.0 * (1.0 - progress) * (1.0 - tightness);

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as i32 as f64;
        score -= 10.0 * fits_next * (1.0 - (pr - nx) / cap).abs();
        score += 5.0 * (1.0 - fits_next) * pr_norm;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins deviating from mean residual (consolidate)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // Mild penalty for spreading across many bins late in stream
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that cannot host any
    // future item of the known minimum size is worst.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // exact fit already handled, keep safe
    }

    // Modulo-arithmetic "harmonic classes": residuals divisible by common
    // item sizes are more reusable. Reward residuals divisible by small
    // harmonic denominators (2,4,5,10) since many item sizes cluster there.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr % 10 == 0 { harmonic_bonus += 8.0; }
    if pr % 20 == 0 { harmonic_bonus += 4.0; }
    if pr % 25 == 0 { harmonic_bonus += 3.0; }
    if pr % 50 == 0 { harmonic_bonus += 2.0; }
    score -= harmonic_bonus;

    // Penalize residuals in awkward classes (odd small remainders).
    let class = pr % 10;
    if class == 1 || class == 3 || class == 7 || class == 9 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            // next item fits: penalize by leftover after next placement
            let pr2 = pr - next_item_size;
            score += pr2 as f64 * 0.3;
            if pr2 % 10 == 0 { score -= 5.0; }
        } else {
            // next item cannot use the residual: mild penalty scaled by waste
            score += (pr as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we prefer
    // filling existing bins unless the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if current item is large relative to capacity, opening fresh
        // is fine (keeps big items from fragmenting bins).
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (best-fit flavor).
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 && res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.05;
    }

    // Late in the stream, consolidate aggressively to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.05;

    // Prefer fewer open bins: slight penalty proportional to bin count.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // plausible future item (<= 10) are nearly worthless -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < item_size.min(20) {
        // Gaps smaller than the current item's class are likely dead space too.
        score += 25.0;
    }

    // Reward tight fits: post_residual close to zero is good (subtract).
    let tightness = 1.0 - (post / cap);
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0; // chain fit leaves no dead space
        } else {
            score -= 10.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement creates a gap the next item cannot use.
        score += 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight fit exists elsewhere.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual < 10 {
            score += 60.0; // but dead space still dominates
        }
    }

    // New-bin candidate: make it attractive only when all open fits are poor.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // baseline = residual left in fresh bin
        if fitting_bins_count > 0 {
            // Only prefer a new bin if every existing fit would leave dead space.
            score += 5.0; // slight handicap so decent fits win
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host current + next item
        }
    }

    // Mild stream-phase modulation: early on, keep options open.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - phase) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: squared post-residual punishes dead space super-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect chain: next item exactly fills post-residual -> strong reward.
        if (post_residual as u32) == next_item_size {
            score -= 40.0;
        }
        // Next item fits into post-residual: reward proportionally to how snugly.
        if next_item_size <= post_residual {
            let slack2 = post_residual as f64 - nxt;
            score -= 18.0 * (1.0 - slack2 / bin_capacity as f64);
            // Bonus if the chain nearly closes the bin completely.
            if slack2 <= 5.0 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here: penalize leaving medium-sized holes
            // that are too small for the upcoming item (dead space trap).
            let gap = nxt - post_residual as f64;
            if post_residual > 0 && gap <= 20.0 {
                score += 14.0 * (1.0 - gap / 20.0);
            }
        }
    } else {
        // Last item of stream: strongly prefer tightest final fit.
        score -= 30.0;
    }

    // --- Relative-to-mean residual anchoring ---
    // Prefer bins whose residual is close to the item (deviation from mean
    // indicates an outlier hole; align with the pack of open bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.35 * dev;

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this bin can take the item: avoid opening a new bin unless
        // the fit is terrible.
        score -= 25.0;
        if post_residual <= 10 {
            score -= 20.0; // near-perfect fill of the last fitting bin
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty-bin candidate: penalize so it's chosen only when open bins
        // offer genuinely bad fits. The penalty shrinks late in the stream
        // and when many bins are already open (fragmentation pressure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 10.0 * progress - 0.5 * open_bins_count as f64;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly (wasted capacity grows quadratically).
    score += 0.6 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Reward tight fits: small post_residual gets a bonus.
    if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 25 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward this bin.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if next_item_size <= post_residual {
            score -= 10.0 - (gap as f64).min(10.0) * 0.4;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Many fitting bins: mild penalty to prefer diversity of residual profiles.
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize
    // cramming less); late in stream, conserve by favoring existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    // Global residual pressure: if mean residual is high, encourage filling bins
    // with large residuals (this bin's residual above mean => bonus).
    let resid_f = bin_residual as f64;
    let dev = resid_f - mean_residual;
    score -= 0.05 * dev;

    // Few open bins relative to progress: encourage opening bins early to spread load.
    let expected_bins = (step_index as f64) * (item_size as f64 / bin_capacity as f64) + 1.0;
    if (open_bins_count as f64) < expected_bins {
        score += 1.0;
    }

    // Brand-new bin candidate: neutral baseline with slight preference when the
    // item is large (large items deserve fresh space) or existing fits are poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if item_size > 60 {
            score -= 3.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Tight fits rewarded more strongly as stream progresses (smooth coupling)
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize very small dead space relative to smallest possible item (smooth)
    score += 6.0 * (pr_norm * (1.0 - pr_norm)).powi(2) * (1.0 - progress);

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual (smooth falloff)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 5.0 * gap * gap;
    }

    // Mean residual coupling: prefer bins near mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Crowding penalty: many open bins -> favor filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm) * 2.0;

    // New-bin candidate: mild penalty so it only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: bins with small post-residual are "tight fits".
    let pr = post_residual;
    let class = pr / 10; // integer division class 0..10
    score += match class {
        0 => -25.0,          // near-perfect fit: strong reward
        1 => -12.0,
        2 => -6.0,
        3 => 0.0,
        4 => 4.0,
        5 => 8.0,            // half-empty: mildly bad
        6 => 6.0,
        7 => 3.0,
        8 => 10.0,
        9 => 18.0,
        _ => 0.0,            // untouched/new bin
    };

    // Modulo harmonic coupling: leftover that is a multiple of common item sizes is reusable.
    if pr >= 10 && pr <= 80 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
    } else if pr > 80 {
        // large leftover: still very reusable, small penalty removed
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 6.0;
            // harmonic match on residual class
            if (pr / 10) == (next_item_size / 10) { score -= 4.0; }
        } else {
            score += 5.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when all open residuals are poor.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        // base cost of opening a new bin
        score += 12.0;
        // open fewer bins late in the stream; open more early when stream is long
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        if open_bins_count < 2 { score -= 25.0; }
        if mean_residual < 25.0 { score -= 15.0; } // existing bins are cramped -> new bin good
        if mean_residual > 60.0 { score += 20.0; } // plenty of room in open bins -> avoid new bin
    }

    // Mild tie-break: prefer bins whose residual is closest to item size (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible future item are "dead space". Penalize them hard,
    // proportionally to how far below the viability threshold they fall.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }

    // Unusable-gap penalty: if post_residual is small but nonzero, it is likely
    // wasted. Penalize sharply as post_residual approaches 0.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small but usable leftovers) super-linearly.
    if post_residual > 0 {
        score -= (bin_capacity as f64 / post_residual as f64).sqrt() * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is less costly.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has full residual. Make it
    // attractive only when the current item is large relative to open-bin
    // residuals or when mean residual across open bins is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit_quality = 1.0 - (mean_residual / bin_capacity as f64);
        // Prefer new bin when open bins are fragmented (low mean residual means
        // they are mostly full) or many bins are open.
        score -= 20.0 * mean_fit_quality + 10.0 * progress;
        // Discard new-bin option if a very tight fit exists elsewhere.
        if post_residual == 0 {
            score += 100.0;
        }
    }

    // Lookahead coupling: if the next item would fit into this bin's
    // post_residual, reward the placement (enables chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would NOT fit anywhere else either, mild penalty for
    // leaving a gap the successor cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mild normalization of raw residual preference over the stream.
    score += (post_residual as f64) * (0.5 - 0.3 * step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual is better, non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that no plausibly arriving item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack / 20.0);
        } else {
            // next item cannot fit here; penalize large leftover a bit more
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.3;
        }
    }

    // Compare against mean residual: prefer bins that are already fuller than average.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score += (mean_residual - residual_f) * 0.4; // penalize emptier-than-average bins
    } else {
        score -= (residual_f - mean_residual) * 0.2; // reward fuller-than-average bins
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in the stream, be slightly more willing to keep bins consolidated;
    // later, allow spreading to reduce fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (open_bins_count as f64) * 0.5;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening fresh bin may serve both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted space relative to capacity (dead space shaping).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Reward tight fits.
    score -= (item_size as f64 / bin_residual as f64) * 15.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        // Next item won't fit here; slight penalty for leaving awkward residual.
        score += 6.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins.
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 1.5;
    }

    // Global residual pressure: if mean residual is large, prefer bins below mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: late in the stream, be more conservative (fill tightly, avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits, new bin is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        - 30.0 * norm_pr * (1.0 - progress)
        - 20.0 * norm_pr * norm_pr * progress
        + 15.0 * norm_pr * norm_pr * (1.0 - progress) * progress;

    // Penalize dead space relative to mean residual (smooth cubic coupling)
    let dead = (pr - mean_residual) / cap;
    score += 40.0 * dead * dead * dead.abs().max(0.0) * (0.5 + progress);

    // Lookahead: reward leaving space for the next item
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - (gap / cap)) * (0.5 + 0.5 * progress);
        } else {
            score += 8.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to reuse existing bins as stream matures
    score += 0.05 * open_bins_count as f64 * (0.3 + progress) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable" classes.
    let r = post_residual % 10;
    // Residuals divisible by 10 (or 5) are more likely reusable by future items.
    let harmonic_bonus = match r {
        0 => -12.0,
        5 => -6.0,
        1 | 9 => 4.0,
        2 | 8 => 6.0,
        3 | 7 => 8.0,
        _ => 10.0,
    };
    score += harmonic_bonus;

    // Integer-division threshold: small post_residual = dead space penalty.
    let div_class = post_residual / 10; // 0..=10
    if div_class == 0 {
        score += 15.0; // nearly full bin, fine but low flexibility
    } else if div_class <= 2 {
        score += 5.0;
    } else if div_class >= 8 {
        score -= 4.0; // large leftover, still flexible
    }

    // Lookahead harmonic coupling: can next item land exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect future fit
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // mod-based coupling: gap in {0,5,10} classes is attractive
            if gap % 10 == 0 {
                score -= 8.0;
            } else if gap % 5 == 0 {
                score -= 4.0;
            } else {
                score += (gap as f64) * 0.3;
            }
        } else {
            // next item cannot fit here regardless; slight reward for filling bin
            score -= 3.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer fresh bin if all open bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Open new bin when mean residual is low (open bins nearly full).
        score = 45.0 + 40.0 * pressure - 20.0 * progress;
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mild preference for tighter bins overall (deviation from mean residual).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are fine,
    // but residuals that waste space relative to typical upcoming needs are penalized hard.
    // Treat gaps < 10 as fully dead (unusable for items >= 10 style streams) unless exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (post_residual as f64 + 1.0);
    score -= tightness * 2.0;

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if post_residual is awkwardly just below the next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading into a fresh bin;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items as f64;
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline at capacity, adjusted by pressure and progress.
        score = bin_capacity as f64 - 10.0 + pressure * 3.0 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin good for large lookahead
        }
    } else {
        // Existing bin: mild penalty scaling with open bins to encourage consolidation.
        score += open_bins_count as f64 * 0.5;
        // Prefer bins with below-mean residual (consolidating waste).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post-residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            // Perfect chain fit: post_residual exactly equals next item size
            if gap < 1.0 {
                score -= 35.0;
            } else {
                // Reward closeness of next fit, scaled by how much slack remains
                let closeness = 1.0 - (gap / bin_capacity as f64);
                score -= 25.0 * closeness * closeness;
            }
        } else {
            // Next item cannot chain into this bin: penalize leftover dead space
            score += (nxt - pr) * 0.5;
        }
    }

    // Compare post_residual against mean residual: avoid leaving this bin far
    // above average slack unless it creates a perfect next-fit
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.1; // slightly reward below-average residual
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly-full bin on a small item
    if bin_residual < item_size * 2 && item_size < 30 {
        score += 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the item fits badly everywhere (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let bad_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if progress < 0.15 || bad_fit || fitting_bins_count == 0 {
            score -= 12.0;
        } else {
            score += 25.0; // discourage opening new bins mid-stream for decent fits
        }
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
