pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let fit_norm = pr / cap;
    // Core: quadratic coupling of post-residual with stream progress
    let mut score = pr * (1.0 + 0.8 * fit_norm * fit_norm) * (1.0 + 0.6 * progress);
    // Reward tight fits: subtract for small relative post-residual
    score -= 30.0 * (1.0 - fit_norm) * (1.0 - fit_norm);
    // Smooth interaction: post_residual vs mean residual deviation
    score += 0.15 * (pr - mean_residual).abs();
    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }
    // Lookahead: penalize if next item cannot use the leftover space smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 8.0 * (nx - pr) / cap;
        } else {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        }
    }
    // New-bin candidate handling: early on prefer new bins for small items,
    // later prefer filling existing bins (smooth ramp)
    if bin_residual as u32 == bin_capacity {
        score += 12.0 - 20.0 * progress + 0.05 * item_size as f64;
    }
    // Mild penalty for proliferation of open bins
    score += 0.4 * open_bins_count as f64 * (0.5 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable" bands
    // (small enough to be closed by common items) are rewarded.
    let pr = post_residual;
    let class = pr / 10; // integer division into deciles of capacity
    match class {
        0 => score -= 25.0,               // near-perfect fit: dead space ~0
        1 => score -= 15.0,               // excellent
        2 | 3 => score -= 8.0,            // good: fits medium items
        4 | 5 => score -= 2.0,            // neutral band
        6 | 7 => score += 6.0,            // awkward half-empty bin
        _ => score += 12.0,               // nearly empty placement wastes a bin
    }

    // Modulo coupling: leftover that is congruent to small-item sizes is valuable.
    let small_hit = (1..=9).any(|k| pr % 10 == k && (10..=30).contains(&(pr % 40)));
    if small_hit { score -= 5.0; }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64) * 0.4; // tighter lookahead fit is better
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate handling: empty bin is a fallback; make it attractive
    // only when the item is large relative to capacity or many bins are open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 - frac * 55.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin is fine
        }
    }

    // Stream progression: early on, keep bins tight; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Exact-fill bonus via modulo arithmetic on capacity fraction.
    if (bin_capacity - pr) % 25 == 0 && pr < 25 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are the worst outcome; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using bins with small residuals (tight packing) relative to mean.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && !new_bin_candidate {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item almost fits, slight penalty for wasting the gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + (next_item_size as f64) * 0.5;
            // chain fit: next item also leaves room (small dead space after chain)
            let chain_residual = post_residual - next_item_size;
            score -= 20.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
        } else {
            // dead space penalty scaled by how far off the next item is
            score += 15.0 + (next_item_size as f64 - post_residual as f64).min(40.0) * 0.4;
        }
    }

    // Penalize large leftover relative to mean residual (avoid hoarding space)
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current bin would leave unusable sliver
    if bin_residual == bin_capacity {
        let sliver = post_residual > 0 && post_residual < 10;
        if next_item_size > 0 && post_residual >= next_item_size && !sliver {
            score += 50.0; // an open bin can chain; don't open new
        }
        if sliver { score -= 30.0; }
        score += 10.0; // mild default bias toward existing bins
    }

    // Tight-fit reward: small post_residual generally good
    score -= 0.2 * (bin_capacity as f64 - post_residual as f64);

    // Late-stream consolidation: fewer bins preferred near end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to hold typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < item_size.min(40) {
        score += 8.0; // hard-to-refill space
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for hoarding when alternatives exist? Actually prefer filling existing bins.
        score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves waste; reward proportional to how well it fills
            let fill_after = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 * fill_after;
        } else {
            // next item won't fit here; penalize slightly more as post_residual grows
            score += 0.05 * (post_residual as f64);
        }
    } else {
        // Last item in stream: just minimize waste.
        score -= 5.0 * tightness;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowded = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score -= 0.02 * crowded * (0.5 + progress);

    // New-bin candidate handling: empty bin should only win when the fit here is poor
    // or residuals everywhere are tiny. Give empty bin a base handicap.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress; // opening new bins gets costlier over time
        if mean_residual < 15.0 && fitting_bins_count <= 1 {
            score -= 25.0; // but allow fresh bin when existing bins are nearly full
        }
    }

    // Time horizon: early in stream, be slightly exploratory (favor spreading via mild penalty on tight fits);
    // late in stream, consolidate aggressively.
    score *= 1.0 - 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate slack
    // to keep bins flexible, so the coupling weight decays with progress.
    let coupling = (1.0 - progress).powf(1.7);
    let mut score = pr * (0.55 + 0.45 * coupling);

    // Penalize residual below the smallest plausible item (dead space),
    // with a smooth quadratic ramp rather than a hard cutoff.
    let dead = (norm_pr * 10.0).powi(2);
    score += dead * (1.0 + progress);

    // Reward bins whose post-residual still matches the next item (lookahead fit).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 8.0;
    } else {
        // Last item: maximize fill, reward minimal post_residual.
        score -= (cap - pr) * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // New empty bin candidate: penalize mildly so it is chosen only when
    // open bins would create large dead space or when few bins are open.
    if bin_residual == bin_capacity {
        let slack_penalty = (mean_residual / cap).max(0.0);
        score += 6.0 + 10.0 * slack_penalty * (1.0 - progress);
    }

    // Mild preference for consolidating into few bins.
    score -= (mean_residual - pr) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that pair well with
    // typical small items (which fit into residuals of 10..=30) are penalized less.
    let post = post_residual;
    let class_penalty: f64 = if post == 0 {
        -25.0 // perfect closure: strongly reward full bins
    } else if post < 10 {
        30.0 // dead space below the minimum item size: unusable
    } else if post <= 30 {
        0.0 // usable by small items
    } else if post <= 50 {
        6.0
    } else if post <= 70 {
        2.0
    } else {
        0.0
    };

    // Modulo coupling: residuals that are multiples of common item granularities
    // (5, 10, 20) tend to admit exact future pairings.
    let mod_bonus: f64 = if post > 0 {
        if post % 10 == 0 { -4.0 }
        else if post % 5 == 0 { -2.0 }
        else if post % 20 == 0 { -5.0 }
        else { 1.5 }
    } else {
        0.0
    };

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    let lookahead_bonus: f64 = if next_item_size > 0 {
        if next_item_size == post {
            -20.0
        } else if next_item_size < post {
            // partial fit: mild reward scaled by fill fraction
            -3.0 * (next_item_size as f64 / post as f64)
        } else {
            // next item cannot use this residual: penalize small leftovers more
            4.0 * (1.0 - post as f64 / bin_capacity as f64)
        }
    } else {
        0.0
    };

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    let last_chance: f64 = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -8.0
    } else {
        0.0
    };

    // Prefer bins tighter than the mean residual (best-fit flavor), damped early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_coupling: f64 = 2.0 * progress * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // New-bin candidate: discourage opening a new bin when decent fits exist,
    // but allow it when the item is large and open bins would be badly fragmented.
    let new_bin_penalty: f64 = if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        10.0 + 25.0 * fragmentation - (item_size as f64 / 4.0)
    } else {
        0.0
    };

    score += class_penalty + mod_bonus + lookahead_bonus + last_chance + mean_coupling + new_bin_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the typical next item (lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward exact fit for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bins pressure: penalize spreading across many open bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when open bins are few or fit is poor.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        if post_residual < 20 {
            score -= 30.0; // big item in fresh bin is fine
        }
    }

    // Prefer filling bins with low residual relative to mean (tight packing).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Slight progression pressure: pack tighter later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits too: reward proportional to how snugly
            score -= 100.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit: penalize dead space potential
            score += 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));
        }
    }

    // Penalize large residual relative to mean residual (wasteful bins)
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        score += 150.0;
        // open new bin if next item is large and current bin would fragment
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 100.0;
        }
    }

    // Slight preference for tighter fits overall
    score += (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if is_new_bin {
        // Brand-new empty bin candidate: attractive when the item is large
        // (small post_residual => efficient packing) or when no open bin fits.
        score -= 6.0 * (item_size as f64 / 100.0);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: opening is mandatory anyway
        }
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 4.0; // leftover of a fresh bin likely still usable if item was big
        }
        // Slight resistance to opening bins when many are already open.
        score += 0.5 * open_bins_count as f64;
    } else {
        // Dead-space penalty: residuals too small to hold any future item (min size 1..100 stream)
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 8.0;
        }

        // Lookahead synergy: reward bins whose remainder can host the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 3.0;
        }

        // Last-chance bonus: this is the only open bin that fits the item.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Tight-fit reward: fraction of the bin consumed by this placement.
        if bin_residual > 0 {
            score -= (item_size as f64 / bin_residual as f64) * 4.0;
        }

        // Mild pressure against over-fragmenting across many open bins late in stream.
        if open_bins_count > 8 {
            score += 1.0 + 0.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let norm_post = post_residual as f64 / cap;
    let norm_item = item_size as f64 / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    score += 12.0 * norm_post * norm_post * (0.5 + progress);
    score -= 8.0 * norm_item * (1.0 - progress) * (1.0 - progress);
    // reward tight fits more strongly as stream progresses
    score -= 15.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.3 + 0.7 * progress);
    // penalize deviation from mean residual (fragmentation control)
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);
    // last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }
    // lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let next = next_item_size as f64 / cap;
        let diff = norm_post - next;
        score += 5.0 * diff * diff * (1.0 - progress);
    }
    // mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fraction lattice) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as fraction of capacity

    // Dead-space penalty: residuals in "awkward" classes (not multiples of common
    // item sizes) are penalized. Harmonic classes mod 10 / mod 20 / mod 25.
    let class10 = post_residual % 10;
    let class20 = post_residual % 20;
    let class25 = post_residual % 25;

    // Perfect harmonics (0 residual, or residual matching a common item size)
    // are strongly rewarded; odd/prime-ish residuals penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        let harmonic_bonus: f64 = match class10 {
            0 => 25.0,
            _ => match class20 {
                0 => 15.0,
                _ => match class25 {
                    0 => 12.0,
                    _ => 0.0,
                },
            },
        };
        score -= harmonic_bonus;

        // Penalize small unusable slivers (1..10) — dead space.
        if post_residual < 10 {
            score += 18.0;
        } else if post_residual < 20 {
            score += 8.0;
        }
    }

    // --- Lookahead coupling: does next item harmonically fit the post residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 14.0; // next item fits after this placement
        let slack_class = slack % 10;
        if slack_class == 0 {
            score -= 10.0; // then residual becomes harmonic again
        } else if slack < 10 {
            score += 6.0; // creates a sliver after next item
        }
    } else if next_item_size > 0 {
        // next item won't fit in this bin afterward; residual is likely dead
        score += 10.0 * (1.0 - frac);
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost, but attractive if open bins are
        // fragmented (high mean residual spread) or late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0
            + 0.35 * mean_residual
            - 20.0 * progress
            + if next_item_size > 0 && next_item_size > bin_capacity { 0.0 } else { 5.0 };
        // If the current item nearly fills a fresh bin, opening is great.
        if item_size >= 70 {
            score -= 15.0;
        }
        // Discourage opening when a good harmonic fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual % 10 == 0 && (post_residual as f64) < mean_residual {
            score += 25.0;
        }
    }

    // --- Mild regularization: prefer tighter bins when many are open ---
    score += 0.05 * (open_bins_count as f64) * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Strict dead-space avoidance: tiny gaps (below min item size) are unusable.
        score += 45.0;
    } else if post_residual < 25 {
        // Moderately small gaps are also wasteful.
        score += 15.0;
    }

    // New-bin candidate: penalize opening a new bin slightly, scaled by open-bin pressure,
    // so we only open new bins when fits in existing bins are genuinely poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.15 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bins pressure: mildly penalize leaving large residuals spread across many bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post-residual exactly/well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Reward tight two-item packing
            score -= (slack_after_next as f64) * 0.5;
            // Bonus for near-perfect two-item fill
            if slack_after_next <= 5 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.3;
        }
    }

    // Penalize dead space that nothing can use (below minimum item size 1..small)
    if post_residual < 10 {
        score -= 8.0; // small residual is fine, near-full bin
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count > 0 && post_residual >= next_item_size && next_item_size > 0 {
            score += 10.0;
        }
        // Early in stream, new bins are cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: small post_residuals that are hard to fill later
    // are fine (waste), but medium dead space (1..30) is bad.
    let pr = post_residual as f64;
    if post_residual > 0 {
        let dead = if pr < 10.0 { 0.0 } else if pr <= 30.0 { (30.0 - pr) * 0.8 } else { 0.0 };
        score += dead;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 5.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless the fit is poor; scale with stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * progress;
        // But if existing bins fit badly (high mean residual mismatch), allow new bin
        if mean_residual < item_size as f64 * 1.1 && fitting_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Prefer bins with residual close to item size (near-perfect fit detection).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * residual_gap;

    // Mild preference to fill bins with larger residuals first (keep tight bins tight)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit).
    let mut score = post;

    // Smooth non-linear tightness reward: quadratic coupling of fill ratio with progress.
    let fill = 1.0 - post / cap;
    score -= (fill * fill) * cap * (0.5 + 0.5 * progress);

    // Penalize dead space that is too small to be useful later (smooth wedge).
    let dead = post / cap;
    score += 20.0 * dead * dead * (1.0 - dead);

    // Lookahead: reward residual that can still host the next item, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0);
        let usable = fits_next / cap;
        score -= 15.0 * usable * (1.0 + progress);
        // Penalize leaving exactly-too-small gaps relative to next item (smooth).
        let gap_deficit = (nxt - post).max(0.0) / cap;
        score += 8.0 * gap_deficit * gap_deficit;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins
    // are open and mean residual is high (existing capacity is abundant).
    if bin_residual == bin_capacity {
        let abundance = mean_residual / cap;
        score += 10.0 + 25.0 * abundance * (0.5 + progress);
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fill);
    }

    // Coupling: interaction between item size and residual smoothness.
    let ratio = item / cap;
    score -= 10.0 * ratio * (1.0 - post / cap) * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect-fit classes get strong rewards
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits (dead space minimization) with non-linear squash
    let fit_ratio = (bin_capacity - post_residual) as f64 / cap;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Harmonic classes: post_residual divisible by common item sizes (10,20,25,50)
    if post_residual % 50 == 0 { score -= 12.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 4.0; }
    if post_residual % 10 == 0 { score -= 2.0; }

    // Penalize residuals in awkward class (1..10 small dead space that nothing fits)
    if post_residual > 0 && post_residual < 10 { score += 15.0; }

    // Coupling with next item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            score += 4.0 * (next_item_size - post_residual) as f64 / cap * 10.0;
        }
        // Harmonic pairing: post_residual % next_item_size == 0 means future perfect stacking
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    } else {
        // Last item: only dead space matters
        score += pr * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open bins are bad,
    // but reward it when item is large and mean residual is small (fresh capacity valuable)
    if bin_residual == bin_capacity {
        score += 18.0;
        if (item_size as f64) / cap > 0.7 && mean_residual < 30.0 {
            score -= 25.0;
        }
        if post_residual % 50 == 0 { score -= 5.0; }
    }

    // Stream progression: early on, prefer compacting into existing bins;
    // late in stream, allow more new bins since lookahead is limited
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * progress;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's fragmented; favor it slightly
    score -= (mean_residual - pr).clamp(-20.0, 20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (< 10) are almost unusable
    // (items >= 1, but typical sizes are larger), so punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (small relative waste) beyond the raw residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Dead space that can't fit the next item is extra-bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid fragmenting further;
    // prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / 20.0).min(3.0);
    score += pressure * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this item would create large dead space in every open bin,
    // or mean residual is too small for the item).
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = mean_residual < item_size as f64
            || (fitting_bins_count > 0 && post_residual > 30);
        if poor_fit_everywhere {
            score -= 45.0;
        } else {
            // Prefer filling existing bins when a decent fit exists.
            score += 50.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild preference for bins whose residual is close to the item,
    // keeping large residuals for large future items.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: item now + next item exactly fills the bin.
    if next_item_size > 0 {
        let sum = post_residual as f64 - next_item_size as f64;
        if sum == 0.0 {
            score -= 1000.0; // ideal: bin fully consumed over two steps
        } else if sum < 0.0 {
            // next item cannot fit here; dead space penalty grows with waste
            score += 0.6 * (-sum);
            // if this is the only fitting bin, still prefer it over opening a new bin
            if fitting_bins_count == 1 {
                score -= 0.5 * post_residual as f64;
            }
        } else {
            // next item fits too: reward closeness of leftover to typical residual
            score -= 0.3 * sum;
            score -= (mean_residual - sum).abs() * 0.2;
        }
    }

    // Penalize leaving tiny unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Exact fill now is excellent
    if post_residual == 0 {
        score -= 500.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current bin fits poorly
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin still viable for lookahead pairing
        }
    }

    // Mild preference for tightest bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of post-residual favors near-perfect packing.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits into the resulting residual exactly or well.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let slack_after_next = post_residual as f64 - next_item_size as f64;
        score -= 15.0 * (1.0 - slack_after_next / cap);
        if slack_after_next == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how badly it misses.
        let miss = next_item_size as f64 - post_residual as f64;
        score += 0.3 * miss.min(60.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 18.0;
        if post_residual > 0 && post_residual < 15 {
            score -= 12.0;
        }
    }

    // Penalize creating dead space that no plausible item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Global state coupling: when many bins are open, prefer consolidating into
    // low-residual bins; when few bins are open, allow spreading.
    let spread_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.5 * spread_pressure * (post_residual as f64 / cap);

    // Mean residual coupling: if this bin is far below mean residual, it is a
    // "ragged" bin; prefer filling ragged bins to homogenize residuals.
    let dev = mean_residual - post_residual as f64;
    score += 0.2 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large); late in the stream, squeeze everything in.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / cap);
    score -= 10.0 * progress * tightness;

    // New-bin candidate handling: an empty bin gets a baseline cost; opening a
    // new bin is only attractive if all fits would leave large residuals early on.
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * (1.0 - progress);
        // If many bins already open and fit is poor elsewhere, new bin is fine.
        if open_bins_count > 3 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: reward tight fits via smooth polynomial in normalized post-residual
    let mut score = pr as f64;
    score -= 40.0 * (1.0 - x) * (1.0 - x) * (1.0 - 2.0 * x * (1.0 - x));

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, dead space is more costly
    score += 30.0 * x * x * progress;

    // Penalize post-residual that cannot fit the next item (smooth interaction)
    let nx = next_item_size as f64;
    let gap = (nx - pr as f64).max(0.0) / cap;
    score += 25.0 * gap * gap * (1.0 + progress);

    // Reward when next item fits snugly after placement
    let fit_gap = (nx - pr as f64).abs() / cap;
    score -= 20.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * (nx > 0.0) as i32 as f64;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Slight penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 3.0 * x;

    // Penalize bins whose residual deviates from mean residual (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: mildly penalize so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space (harmonic class of post_residual).
    let pr = post_residual;
    if pr > 0 {
        // Dead space penalty grows sharply when post_residual is small
        // (hard to fill later), soft when large.
        let dead = if pr <= 10 {
            60.0 + (10 - pr) as f64 * 8.0
        } else if pr < 30 {
            20.0 + (30 - pr) as f64 * 0.5
        } else {
            5.0
        };
        score += dead;
    }

    // Reward if the lookahead item fits into the post residual (chained fit).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 30.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += (next_item_size - pr).min(40) as f64 * 0.6;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Many open bins with slack: prefer consolidating into fuller bins.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Early in stream: keep bins flexible (larger residuals are OK);
    // late in stream: push toward tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.3;

    // Slight preference for bins below mean residual (balance load).
    score += (mean_residual - post_residual as f64) * 0.1;

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, small residuals elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // Cheaper to open a new bin when item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // If other bins fit, discourage new bin unless they'd leave bad dead space.
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // new bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize small unusable gaps (dead space): gaps too small for typical
    // future items (min size 1, but practically gaps < ~15 are hard to reuse).
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 15.0 {
        score += (15.0 - gap) * 3.0;
    }

    // Reward gaps that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Creating a gap that cannot fit the next item is dead space risk.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // fit in existing bins is poor. The new-bin call has post_residual =
    // capacity - item_size, which is naturally large; add a mild penalty so
    // decent fits in existing bins beat it, scaled by open bin pressure.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize new-bin creation more, reward reuse).
    score += open_bins_count as f64 * 0.3 * (bin_residual == bin_capacity) as i32 as f64;

    // Prefer bins whose residual is below the mean residual (tighter bins),
    // keeping looser bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight progression term: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly or nearly fits the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits after this placement: reward tight 2-step chains
            score -= 18.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item would not fit: penalize, scaled by wasted space
            score += 6.0 + 0.25 * (post_residual as f64);
        }
        // exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize leaving dead space below the minimum item size (1..100 interface)
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 50.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Mild penalty for placing into a fresh empty bin unless lookahead justifies it
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // opening a new bin is fine if it enables a 2-step chain
        }
    }

    // Late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.1 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space relative to capacity).
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)) * 30.0;

    // Penalize bins whose residual deviates from the mean (avoid fragmentation).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.35;

    // Lookahead: if the next item also fits in the leftover space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item nearly fills the remaining space after this one.
        let combo = post_residual - next_item_size;
        score -= (1.0 - (combo as f64) / (bin_capacity as f64)) * 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: mild penalty scaled by progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (next_item_size - post_residual) as f64 * (0.1 + 0.3 * progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 22.0;
        score -= large_item_bonus;
        // Opening a new bin is costlier when many bins are already open.
        score += (open_bins_count as f64) * 1.5;
        // If several bins fit, discourage opening a fresh one.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
    }

    // Slight preference for filling nearly-full bins early in the stream.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // residual waste matters more as the stream matures.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress * progress);
    score += 20.0 * coupling;

    // Smooth reward for tight fits (small post_residual), stronger mid-stream.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= (30.0 + 40.0 * progress) * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins when many bins are open and mean residual is high.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let pressure = mean_residual / cap;
    score += new_bin * (25.0 + 50.0 * pressure * (0.3 + progress));

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= 15.0 * fits_next * (1.0 - gap) * (0.4 + progress);
        score += 10.0 * (1.0 - fits_next) * norm_pr;
    }

    // Mild penalty for spreading across too many bins early on.
    let bins_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 5.0 * bins_norm * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "nice" capacity fractions (multiples of 25) are more reusable.
    let nice = if post_residual % 25 == 0 { 12.0 } else if post_residual % 10 == 0 { 8.0 } else { 0.0 };
    score -= nice;

    // Dead-space penalty: leftover too small to host typical items (1..=10 min).
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Lookahead: strongly reward bins that can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap just below the next item is wasteful.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large and no good
    // residual class exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 25.0 + 30.0 * progress - 0.4 * item_size as f64;
        if item_size > 60 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 10.0; // next item can't share this fresh bin anyway
        }
    }

    // Slight preference for filling tight bins (low residual) first.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Mild bonus for keeping mean residual balanced.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item (1..=100)
    // can use are pure waste. Penalize unusable gaps super-linearly.
    if post_residual > 0 {
        // A gap of size g is usable if some item <= g exists; since items go
        // down to 1, small gaps are still usable, but very small gaps (< 10
        // under original regime) are effectively dead. Penalize the band
        // (0, DEAD_LIMIT) heavily.
        let dead_limit = 10.0;
        if (post_residual as f64) < dead_limit {
            score += (dead_limit - post_residual as f64) * 12.0;
        }
        // General super-linear dead-space pressure on the remaining gap.
        let g = post_residual as f64 / bin_capacity as f64;
        score += g * g * 40.0;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading across many bins when the
    // item fits acceptably; encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: if open bins are on average roomy, prefer
    // filling them rather than opening fresh capacity.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.5;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item would fit exactly into the post_residual,
    // strongly favor this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover gap: dead space likely.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit. Base penalty
    // for opening a new bin grows with stream progress (sunk capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 30.0 * progress;
        // If many open bins already fit the item, opening a new one is bad.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // If next item is small, a fresh bin wastes flexibility less; slight relief.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits (small dead space) more than linearly.
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // 2-step lookahead: if the next item fits into this bin's post-residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a residual too small to be useful for the next item.
        score += (next_item_size as f64 - post_residual as f64) * 0.1;
    }

    // Compare post-residual against mean residual: avoid making a bin an outlier
    // with huge leftover relative to the fleet average.
    if (post_residual as f64) > mean_residual * 1.2 {
        score += ((post_residual as f64) - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    // Late in the stream, tighten packing (dead space costs more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (dead space elimination).
    let fill_ratio = 1.0 - post_residual as f64 / cap;
    score -= 20.0 * fill_ratio * fill_ratio * fill_ratio;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin
    // (keeps chains of compatible items together).
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 6.0;
    }
    // Lookahead penalty: post-residual is a dead zone for the next item and
    // too small to matter — penalize leaving awkward scraps.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate: mild penalty so any decent existing fit wins,
    // but poor fits (large post_residual) still lose to opening a fresh bin.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is far from the mean residual when the mean
    // is large (target the emptiest bins for big items implicitly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.5 * dev;

    // Mild consolidation pressure: with many open bins, prefer reusing bins.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly warped by stream progress.
    let warp = 1.0 + 0.6 * progress * (1.0 - norm_pr);
    let mut score = pr * warp;

    // Polynomial coupling of normalized post-residual with progress:
    // small post-residuals (tight fits) are rewarded more as stream advances.
    let tight = 1.0 - norm_pr;
    score -= 18.0 * tight * tight * (0.4 + 0.6 * progress);

    // Penalize large dead space quadratically, weighted by open-bin pressure.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
    score += 10.0 * norm_pr * norm_pr * (0.5 + pressure);

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev - 3.0 * dev;

    // Lookahead: reward if next item fits in post-residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mildly penalize so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common sizes
    let pr = post_residual;
    let class = pr % 10;
    // Penalize awkward dead space (small nonzero residues are unusable)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Reward exact fits and residues in "harmonic" classes (multiples of 10, 25)
    if pr == 0 {
        score -= 40.0;
    } else if pr % 25 == 0 || pr % 10 == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 3.0;
    }

    // Integer-division tier on post_residual: big leftover space is valuable
    let tier = pr / 25; // 0..4
    score -= tier as f64 * 6.0;

    // Lookahead coupling: if next item fits in post_residual, this placement is great
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // extra reward if next item exactly consumes the residue class
            if next_item_size == pr {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize if residue becomes stranded
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32;
        if pressure == 1 {
            score -= 15.0;
        } else {
            // discourage opening a new bin when existing bins can take the item
            score += 20.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a good filler
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Stream progression: early on, be frugal with bins; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (pr as f64 / cap);

    // Size-fraction harmonic: reward placing large items into tight bins
    let frac = item_size as f64 / cap;
    if frac > 0.5 && bin_residual < bin_capacity {
        score -= 10.0 * frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is too small for the minimum item size (1..100 interface,
    // but conservatively treat gaps < 10 as nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 {
        // Penalize moderate gaps less; reward gaps that can still fit typical items.
        score -= 5.0;
        // If the next item fits exactly into the post residual, reward heavily.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 1.5 + 20.0;
        } else if next_item_size > post_residual {
            // Next item can't use this bin's remainder: mild penalty for stranding space.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing bins
    // over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Deviation from mean residual: prefer bins whose residual is already tight
    // (small residual relative to mean means we are consolidating).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate: empty bin should only win when the fit into open bins
    // is bad. Penalize the fresh bin by its would-be fullness loss.
    if bin_residual == bin_capacity {
        score += 30.0 + (bin_capacity - item_size) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // 2-step lookahead: strongly reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward a chained fit, especially when the chain leaves little waste.
            score -= 15.0 + (bin_capacity as f64 - slack) / bin_capacity as f64 * 10.0;
        } else {
            // Penalize when next item cannot follow into this bin's leftover.
            score += 8.0;
        }
    }

    // Compare against mean residual: bins with residual far above mean are attractive targets.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: slightly favor consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Penalize opening a new bin unless it enables a good lookahead chain.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 3.0; // new bin with chain potential is acceptable
        } else {
            score += 30.0; // discourage needless bin opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste quadratically.
    let waste = post_residual as f64 / cap;
    score += 40.0 * waste * waste;

    // Reward bins whose post-residual becomes "dead space" (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            // Penalize leaving a gap the next item can't use.
            score += 8.0 * (1.0 - (post_residual as f64 / cap));
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Global state coupling: if mean residual is low, be frugal with open bins.
    score += 0.05 * mean_residual * (open_bins_count as f64).sqrt();

    // Time horizon: early in stream, mildly favor opening new bins to spread load;
    // late in stream, strongly prefer existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 + 35.0 * t;
        // But if no open bin fits well, allow a new bin late.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        score -= 6.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let prog2 = progress * progress;
    let coupling = prn * (1.0 + 1.6 * progress) - 1.2 * prn * prn * (0.5 + prog2);
    score += coupling * cap * 0.35;

    // Penalize dead space more as stream progresses
    score += (prn * prn * prn) * cap * (0.15 + 0.45 * progress);

    // Lookahead: reward leaving room for the next item
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let diff = pr - ni;
        if diff >= 0.0 {
            score -= 3.0 * (diff / cap).powi(2);
        } else {
            score += 2.5 + (-diff / cap) * 4.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Mild preference for consolidating when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * 0.2;

    // New-bin candidate: penalize slightly so it is only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress;
    }

    // Mean-residual coupling: prefer bins whose residual is close to the mean
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity split into 4 bands.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..=4

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Penalize dead space in the lowest band (unusable sliver) more than linear.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic compatibility: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or snugly into leftover -> great chaining.
            let snug = (post_residual - next_item_size) as f64;
            score -= 60.0 - snug.min(60.0);
            if post_residual == next_item_size {
                score -= 50.0; // perfect two-item closure
            }
        } else {
            // Leftover too small for the next item: dead space likely.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap * 0.8).min(50.0);
        }
    }

    // Class-based residual shaping: prefer mid-band leftovers that remain reusable.
    match post_class {
        0 => score -= 5.0,               // tiny leftover, nearly closed bin
        1 => score -= 10.0,              // small but usable
        2 => score -= 15.0,              // half-ish residual, very reusable
        3 => score -= 8.0,
        _ => {}
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    // or when open bins are already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).sqrt() * 4.0;
        score += 25.0 + fragmentation;
        if post_residual >= quarter {
            score -= 20.0; // fresh bin keeps a healthy residual for future items
        }
        if next_item_size > 0 && next_item_size >= bin_residual / 2 {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    // Prefer bins whose residual is below mean (tighter bins first).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.2;
    } else {
        score += (res_f - mean_residual) * 0.1;
    }

    // Late in the stream, prefer closing bins out (avoid many tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Medium awkward gaps (11..=25) also mildly penalized
    if post_residual > 10 && post_residual <= 25 {
        score += 12.0 * (26.0 - post_residual as f64) / 15.0;
    }

    // Reward tight fits (exact or near-exact fills)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the item (good fit ratio)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Lookahead: if next item fits into post_residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly above tight fits
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize residual below the next item size: dead space (2-step lookahead).
    let next = next_item_size as f64;
    if next > 0.0 {
        if (post_residual as f64) >= next {
            // Reward exact match of next item into post_residual.
            let gap = post_residual as f64 - next;
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to next item.
            score += 12.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Prefer bins whose residual deviates below the mean residual (tighter packing).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for opening a new bin when many bins are open and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on leftover space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Dead space for the known next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // especially early in the stream or when many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin may pay off for large items followed by large items.
            score -= 10.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers),
    // penalize draining bins that are far above mean residual.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Slight preference for fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in stream, tighter packing valued more
    score += 20.0 * progress * norm_pr * norm_pr;

    // Penalize waste relative to mean residual (smooth quadratic coupling)
    let waste = pr - mean_residual;
    score += 0.15 * waste * waste / cap;

    // Reward using the last fitting bin (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Smooth lookahead term: reward residual close to next item size
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 25.0 * (1.0 - diff / cap).max(0.0);
    }

    // Mild penalty for proliferation of open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Penalize residuals in "dead zones": (0, 10) is nearly useless,
    // (10, 20) only fits tiny items. Reward residuals >= 50 (half-bin class).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - frac * 10.0); // steep penalty near zero
    } else if post_residual < 20 {
        score += 12.0;
    }

    if post_residual >= 50 {
        score -= 8.0; // half-bin class is valuable
    }

    // Modulo classes of post_residual relative to common item sizes (10..80 grid).
    // Residuals congruent to small multiples of 10 pair well with typical items.
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0; // aligned with the 10-grid of item sizes
    } else {
        score += m as f64; // misalignment penalty proportional to remainder
    }

    // Integer division thresholds: which harmonic slot does post_residual fall into?
    let slot = post_residual / 25; // 0..4 quarters
    score -= slot as f64 * 3.0;

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0; // chain placement possible: strong reward
            // extra reward if next item is in the same modulo class
            if (next_item_size % 10) == m {
                score -= 5.0;
            }
        } else {
            score += 6.0; // next item won't fit here
        }
    } else {
        // Last item: prefer tightest fit, dead space irrelevant afterwards.
        score = post as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current bin would
    // leave terrible dead space or the item is huge and bins are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 10.0 * progress;
        // If current item nearly fills a bin alone, new bin is attractive.
        if item_size >= 80 {
            score -= 25.0;
        }
        // If many open bins are fragmented (low mean residual), prefer new bin.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 15.0;
        }
        // If next item is large and nothing can chain, new bin is fine.
        if next_item_size >= 60 && post_residual < 20 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * tightness;

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Small residuals that could still fit a next item: mild reward.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward; if next item cannot fit, the residual is likely dead -> penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: opening a bin should be discouraged unless the
    // current bin would leave a bad dead gap or no bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If the item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: mildly prefer reusing bins when many are open,
    // scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it is a tight bin -> prefer filling it.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff.min(50.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leftover after the lookahead would fit too; reward closeness of match.
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Lookahead cannot follow into this bin; penalize dead space relative to mean residual.
        score += 0.5 * (mean_residual - post_residual as f64).abs();
    }

    // Small unusable leftovers are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = 100.0 + 40.0 * progress - 30.0 * poor_fit + (open_bins_count as f64).sqrt() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space < 5)
    if post_residual < 5 {
        score -= 60.0;
    } else if post_residual < 12 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // good chaining: residual still usable
            score -= 15.0 * (nxt / cap);
        } else {
            // dead space that next item cannot use
            let waste = (post_residual as f64) - nxt;
            if waste > 0.0 {
                score += 0.15 * waste;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates from mean (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in stream: keep bins tight (less waste tolerated)
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 0.10 * post_residual as f64;

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 5.0 + 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.85 + 0.10 * post_residual as f64;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative
        }
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.5 {
            score -= 10.0; // big next item: prefer fresh capacity
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with polynomial sharpening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr) + 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (nxt - pr).abs() / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and residual is far from mean (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // Reward tight fits non-linearly
    score -= 15.0 * fit * (1.0 - norm_pr) * (1.0 - norm_pr);

    // New-bin candidate: neutral-ish baseline, penalized early, relaxed late
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * (1.0 - progress) * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
