    // for typical future items are rewarded; tiny residues are dead space.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10; // harmonic class modulo 10
        match class {
            0 => score -= 12.0,           // round residue, highly reusable
            5 | 2 | 8 => score -= 6.0,    // decent residue classes
            1 | 9 => score += 8.0,        // near-dead residues
            _ => {}
        }
        if pr < 10 {
            score += 25.0; // unusable sliver: strong penalty
        }
    }

    // Tight fits (small post_residual) are good — reward quadratically.
    score -= ((cap - post_residual as f64) / cap).powi(3) * 30.0;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - waste as f64 / cap);
        } else {
            // next item cannot follow here; mild penalty proportional to gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
