    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < (item_size as f64 + 10.0);
        score += 45.0;
        if progress < 0.15 { score -= 20.0; }
        if crowded && fitting_bins_count > 0 { score -= 25.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 30.0; // next item is huge; a fresh bin pairs well
        }
    }

    // Prefer filling bins that are already relatively empty (consolidation).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Slight preference for fewer open bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize waste proportional to item size (large items should fill bins well)
    score += (item_size as f64) * 0.05;

    // Open bins pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 0.3;

    // Last chance bin: favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if next item is large and won't fit after this placement
    if next_item_size > post_residual as u32 && next_item_size > 0 {
        score += 5.0;
    }

    // New bin candidate: mildly penalize so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Mean residual coupling: avoid placing into bins far from mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Slight preference for bins with less residual overall
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: match post_residual against next_item_size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nr;
        if diff == 0.0 {
            // Perfect match: next item exactly fills this bin.
            score -= 1000.0;
        } else if diff > 0.0 {
            // Next item fits with leftover gap; penalize proportional to gap.
            score -= 200.0 - 3.0 * diff;
        } else {
            // Dead space: next item cannot use the leftover.
            score += (-diff) * 2.5;
        }
    }

    // Penalize very small unusable residuals (classic dead-space trap).
    if post_residual < 10 && post_residual > 0 {
        score += 150.0;
    }

    // Reward tight fits relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 50.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Mild pressure toward reusing existing bins vs opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residuals below mean (consolidate waste).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize very small post residuals.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Dead space penalty grows super-linearly for large leftovers.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64 * 2.0);
    }

    // Fill-rate preference: bins whose residual closely matches the item are best.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor matches.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it must lose to good fits.
        score += 15.0;
        // But if the item barely fits anywhere else, opening is better.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 80.0;
        }
        // Early in the stream with few open bins, spreading load is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If mean residual of open bins is small (all bins nearly full), new bin wins.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Lookahead coupling: keep room for the next item if it's large.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) < ni && (post_residual as f64) > 0.0 {
            // This bin becomes dead for the next item; penalize proportionally.
            score += 8.0 + ni / 10.0;
        } else if (post_residual as f64) >= ni {
            // Leaving exactly enough room for the next item is excellent.
            let slack = post_residual as f64 - ni;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Prefer consolidating into bins with above-average residual when open bin count is high.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Mild preference for using existing bins as the stream matures (avoid bin sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Reward tight fits strongly (small post residual gets quadratic bonus).
    score -= (cap - post) * (cap - post) / cap;

    // Smooth interaction: as stream progresses, penalize wasted space more.
    score += 6.0 * progress * (post / cap) * (post / cap);

    // Lookahead: if next item fits exactly into post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = post - nxt;
        if fit_gap >= 0.0 {
            score -= 8.0 * (1.0 - fit_gap / cap);
        } else {
            score += 3.0 * (-fit_gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins with slack exist,
    // unless the item is large relative to residual (poor fit elsewhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 * (1.0 - item / cap) * (1.0 - progress);
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Prefer bins whose residual deviates favorably from mean (consolidation).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space is quantized.
    // Class 0: 0; class 1: 1..=5 (near-perfect); class 2: 6..=15; class 3: 16..=30; class 4: >30
    let post_class: u32 = if post_residual == 0 { 0 }
        else if post_residual <= 5 { 1 }
        else if post_residual <= 15 { 2 }
        else if post_residual <= 30 { 3 }
        else { 4 };
    score += (post_class as f64) * 6.0;

    // Modulo-10 structure of post_residual: residuals divisible by 10 pair
    // well with typical item granularity.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chainability, scaled by how much slack remains after next item.
            let post2 = post_residual - next_item_size;
            score -= 5.0 + (post2 as f64).sqrt() * 2.0;
            // Bonus if next item exactly fills the bin (harmonic chain closure)
            if post2 == 0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: dead space penalty unless residual is large.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(40.0) * 0.15;
        }
    } else {
        // Last item: minimize residual directly, perfect fit dominates.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin when item is large relative to capacity (fraction > 0.6)
        // or when open bins are collectively tight and current item fits poorly anywhere.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 10.0;
        } else {
            score += 20.0 + frac * 10.0;
        }
        // If many bins fit the item, definitely use an existing one.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
    }

    // Progress pressure: later in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // "denser" already; using dense bins preserves slack elsewhere.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.05;

    // Integer-division threshold on post_residual: quarter/half capacity classes.
    let q = post_residual / (bin_capacity / 4);
    score += q as f64 * 1.5;

    // Small tie-breaker on exact residual to keep determinism and prefer tight fits.
    score += (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Softer penalty for small-ish gaps that are hard to fill
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 10.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + gap);
    }
    // If next item would leave a dead gap, penalize
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 10.0;
    }

    // Prefer bins below mean residual when bins are many (balance residuals)
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // opening a new bin is costly; make it unattractive unless dead space would be severe
            let worst_case_dead = if post_residual < 10 { 20.0 } else { 0.0 };
            score += 10.0 + open_bins_count as f64 * 0.2 - worst_case_dead;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that become (near-)empty.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // 2-step lookahead: if next item exactly fits the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            // Slack left after the hypothetical next placement.
            let after_next = post_residual - next_item_size;
            score -= 120.0 - (after_next as f64).min(60.0);
            if after_next == 0 {
                score -= 300.0;
            }
        } else {
            // Next item cannot fit here: penalize wasted lookahead potential.
            score += 40.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 2.0;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize very small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Slight preference for keeping many bins consolidated as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln() * 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving awkward dead space: residuals that are too small for
    // the smallest plausible future item (assume ~10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 3.0 * ((next_item_size as f64) - (post_residual as f64)) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits);
    // later, accept more to avoid bin proliferation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins aggressively; few bins -> allow opening new ones.
    let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when pressure is high, discount when low.
        score += 10.0 + 4.0 * pressure;
        // Opening a new bin is attractive for big items early on.
        score -= 6.0 * (1.0 - progress) * (item_size as f64) / 100.0;
    } else {
        // Existing bin: reward when there is pressure to consolidate.
        score -= 2.5 * pressure;
    }

    // Mild penalty for very loose fits regardless of state.
    if post_residual as f64 > 0.5 * (bin_capacity as f64) {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual, scaled smoothly by stream progress
    let mut score = pr * (0.8 + 0.4 * progress);

    // Non-linear polynomial coupling: quadratic dead-space penalty grows with progress
    score += 25.0 * pr_norm * pr_norm * (0.5 + progress);

    // Cubic term: heavily penalize near-empty-but-unusable residuals late in stream
    score += 10.0 * pr_norm * pr_norm * pr_norm;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 15.0 * (-pr / 20.0).exp();

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1e-9 || nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap).abs();
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Slight penalty for spreading across many open bins when mean residual is high
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: prefer opening new bins early, penalize later
    if bin_residual == bin_capacity {
        score += 10.0 * progress - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by small divisors are
    // more likely to be exactly filled by future items -> reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    if pr > 0 {
        let mut class_reward = 0.0;
        if pr % 10 == 0 { class_reward += 6.0; }
        if pr % 25 == 0 { class_reward += 4.0; }
        if pr % 5 == 0 { class_reward += 2.0; }
        // Integer-division thresholds: "tiny" dead space is bad, "usable" space is fine.
        if pr < 10 { class_reward -= 25.0; }        // dead space, almost unusable
        else if pr < 20 { class_reward -= 8.0; }
        else if pr <= 40 { class_reward += 3.0; }   // sweet zone for medium items
        score -= class_reward;
    } else {
        // Perfect closure of the bin is the best outcome.
        score -= 40.0;
    }

    // Lookahead coupling: does the next item divide into the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0;
        if pr % next_item_size == 0 { score -= 8.0; } // exact fill possible next step
    } else if next_item_size > pr {
        score += 5.0; // next item won't fit here; deprioritize slightly
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals
    // are poor (large mean residual spread / small fitting set).
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64).max(1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin, discounted when open bins are fragmented.
        score = cap * 0.65
            + (open_bins_count as f64) * 2.0
            - (mean_residual / cap) * 20.0
            - (pressure.recip()) * 10.0
            + progress * 5.0;
        // If item is large, a fresh bin is relatively more attractive.
        if item_size >= bin_capacity / 2 { score -= 10.0; }
    }

    // Mild tie-break: prefer bins whose residual is close to item_size (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual in 1..=9 is nearly dead)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward when next item can fit in the post residual (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // dead space relative to known lookahead
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // New-bin candidate: prefer opening a new bin when existing fits are poor,
    // but discourage when open bins count is already large or many bins fit.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0;
        score = 45.0 + pressure - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can also host next item
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild pressure: fewer open bins is better; discourage spreading
    score += 0.05 * open_bins_count as f64;

    // Slight preference for tighter bins (small residual) among equals
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual already handled by base).

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain: bin closed exactly after next item
        } else if next_item_size < post_residual {
            // next item fits here too; reward proportional closeness of resulting fit
            let after2 = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after2 as f64 / bin_capacity as f64);
            score += 0.15 * after2 as f64; // slight penalty for leftover after two placements
        } else {
            // next item cannot use this bin's leftover; penalize dead space more strongly
            score += 0.35 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean (tighter bins)
    // to keep loose bins available for future large items.
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // Large items are fine in a fresh bin; small items should go into existing slack
        score -= 0.4 * item_size as f64;
        // If many bins are open and mean residual is large, discourage new bins
        score += 0.1 * open_bins_count as f64 + 0.2 * mean_residual;
        // If only this new bin fits, it's mandatory anyway (bonus irrelevant but safe)
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    // Mild late-stream tightening: as stream progresses, prefer exact fits even more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * fit_ratio;

    // Penalize dead space: post_residual that is too small to hold anything (assume min item ~1,
    // but relative to capacity, tiny slivers are waste).
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 && dead < 0.05 {
        score += 25.0 * (0.05 - dead);
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight bonus for leaving roomy residual.
            score += 2.0;
        }
    }

    // Prefer filling more-opened bins (larger residual) when many bins are open, to consolidate.
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be pickier (keep residuals flexible); later, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    // Compare against mean residual: placing into an unusually empty bin (large residual vs mean)
    // is fine if it tightens the mean; penalize placing into already-tight bins unless it's a perfect fit.
    if fit_ratio < 0.95 && (bin_residual as f64) < mean_residual * 0.6 {
        score += 6.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad dead space,
    // or when item is large and residuals are all small.
    if bin_residual == bin_capacity {
        let best_possible_waste = if fitting_bins_count > 0 {
            // Some open bin fits; penalize new bin unless the fit would be very loose.
            let min_waste_elsewhere = 0.0; // unknown, use mean residual as proxy
            (mean_residual - item_size as f64).max(0.0)
        } else {
            -100.0 // no bin fits: new bin is necessary
        };
        if fitting_bins_count > 0 {
            // Open a new bin if existing fits would waste a lot (mean residual proxy).
            score += 40.0 - best_possible_waste.min(40.0);
            // Late in stream, avoid opening bins aggressively.
            score += 10.0 * progress;
        } else {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - 2.0 * progress) + norm_post * (1.0 + progress);

    let mut score = post + 12.0 * poly;

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: penalize other bins when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 6.0 * (1.0 - (nx / cap)) * progress;
        } else {
            score += 5.0 * (nx - post) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * (open_bins_count as f64 - 1.0).max(0.0) * (1.0 - norm_post);

    // Discard bins far below mean residual (poor consolidation)
    score += 3.0 * ((mean_residual - post) / cap).max(0.0);

    // New-bin candidate: only attractive early or for large items
    if bin_residual == bin_capacity {
        score += 10.0 * progress - 4.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover multiples of 10 are "reusable slots"
    let slot = post_residual / 10;
    score += match slot {
        0 => -60.0,                 // perfect fit, dead space eliminated
        1 => -15.0,                 // small but harmonically reusable slot
        2 => 5.0,
        3 => 15.0,
        _ => (slot as f64) * 4.0,   // larger leftovers mildly penalized relative to residual
    };

    // Modulo coupling: residual and item sharing a divisor => tighter packing
    let r = bin_residual;
    let s = item_size;
    if s > 0 && r % s == 0 {
        score -= 20.0; // item divides residual exactly
    }
    if post_residual % 5 == 0 {
        score -= 6.0; // leftover in a "nice" harmonic class
    }

    // Lookahead: favor bins whose leftover fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // creates dead space for the known next item
    }

    // Last-chance bonus: only one bin fits, use it rather than opening new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win for large items or poor fits
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 55.0;
        // large items (half capacity or more) justify a fresh bin
        if item_size * 2 >= bin_capacity {
            score -= 45.0;
        }
        // opening fresh is attractive when existing bins are fragmented
        if mean_residual < 0.35 * cap {
            score -= 20.0;
        }
        // early in the stream, new bins are cheap
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins: discourage sprawl
    score += (open_bins_count as f64) * 0.5;

    // Prefer tighter bins overall
    score -= (1.0 - (bin_residual as f64) / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small non-zero post_residuals are unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this leftover: penalize proportionally
        score += 0.3 * (post_residual as f64).min(15.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream.
        score += 10.0 + 2.5 * open_bins_count as f64 + 15.0 * progress;
        // But if the only fitting bin would leave a dead gap, allow new bin.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
    } else {
        // Mild penalty for using already-open bins when few are open? No:
        // favor consolidation: slight reward scaled by open_bins_count.
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    // Mean-residual coupling: prefer bins with residual near mean (balanced usage).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (waste is worse than spread)
        let pr = post_residual as f64;
        score += 0.08 * pr * pr / bin_capacity as f64;

        // 2-step lookahead: if next item fits into the post-residual, reward
        if next_item_size > 0 && next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.3 * chain_waste;
        } else if next_item_size > post_residual {
            // next item cannot chain here; penalize proportionally to leftover
            score += 5.0;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Prefer opening a new bin only when fits are terrible
    if bin_residual == bin_capacity {
        // new bin candidate: baseline score slightly above good fits
        score += 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Early in stream, be more willing to open bins (future flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= next_item_size as f64 * 0.6;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // penalize creating dead space the next item cannot use
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin carries a penalty; larger early when exploration matters less
        score += 45.0 + 25.0 * (1.0 - t);
        // Large items in a fresh bin are acceptable (small post-residual waste)
        if post_residual < 20 {
            score -= 30.0;
        }
        // If many bins are already open, prefer consolidation over expansion
        score += open_bins_count as f64 * 1.5;
    } else {
        // Last-chance bin before opening a new one: strong reward
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Reward filling bins deeply (larger item into this bin)
        score -= item_size as f64 * 0.15;
        // Tiny residual slivers are nearly dead space: reward approaching them only when deliberate
        if post_residual > 0 && post_residual < 10 {
            score -= 15.0;
        }
        // Prefer bins whose residual is close to the global mean residual (balanced packing)
        score += (mean_residual - post_residual as f64).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + progress) - norm_post * norm_post * norm_post * (0.5 + 0.5 * progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 30.0 * progress);

    // Penalize leaving residual that cannot fit the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let gap = (post - norm_next * cap).max(0.0) / cap;
        score += 15.0 * gap * (1.0 + progress);
        let snug = 1.0 - ((post as f64 - norm_next * cap).abs() / cap).min(1.0);
        score -= 8.0 * snug * snug * progress;
    }

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when bin deviates from mean residual (prefer balanced bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for fewer open bins early on
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * norm_item;

    // New-bin candidate: discourage opening a new bin unless residuals are badly fragmented
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let class = post_residual % 10;
    // Dead-space penalty: residuals that are too small to fit the smallest item (1..100, min likely small but waste matters)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }
    // Sweet spots: residuals that are exact multiples of 25 (quarter-capacity classes) are reusable
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Class-based shaping: mid-range fragments penalized
    score += match class {
        0 => -6.0,
        1..=3 => 8.0,
        4..=6 => 3.0,
        7..=9 => 5.0,
        _ => 0.0,
    };

    // Coupling with next item: does post_residual fit next_item_size exactly or well?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // reward chains: post_residual can host next item
            score -= (next_item_size as f64) * 0.35;
            if slack == 0 {
                score -= 15.0; // perfect pairing
            } else if slack < 10 {
                score += 6.0; // creates new sliver
            }
        } else {
            // next item cannot fit here; residual is terminal unless big
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer new bin only when no good harmonics exist
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.55;
        // if existing bins are fragmented (high mean residual relative to capacity), new bin is fine
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        // if item is large relative to mean residual, new bin favored
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
        // early stream: opening bins is cheap investment
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    }

    // Slight preference to fill tighter bins overall
    score -= (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste — penalize them heavily.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // Marginal zone: likely dead space unless a tiny item arrives.
        score += 18.0 + (20 - post_residual) as f64 * 1.5;
    } else {
        // Usable residual: reward proportionally (subtract) so larger usable
        // leftovers are preferred over tighter-but-risky fits.
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let chain_dead = post_residual - next_item_size;
            if chain_dead < 10 {
                score -= 10.0 - chain_dead as f64; // chained but leaving dead space
            } else {
                score -= 6.0;
            }
        } else {
            // Next item cannot follow into this bin's remainder — slight penalty
            // since the residual will likely sit idle one step.
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only open bin that fits, using it
    // avoids opening a new bin — reward it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins dilute residual capacity; discourage
    // spreading across bins when a tight fit exists elsewhere.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins tighter than the mean residual (best-fit flavor) early on,
    // but relax late when consolidation matters more.
    let tightness = mean_residual - bin_residual as f64;
    score -= tightness * (1.2 - 0.8 * progress);

    // New-bin candidate handling: only attractive when the item is huge relative
    // to capacity or no open bin fits well (fitting_bins_count == 0 is implied by
    // the empty-bin call being competitive). Penalize opening new bins mildly,
    // more strongly as the stream progresses.
    if bin_residual == bin_capacity {
        score += 8.0 + 25.0 * progress;
        // But if the item is large, a fresh bin is often correct.
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Room for the next item too — make new bin more attractive.
            score -= 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base score.

    // Aggressive 2-step lookahead: strongly reward bins where the leftover
    // after placement exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect chain: post_residual == next_item_size -> huge bonus.
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0;
        }

        // Penalize if next item cannot fit into post_residual while it could
        // have fit if we placed elsewhere (dead space creation).
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual differs from the mean
    // in a useful direction (very full bins are good targets).
    score -= 0.6 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or lookahead suggests a better use of a fresh bin.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
        let lookahead_bonus = if next_item_size > 0 {
            ((bin_capacity as i64 - next_item_size as i64) - item_size as i64).max(0) as f64 / 100.0
        } else {
            0.0
        };
        score += 20.0 - 10.0 * fit_quality - 15.0 * lookahead_bonus;
    }

    // Late-stream pressure: consolidate more aggressively near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large absolute waste relative to capacity.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // Reward tight fits: small post_residual is good (already in base), but
    // extra reward for near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item (size 1..100).
    // Treat residual < 10 as dead space since typical items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item exactly fills the bin afterwards.
            if post_residual - next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; mild penalty proportional to overflow gap.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.08 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // When many bins fit the item, prefer the one with least waste (already in base),
    // but add mild penalty to discourage spreading across many open bins.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: if mean residual is high, we have slack in the system;
    // penalize opening a new bin when existing bins fit reasonably well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin base cost: opening a bin should carry a fixed penalty.
        score += 30.0;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual;
        // But if few fitting bins and mean residual is small (system nearly full),
        // new bin becomes attractive: reduce penalty.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating: new bins get costlier.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Time horizon: early in the stream, encourage keeping residuals flexible
    // (prefer bins with larger post_residual); late, prefer tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    // Open bins count pressure: many open bins -> favor filling existing ones.
    score += 0.05 * open_bins_count as f64 * (is_new_bin as i32 as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fit preferred, non-linearly scaled
    let mut score = (pr as f64).powf(1.3) / 10.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are more acceptable; later, penalize waste harder.
    let progress_waste = norm_pr * norm_pr * (0.5 + progress) * cap;
    score += 0.02 * progress_waste;

    // Smooth interaction: reward filling bins completely as stream advances
    let fill_reward = (1.0 - norm_pr).powf(2.0) * (1.0 + progress) * 20.0;
    score -= fill_reward;

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let next_fits = (pr - next_item_size as f64).max(0.0);
        let lookahead_bonus = (1.0 - next_fits / cap) * (1.0 - progress) * 8.0;
        if next_item_size as f64 <= pr {
            score -= lookahead_bonus;
        } else {
            score += (next_item_size as f64 - pr) * 0.15;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across too many open bins
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // item granularities are more reusable. Class = post_residual % 10.
    let pr = post_residual;
    let class = (pr % 10) as f64;

    // Reward residuals that fall into "harmonic" classes: multiples of 10
    // (class 0) are ideal, small odd remainders are dead space.
    if pr > 0 {
        score -= 30.0 * (1.0 - class / 10.0);
    } else {
        // Perfect closure of a bin is highly desirable.
        score -= 200.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits: reward proportionally to how snugly it fits.
            let snug = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 * snug;
            // Harmonic match: next_item_size leaves a class-0 residual again.
            if (pr - next_item_size) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this bin: penalize wasted potential.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize leaving tiny unusable residuals (< 10, the min item size).
    if pr > 0 && pr < 10 {
        score += 50.0;
    }

    // Early in the stream, prefer spreading into fresh bins slightly less
    // aggressively; late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    // Mild penalty for very tight fits that leave awkward mid-range
    // residuals (harmonic class 5 is worst: only items of size 5-k work,
    // and min size is 10, so class 5 residuals < 15 are dead).
    if pr >= 10 && pr < 20 && pr % 10 == 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Penalize "awkward" residuals: large enough to waste, small enough to rarely fit.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 3.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the next item fits exactly in the post-residual, reward keeping this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item cannot fit in post-residual but could fit elsewhere, mild penalty
    // unless post_residual is still large.
    if next_item_size > post_residual && post_residual < 20 {
        score += 15.0;
    }

    // Open-bin pressure: discourage proliferation of many open bins,
    // but relax pressure as the stream progresses (end-game consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (2.5 - 1.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "straggler" bin; prefer filling it to close it out.
    let residual_gap = mean_residual - post_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.8;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 40 {
            score -= 35.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, opening new bins is less costly than leaving dead space.
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Reward perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if next item fits in the residual after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space: small post_residual that cannot hold the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize waste relative to mean residual across open bins
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave very awkward space
    if bin_residual == bin_capacity {
        let awkward = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = bin_capacity as f64 - 40.0 * awkward - 10.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical items (residual < 10 useless if min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by how many.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: reward bins whose post residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            // Penalize blocking: post residual too small for the next item.
            score += 8.0;
        }
    }

    // Global state: when mean residual is low, conserve open bins' capacity more aggressively.
    let residual_pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 10.0 * residual_pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open/spread (penalize cramming);
    // late in the stream, prioritize consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bins should only win when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when open bins are scarce or item is large.
        let mut new_bin_cost = 22.0;
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // must open
        }
        // Large items consume most of a fresh bin anyway; discount the cost.
        new_bin_cost -= 0.25 * item_size as f64;
        // If many open bins compete, opening new bins is wasteful.
        new_bin_cost += 1.5 * open_bins_count as f64;
        score += new_bin_cost;
    }

    // Slight penalty for very full bins late in the stream to avoid stranding capacity.
    if post_residual == 0 {
        score -= 5.0; // perfect fit is great
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic reward for tight fits (small post_residual).
    let mut score = norm_pr * norm_pr * cap;

    // Cubic coupling with stream progress: late in the stream, dead space is
    // increasingly costly, so amplify the penalty on large residuals.
    score += norm_pr * norm_pr * norm_pr * cap * (1.0 + 2.0 * progress);

    // Interaction between post_residual and mean residual: placing into a bin
    // whose residual deviates strongly from the mean is mildly discouraged,
    // smoothing fragmentation across bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev.abs() * (1.0 + norm_pr);

    // Lookahead: if the next item can still fit into post_residual, reward
    // this placement (subtract); otherwise penalize slightly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= (ni / cap) * 8.0 * (1.0 - progress);
        } else {
            score += (ni / cap) * 5.0 * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly reward
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is mildly penalized so we
    // prefer existing bins with good fits, but the penalty shrinks as the
    // item is large relative to capacity (a big item "deserves" a fresh bin).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 10.0 * (1.0 - fill_ratio) * (1.0 - 0.3 * progress);
    }

    // Mild penalty for proliferation of open bins, growing with progress.
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartiles
    let q = bin_capacity / 4; // 25
    let class = post_residual % q;
    let class_norm = class as f64 / q as f64;
    score -= 12.0 * (1.0 - class_norm); // reward residuals just below a quartile boundary

    // Integer-division threshold: residuals that form a "half" class are valuable
    let half = bin_capacity / 2;
    if post_residual == half || post_residual == half - 1 {
        score -= 20.0;
    }

    // Perfect tiny residual is dead space: penalize small nonzero leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 55.0 + 40.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight bias toward bins tighter than the mean residual
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are worse than a perfect fit, but a tight fit (post_residual <= 10) is great.
    if post_residual == 0 {
        score -= 25.0; // perfect fit, strongly favored
    } else if post_residual < 10 {
        score += 20.0; // tiny dead space: heavily penalize
    } else if post_residual <= 20 {
        score -= 8.0; // still a good fit
    } else {
        // larger leftover: mild quadratic penalty to prefer tighter fits
        score += 0.02 * (post_residual as f64 - 20.0).powi(2);
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 15.0; // sets up a near-perfect follow-up placement
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // post-residual too small for the lookahead item
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins; when few bins are open, tolerate spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual < bin_capacity {
        score -= pressure * 2.0;
    } else {
        // new-bin candidate: penalize when open-bin pressure is high,
        // reward slightly early in the stream.
        score += pressure * 3.0 - 5.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins with residual near/below the mean
    // (consume the "easiest" space first, keep large residuals flexible).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.1 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful (below min item size 1..~10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2-step lookahead: strongly reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack * 0.5;
        } else {
            // next item cannot follow: penalize leaving a gap smaller than next item
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // prefer bins whose residual stays near/below mean (balanced packing)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild preference for tighter fits among many candidates
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Early in stream: slightly discourage opening many bins; late: encourage consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when no good open option exists
        score += 40.0 * (1.0 - progress) + 10.0;
    }

    // Favor bins with larger residual for large items (avoid fragmentation)
    if item_size > bin_capacity / 2 {
        score += (bin_capacity - bin_residual) as f64 * 0.2;
    }

    score
}
